import re, math, json

class GDALError(Exception):
    def __init__(self, message, code=1, errnum=1, usage_path=None, add_usage=True, stdout=""):
        super().__init__(message)
        self.message = message
        self.code = code
        self.errnum = errnum
        self.usage_path = usage_path
        self.add_usage = add_usage
        self.stdout = stdout

# raw number preserved from parsed JSON strings (projjson etc)
class RawNumber(float):
    def __new__(cls, raw):
        obj = float.__new__(cls, float(raw))
        obj.raw = raw
        return obj

def format_json_float(v):
    if isinstance(v, RawNumber):
        return v.raw
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if math.isnan(v):
        return "null"
    if math.isinf(v):
        return "1e+999" if v>0 else "-1e+999"
    # C %.17g
    s = format(v, '.17g')
    # python .17g may give exponent like 1e+20, fine. It can give '1e-07'
    if re.fullmatch(r'-?\d+', s):
        s += ".0"
    return s

# A wrapper to allow custom formatting for some numbers in json output
class FmtNumber(float):
    def __new__(cls, value, text):
        obj=float.__new__(cls, value)
        obj.text=text
        return obj

def _json_escape(s):
    # GDAL CPLJSON: escape " \ and control chars, presumably like standard
    out=[]
    for ch in s:
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        elif ch=='\b': out.append('\\b')
        elif ch=='\f': out.append('\\f')
        elif ord(ch)<0x20: out.append('\\u%04x'%ord(ch))
        else: out.append(ch)
    return '"' + ''.join(out) + '"'

def gdal_json_dumps(obj, level=0):
    indent='  '*level
    next_indent='  '*(level+1)
    if isinstance(obj, dict):
        if not obj:
            return "{\n"+indent+"}"
        items=[]
        for k,val in obj.items():
            items.append(next_indent+_json_escape(str(k))+":"+gdal_json_dumps(val, level+1))
        return "{\n"+",\n".join(items)+"\n"+indent+"}"
    elif isinstance(obj, (list, tuple)):
        if len(obj)==0:
            return "[\n"+indent+"]"
        items=[next_indent+gdal_json_dumps(v, level+1) for v in obj]
        return "[\n"+",\n".join(items)+"\n"+indent+"]"
    elif isinstance(obj, FmtNumber):
        return obj.text
    elif isinstance(obj, RawNumber):
        return obj.raw
    elif isinstance(obj, bool):
        return "true" if obj else "false"
    elif obj is None:
        return "null"
    elif isinstance(obj, float):
        return format_json_float(obj)
    elif isinstance(obj, int):
        return str(obj)
    else:
        return _json_escape(str(obj))

def _trim_trailing_zeros(s):
    if '.' in s:
        s=s.rstrip('0').rstrip('.')
    return s

def _increment_decimal_prefix(prefix):
    # prefix is fixed point string like -123.456 (no sign handling magnitude)
    sign=''
    if prefix.startswith('-'):
        sign='-'; prefix=prefix[1:]
    if '.' in prefix:
        ip,fp=prefix.split('.')
    else:
        ip,fp=prefix,''
    digits=list(ip+fp)
    i=len(digits)-1
    carry=1
    while i>=0 and carry:
        d=int(digits[i])+carry
        if d==10:
            digits[i]='0'; carry=1
        else:
            digits[i]=str(d); carry=0
        i-=1
    if carry:
        digits.insert(0,'1')
    s=''.join(digits)
    if fp:
        # if carry inserted, integer part grew by 1
        split=len(s)-len(fp)
        s=s[:split]+'.'+s[split:]
    return sign+s

def format_coord(v, decimals=15):
    """GeoJSON coordinate formatting: %.15f trimmed, with snap of 0/9 runs beyond 15 sig figs"""
    if isinstance(v, int):
        # coords stored as float usually
        v=float(v)
    if not math.isfinite(v):
        return format(v, '.15g')
    # For large magnitudes, f-format is what GDAL does (observed 1e20)
    s=format(v, f'.{decimals}f')
    # snap search on untrimmed
    sign=''
    body=s
    if body.startswith('-'):
        sign='-'; body=body[1:]
    if '.' in body:
        ip,fp=body.split('.')
    else:
        ip,fp=body,''
    # significant position calculation: first non-zero digit in ip+fp
    full_digits=ip+fp
    first_sig_idx=None
    for i,ch in enumerate(full_digits):
        if ch!='0':
            first_sig_idx=i; break
    snapped=None
    if first_sig_idx is not None and fp:
        # find runs in fp
        i=0
        while i<len(fp):
            ch=fp[i]
            if ch in '09':
                j=i
                while j<len(fp) and fp[j]==ch:
                    j+=1
                run_len=j-i
                if run_len>=5 and j<len(fp):
                    # position (1-indexed sig) of first digit after run
                    # digit index in full_digits: len(ip)+j
                    sig_pos = (len(ip)+j) - first_sig_idx + 1
                    if sig_pos>15:
                        prefix_ip=ip
                        prefix_fp=fp[:i]
                        prefix=sign+prefix_ip+('.'+prefix_fp if prefix_fp else '')
                        if ch=='9':
                            prefix=_increment_decimal_prefix(prefix)
                            snapped=prefix
                        else:
                            snapped=prefix
                        break
                i=j
            else:
                i+=1
    if snapped is not None:
        s=snapped
    else:
        s=_trim_trailing_zeros(s)
    if '.' not in s:
        s+='.0'
    # handle -0.0 etc already
    return s

def format_coord_number(v):
    # return FmtNumber for JSON features etc where numeric value should use coord formatter
    return FmtNumber(float(v), format_coord(v))

def fmt_geotransform(v):
    # Raster info json geotransform / STAC: attempt %.16f trimmed
    # Use Python repr expanded to fixed when it would be shorter? We'll implement format_coord with 16 decimals
    # but with rules from format_coord it tends to snap some that GDAL does not; accept.
    if v==0:
        return FmtNumber(0.0, "0.0")
    # Use 16 decimal formatting via generic but disable snap by threshold >17? Let's reuse logic with decimals=16 and our snap (sig>15)
    txt=format_coord(v, decimals=16)
    return FmtNumber(float(v), txt)

def fmt_corner(v):
    # CornerCoordinates in raster info json: GDAL seems to round based on a formatting.
    # We will try in info module to pass already rounded values.
    return v

def parse_float_token(s):
    return float(s)

# Formatting for Real feature field in text dumps: %.15g (python lower e)
def fmt_real_text(v):
    if isinstance(v,bool):
        return str(v)
    if isinstance(v,int):
        return str(v)
    if math.isnan(v):
        return "nan"
    if math.isinf(v):
        return "inf" if v>0 else "-inf"
    return format(float(v), '.15g')

# MDV: formatting of metadata statistics values (strings)
def fmt_statistic_string(v):
    if v is None:
        return ""
    if isinstance(v,int):
        return str(v)
    f=float(v)
    if f==int(f) and abs(f)<1e15:
        return str(int(f))
    # Observed: 180.1234567 kept, 1e-07 gives 1e-07, 10 etc. This looks like %.15g ? but 0.300000...
    return format(f, '.15g')

def fmt_double_g(v, precision=15):
    return format(float(v), f'.{precision}g')

# WKT coordinate formatting
def fmt_wkt_coord(v):
    if v==0:
        return "0"
    av=abs(float(v))
    if av>=1e15 or av<1e-15:
        # %.15G
        return format(float(v), '.15G')
    int_digits = len(str(int(av))) if av>=1 else 1
    decimals=max(0, 15-int_digits)
    s=format(float(v), f'.{decimals}f')
    s=_trim_trailing_zeros(s)
    return s

def ensure_list(x):
    return x if isinstance(x,list) else [x]
