        sign='-'; prefix=prefix[1:]
    if '.' in prefix:
        ip,fp=prefix.split('.')
    else:
        ip,fp=prefix,''
    digits=list(ip+fp)
    i=len(digits)-1
    carry=1
    while i>=0 and carry:
        d=int(digits[i])+carry
        if d==10:
            digits[i]='0'; carry=1
        else:
            digits[i]=str(d); carry=0
        i-=1
    if carry:
        digits.insert(0,'1')
    s=''.join(digits)
    if fp:
