    if isinstance(v,int):
        return str(v)
    f=float(v)
    if f==int(f) and abs(f)<1e15:
        return str(int(f))
    # Observed: 180.1234567 kept, 1e-07 gives 1e-07, 10 etc. This looks like %.15g ? but 0.300000...
    return format(f, '.15g')

def fmt_double_g(v, precision=15):
    return format(float(v), f'.{precision}g')

# WKT coordinate formatting
def fmt_wkt_coord(v):
    if v==0:
        return "0"
    av=abs(float(v))
    if av>=1e15 or av<1e-15:
        # %.15G
        return format(float(v), '.15G')
    int_digits = len(str(int(av))) if av>=1 else 1
    decimals=max(0, 15-int_digits)
    s=format(float(v), f'.{decimals}f')
    s=_trim_trailing_zeros(s)
    return s

def ensure_list(x):
    return x if isinstance(x,list) else [x]
