def subcommand_aliases(group_key):
    # returns dict alias -> canonical name (last component)
    nodes=get_nodes()
    node=nodes.get(group_key)
    if not node:
        return {}
    aliasmap={}
    for ln in node.help_text.splitlines():
        m=re.match(r'\s+- ([^:]+):.*\(alias: ([^)]+)\)', ln)
        if m:
            can=m.group(1).strip()
            for al in m.group(2).split(","):
                aliasmap[al.strip()]=can
