def children_of(path_tuple):
    nodes=get_nodes()
    children={}
    plen=len(path_tuple)
    for key,node in nodes.items():
        parts=tuple(key.split())
        if len(parts)==plen+1 and parts[:plen]==path_tuple:
            children[parts[-1]]=parts
    return children
