def edit_distance(a,b):
    if a==b: return 0
    la=len(a); lb=len(b)
    if abs(la-lb)>2:
        # still need exact maybe >2, can return 3
        # compute full if lengths small
        pass
    prev=list(range(lb+1))
    for i,ca in enumerate(a,1):
        cur=[i]+[0]*lb
        for j,cb in enumerate(b,1):
            cur[j]=min(prev[j]+1, cur[j-1]+1, prev[j-1]+(ca!=cb))
        prev=cur
    return prev[lb]

def suggest(name, candidates):
    best=None; bestd=3
    for cand in candidates:
        d=edit_distance(name,cand)
        if d<bestd:
