                if v > spec.max_value:
                    self.error(5, f"Value of argument '{spec.name}' is {self._fmt_num(v)}, but should be <= {self._fmt_num(spec.max_value)}")
            else:
                if v >= spec.max_value:
                    self.error(5, f"Value of argument '{spec.name}' is {self._fmt_num(v)}, but should be < {self._fmt_num(spec.max_value)}")
    def _fmt_num(self,v):
        if isinstance(v,float):
            if v==int(v) and abs(v)<1e15:
                return str(int(v))
            return repr(v)
        return str(v)
    def _check_choices(self, spec, v):
        if spec.choices:
            # special datatype metadata
            md=spec.json.get("metadata",{}) if hasattr(spec,'json') else {}
            types=md.get("type",[]) if isinstance(md,dict) else []
            if "GDALDataType" in types:
                key=v.lower()
                if key in DATATYPE_CANON:
                    return DATATYPE_CANON[key]
                # fall through to invalid
            else:
                for ch in spec.choices:
                    if v.lower()==str(ch).lower():
                        return ch
            choices_str=", ".join(f"'{c}'" for c in spec.choices)
            # This error has no algo prefix and no usage
            raise ParseError(f"ERROR 5: Invalid value '{v}' for string argument '{spec.name}'. Should be one among {choices_str}.\n", code=1, errnum=5, add_usage=False)
        return v
    def convert_list_token(self, spec, raw, arg_display):
        # returns list of converted values from one token (packed splitting)
        t=spec.type
        if raw=="":
            return []
        if spec.packed:
            parts=raw.split(",")
            # For packed string lists, empty parts? keep? GDAL size 4, gave integer list error on whole token.
            # We'll handle conversion below with whole token error formatting for numeric lists
        else:
            parts=[raw]
        out=[]
        if t=="integer_list":
            for p in parts:
                if not re.fullmatch(r'[+-]?\d+', p or ""):
                    self.error(5, f"{self.algo_name}: Expected list of integer value for argument '{arg_display}', but got '{raw}'.")
                v=int(p); self._check_range_each(spec,v); out.append(v)
            return out
        elif t=="real_list":
            for p in parts:
                try:
                    if p.strip()=="": raise ValueError
                    v=float(p)
                except Exception:
                    self.error(5, f"{self.algo_name}: Expected list of real value for argument '{arg_display}', but got '{raw}'.")
                self._check_range_each(spec,v); out.append(v)
            return out
        elif t=="string_list":
            for p in parts:
                out.append(self._check_choices(spec,p))
            return out
        elif t=="dataset_list":
            # packed dataset lists are comma separated (?) spec.packed false usually, parts=[raw]
            return parts
        else:
            return parts
    def _check_range_each(self, spec, v):
        # min/max value in list specs apply to each element (eg size >=0, band >=1)
        self._check_range(spec, v)
    def parse(self, tokens, allow_help=True):
        node=self.node
        parsed=Parsed(node, self.invoked_path)
        # defaults later
        i=0
        positional_raw=[]
        # For duplicate detection, seen_named counts
        named_seen={}
        def mark_specified(canonical, display_for_dup):
            if canonical not in parsed.specified:
                parsed.specified.add(canonical)
                parsed.specified_order.append(canonical)
        def add_value(canonical, value, display, is_named=True):
            spec=node.args[canonical]
            # duplicate handling for named
            if is_named:
                if canonical in named_seen:
                    # if repeated allowed or list with ...? determine
                    if spec.is_list and spec.repeated:
                        pass
                    elif spec.is_list and canonical in ("input",) and spec.type=="dataset_list":
                        # dataset_list input repeated allowed generally (repeated flag often True) handled above
                        pass
                    else:
                        # For list types with repeated=False, duplicate is error (size/bbox)
                        # For list types with no repeated field (None) e.g. ??? treat as duplicate if not list?
                        # dataset_list/input has repeated True in json usually.
                        self.error(5, f"{self.algo_name}: Argument '{display}' has already been specified.")
                named_seen[canonical]=named_seen.get(canonical,0)+1
            # store
            if spec.is_bool:
                parsed.values[canonical]=value
            elif spec.is_list:
                if canonical not in parsed.values:
                    parsed.values[canonical]=[]
                # value here is a list from one token
                parsed.values[canonical].extend(value)
            else:
                parsed.values[canonical]=value
            mark_specified(canonical, display)
        # main scan
        while i<len(tokens):
            tok=tokens[i]
            # token is "--" etc handled as option
            if tok=="--" or tok.startswith("--"):
                # long option
                if "=" in tok:
                    name_token, eq_value = tok.split("=",1)
                    has_eq=True
                else:
                    name_token=tok; eq_value=None; has_eq=False
                canonical=node.alias_map.get(name_token)
                if canonical is None:
                    # unknown long option
                    cand_names=[al[2:] for al in node.alias_map.keys() if al.startswith("--")]
                    # preserve order as appears in alias_map insertion (help order approximated by args parsing order)
                    sug=suggest(name_token[2:], cand_names)
                    if sug:
                        raise ParseError(f"ERROR 5: {self.algo_name}: Option '{name_token}' is unknown. Do you mean '--{sug}'?\n", code=1, errnum=5, add_usage=False)
                    else:
                        self.error(5, f"{self.algo_name}: Option '{name_token}' is unknown.")
                spec=node.args[canonical]
                display=name_token  # for errors, long retains --
                if spec.is_bool:
                    if has_eq:
                        if eq_value=="":
                            val=True
                        elif eq_value=="true":
                            val=True
                        elif eq_value=="false":
                            val=False
                        else:
                            self.error(5, f"{self.algo_name}: Invalid value '{eq_value}' for boolean argument '{name_token}'. Should be 'true' or 'false'.")
                    else:
                        val=True
                    # duplicate check inside add_value; bool repeated false
                    add_value(canonical, val, display, is_named=True)
                    i+=1
                    continue
                else:
                    if has_eq:
                        raw=eq_value
                        i+=1
                    else:
                        if i+1>=len(tokens):
                            self.error(5, f"{self.algo_name}: Expected value for argument '{name_token}', but ran short of tokens")
                        raw=tokens[i+1]; i+=2
                    # config via equals tracking (only if has_eq and canonical config)
                    if canonical=="config" and has_eq:
                        parsed.config_equals.append(raw)
                    if spec.is_list:
                        vals=self.convert_list_token(spec, raw, display)
                        add_value(canonical, vals, display, is_named=True)
                    else:
                        v=self.convert_single(spec, raw, display)
                        add_value(canonical, v, display, is_named=True)
                    continue
            elif tok.startswith("-") and tok!="-" and not _is_negative_number(tok):
                # short options sequence
                # Special: if whole tok[1:] matches a long alias name exactly and first char unknown handled in loop
                chars=tok[1:]
                pos=0
                consumed_next=False
                while pos<len(chars):
                    ch=chars[pos]
                    token_short="-"+ch
                    canonical=node.alias_map.get(token_short)
                    if canonical is None:
                        # check special whole-token long match
                        long_names=[al[2:] for al in node.alias_map.keys() if al.startswith("--")]
                        if chars in long_names:
                            raise ParseError(f"ERROR 5: {self.algo_name}: Short name option '{ch}' is unknown. Do you mean '--{chars}' (with leading double dash) ?\n", code=1, errnum=5, add_usage=False)
                        self.error(5, f"{self.algo_name}: Short name option '{ch}' is unknown.")
                    spec=node.args[canonical]
                    if spec.is_bool:
                        add_value(canonical, True, ch, is_named=True)
                        pos+=1
                        continue
                    else:
                        # non-boolean short must be alone in token (pos==len-1 and only one char? Actually if chars after this char, invalid argument)
                        if pos != len(chars)-1:
                            self.error(5, f"{self.algo_name}: Invalid argument '-{chars}'. Option '{ch}' is not a boolean option.")
                        # Also if preceding boolean chars existed, e.g. -qo, the error above triggers because pos (1)?? -qo: q at pos0 bool, o pos1 is len-1 => above wouldn't trigger, but original reports Invalid argument '-qo'. Option 'o' is not a boolean option.
                        if pos>0:
                            self.error(5, f"{self.algo_name}: Invalid argument '-{chars}'. Option '{ch}' is not a boolean option.")
                        if i+1>=len(tokens):
                            self.error(5, f"{self.algo_name}: Expected value for argument '{ch}', but ran short of tokens")
                        raw=tokens[i+1]; consumed_next=True
                        if spec.is_list:
                            vals=self.convert_list_token(spec, raw, ch)
                            add_value(canonical, vals, ch, is_named=True)
                        else:
                            v=self.convert_single(spec, raw, ch)
                            add_value(canonical, v, ch, is_named=True)
                        pos+=1
                        break
                i+= 2 if consumed_next else 1
                continue
            else:
                positional_raw.append(tok)
                i+=1
                continue
        parsed.positional_tokens=positional_raw[:]
        # If help or json-usage specified (true), return early without positional/required validation (caller will handle)
        if allow_help and (parsed.values.get("help") is True or parsed.values.get("json-usage") is True):
            self._apply_defaults(parsed)
            return parsed
        # Mutual exclusion check: need during scan? Original message order: when second mutually exclusive specified, error at that point before other validations like missing input file etc.
        # Our post check may differ in cases where also other errors, but acceptable. However do it before positional assignment to match examples where mutual flags + missing file? Original raster info --stats --approx-stats file: mutual error.
        self._check_mutual(parsed)
        # Positional assignment
        self._assign_positionals(parsed, positional_raw, add_value, named_seen)
        # Count validation for lists and required checks
        self._validate_counts_and_required(parsed)
        self._apply_defaults(parsed)
        return parsed
    def _check_mutual(self, parsed):
        groups={}
        # Build in order specified
        for can in parsed.specified_order:
            spec=self.node.args.get(can)
            if spec and spec.mutual:
                g=spec.mutual
                if g in groups and groups[g]!=can:
                    self.error(1, f"{self.algo_name}: Argument '{can}' is mutually exclusive with '{groups[g]}'.")
                groups[g]=can
        # Also some mutual exclusions are documented in help but not via same group? json should capture.
    def _assign_positionals(self, parsed, positional_raw, add_value, named_seen):
        node=self.node
        if not node.positional:
            if positional_raw:
                self.error(1, f"{self.algo_name}: Positional values starting at '{positional_raw[0]}' are not expected.")
            return
        # Slots are positional canonicals in order, skipping those already specified by name AND not list-expandable?
        # For list positional slots (input list), named values are merged and positional values can still be added if slot is list with variable max.
        # Determine slot handling algorithm:
        # Cases:
        # - Single/list slot is last and only slot (vector info input list): all positional go to it (merge with named)
        # - List slot followed by other slots (mosaic inputs..., output): last slot gets final token, preceding tokens go to list slot (if list slot not already named filled? if named filled, positional tokens assignment shifts?)
        # - Fixed slots: tokens fill in order skipping named-filled fixed slots.
        #
        # Implement generic allocation:
        slots=node.positional[:]
        # Special C algorithms (Not enough positional values) set
        not_enough_algos={("gdal","raster","blend"),("gdal","raster","pansharpen"),("gdal","vector","buffer"),("gdal","vector","segmentize"),("gdal","vector","simplify"),("gdal","vector","simplify-coverage")}
        is_not_enough = tuple(node.path) in not_enough_algos
        # Identify variable list slots (max_count >1 or unlimited)
        # If there is a variable slot not at end:
        var_idx=None
        for idx,can in enumerate(slots):
            spec=node.args[can]
            if spec.is_list and (spec.max_count is None or spec.max_count>1):
                # but many input dataset_list have max_count=1 though usage not ...; mosaic max is inf
                var_idx=idx
                break
        # If positional tokens and a var slot exists:
        if var_idx is not None:
            # Number of fixed slots after var
            after=slots[var_idx+1:]
            before=slots[:var_idx]
            # Fixed slots before var that are not named-filled need tokens first, after slots need tokens from end.
            # Simpler allocation inspired by GDAL: tokens are assigned from the end for after slots if var slot is list?
            # Observed footprint [input(list), output]: 1 token -> output, 2-> input+output, 3-> inputs (2)+output
            # Pansharpen [input(1), spectral(list), output]: first token input, last output, middle spectral
            # Allocation:
            tokens=positional_raw[:]
            # Before slots: assign in order skipping named filled (fixed)
            # Determine named filled status
            def named_filled(can):
                return can in parsed.specified and not (node.args[can].is_list and (node.args[can].max_count is None or node.args[can].max_count>1))
            # We'll allocate using indices
            # First, before fixed
            assignments={}  # can -> list of raw tokens
            # Use pointer from start and end
            start=0; end=len(tokens)  # exclusive
            for can in before:
                if named_filled(can):
                    continue
                if start<end:
                    assignments.setdefault(can,[]).append(tokens[start]); start+=1
            for can in reversed(after):
                if named_filled(can):
                    continue
                if start<end:
                    assignments.setdefault(can,[]).append(tokens[end-1]); end-=1
            # remaining middle tokens go to var slot
            middle=tokens[start:end]
            if middle:
                assignments.setdefault(slots[var_idx],[]).extend(middle)
            # Now add values in slot order, converting types
            for can in slots:
                if can in assignments:
                    for raw in assignments[can]:
                        self._add_positional_value(parsed, can, raw, add_value)
            return
        # No variable slot: fixed slots (some may be list max1)
        # Remaining slots = slots not named-filled. For list slots with max1 and named-filled, a positional token allocated to it would merge and later count error (raster info -i a b -> 2 values for input).
        # GDAL behavior for raster info: named input a + positional b merges into input list (count error), not skip. For vector convert -o out a : positional a goes to input (output filled skipped, not merge). Difference: input is dataset_list (even max1) - positional tokens are always added to list slot if it is first remaining? Hmm.
        # Rules observed:
        # - raster create -o out a: output is dataset (not list) named filled, a -> no slot, overflow "Positional values starting at a are not expected" (skip behaviour)
        # - raster info -i a b: input is dataset_list max1 named filled, b merges -> count error
        # - vector buffer -o out a b 1: remaining slots are [input(list max1), distance]; a->input, b->distance. Output skipped.
        # - vector convert -i a out(positional): input list named a, positional out -> ??? It would merge into input giving input=[a,out], output missing -> count error?? Let's assume GDAL assigns positional token to next slot starting from first slot regardless of named for list slots. Test knowledge: vector convert -i a -i b out gave count error "3 values for argument input" - that suggests positional 'out' merged into input (3rd), not assigned to output. Yes!
        # So for list-type slots, positional tokens are consumed by that slot until?? But then how does a normal convert a b ever assign b to output if input is a list slot (max1)? Because GDAL knows positional count: With 2 positional tokens and 2 slots, it distributes 1 each. With named input already, positional token count 1 and slots (input,output): if input named, remaining required slot is output, but experiment -i a -i b out showed input got 3 values. Wait that experiment had TWO named inputs a,b plus positional out = total input values if positional assigned to output would be input=2, output=out, count error should be "2 values for input". Actual was 3, so positional assigned to input. That suggests positional tokens are appended to the FIRST positional slot if that slot is a list, regardless named - but then normal a b would both go to input... unless allocation is determined *by total positional token count and fixed slots after list*: Input list in convert is max1, so it's not variable; allocation with 2 tokens to 2 fixed slots works. With named inputs already, number of positional tokens is 1, slots are 2, allocation from the *end*? That would assign out to output, not input.
        # Alternative explanation: -i a -i b out : The parser treats successive -i options as *positional*? No.
        # Let's not overfit that edge: Implement allocation as: slots in order, assign positional tokens one per slot, skipping slots that are non-list and named-filled; for list slots, if named-filled and max_count==1, assign positional token to it as well ONLY if it's the first slot and there are no other unfilled slots earlier? That is messy.
        #
        # Practical allocation for common cases (no named positional duplicates):
        remaining=[]
        for can in slots:
            spec=node.args[can]
            if can in parsed.specified and not spec.is_list:
                continue
            # For list max1 named filled: keep slot in remaining if positional tokens would overflow otherwise? We'll handle by: if named and there are positional tokens, we will first try assigning to unfilled slots; if all positional assigned and any leftover, assign leftover to first list slot (to trigger count error)
            if can in parsed.specified and spec.is_list:
                continue
            remaining.append(can)
        tokens=positional_raw[:]
        # Not enough handling for C algos: if total assigned (named positional slots + tokens) < number of required positional slots, error Not enough later in validate (but original gives that instead of positional starting)
        # Assign token i to remaining i
        overflow=[]
        for idx,raw in enumerate(tokens):
            if idx < len(remaining):
                can=remaining[idx]
                self._add_positional_value(parsed, can, raw, add_value)
            else:
                overflow.append(raw)
        if overflow:
            # If there's a list slot (max1) that was named or first slot is list, original may merge overflow into it and produce count error in some cases (raster info -i a b: remaining is [] because input named skipped, overflow b should merge to input)
            # Detect: if a positional slot is a list and total tokens overflow because that slot was named, merge overflow to that list slot instead of generic overflow, so count validation triggers.
            list_slots=[c for c in slots if node.args[c].is_list]
            if list_slots and len(tokens)>0 and any(c in parsed.specified for c in list_slots) and not remaining:
                # raster info case: only slot is input list named, positional b merges
                for raw in overflow:
                    self._add_positional_value(parsed, list_slots[0], raw, add_value)
                return
            if list_slots and tokens and len(remaining)>0 and len(tokens)>len(remaining):
                # e.g. vector convert -i a -i b out: remaining=[output], tokens=[out] actually not overflow... our remaining skip list named results tokens assign to output, giving count 2 for input, which will error count 2 not 3 - acceptable difference.
                pass
            if is_not_enough and len(slots)>=2:
                # original: Argument '<second slot>' has already been specified (ERROR 5)
                second=slots[1]
                self.error(5, f"{self.algo_name}: Argument '{second}' has already been specified.")
            self.error(1, f"{self.algo_name}: Positional values starting at '{overflow[0]}' are not expected.")
    def _add_positional_value(self, parsed, canonical, raw, add_value):
        spec=self.node.args[canonical]
        # display for type errors for positional real etc: original uses canonical name without dashes e.g. argument 'distance'
        if spec.is_list:
            # positional token is a single value, NOT packed split? For dataset_list token may be "a", keep one.
            # For numeric list positional (unlikely) token could be packed?
            if spec.type in ("integer_list","real_list","string_list"):
                vals=self.convert_list_token(spec, raw, canonical)
            else:
                vals=[raw]
            # add without duplicate named check
            if canonical not in parsed.values:
                parsed.values[canonical]=[]
            parsed.values[canonical].extend(vals)
            if canonical not in parsed.specified:
                parsed.specified.add(canonical); parsed.specified_order.append(canonical)
        elif spec.is_bool:
            parsed.values[canonical]=True
            if canonical not in parsed.specified:
                parsed.specified.add(canonical); parsed.specified_order.append(canonical)
        else:
            v=self.convert_single(spec, raw, canonical)
            parsed.values[canonical]=v
            if canonical not in parsed.specified:
                parsed.specified.add(canonical); parsed.specified_order.append(canonical)
    def _validate_counts_and_required(self, parsed):
        node=self.node
        not_enough_algos={("gdal","raster","blend"),("gdal","raster","pansharpen"),("gdal","vector","buffer"),("gdal","vector","segmentize"),("gdal","vector","simplify"),("gdal","vector","simplify-coverage")}
        is_not_enough=tuple(node.path) in not_enough_algos
        # If no positional tokens were supplied at all and first positional slot exists and not specified, original many give Positional arguments starting at '<METAVAR>'
        # Decision logic based on captured noargs pattern:
        # - For B-type (first positional is list with min_count==0): skip positional starting, go to required list.
        # - For C-type: if any required positional missing -> Not enough
        # - Else if a positional slot is missing (required) and ... ->
        # We need decide when some positional tokens supplied but not enough: e.g. vector convert onlyone -> Positional starting at OUTPUT
        # For mosaic (inputs list min1, output) 1 token -> Required argument 'input' (because token assigned to output)
        #
        # First handle C-type:
        missing_positional=[can for can in node.positional if can not in parsed.specified and node.args[can].required]
        if is_not_enough and missing_positional:
            self.error(1, f"{self.algo_name}: Not enough positional values.")
        # Determine B-type
        def is_b_type():
            if not node.positional:
                return False
            first=node.args[node.positional[0]]
            return first.is_list and (first.min_count==0)
        # Count errors for list args specified (including named)
        # Original count validation happens before required positional starting? Example raster create --size 4 (one value) with output positional present -> count error for size.
        # Example raster info -i a -i b -> count error for input
        for can in parsed.specified_order:
            spec=node.args.get(can)
            if spec and spec.is_list and can not in ("config",):
                vals=parsed.values.get(can,[])
                cnt=len(vals)
                if spec.min_count is not None and spec.max_count is not None and spec.min_count==spec.max_count and cnt!=spec.min_count:
                    # Only if spec was specified (it was) - for size exactly 2, bbox exactly 4, input exactly 1
                    # But what if positional token assigned only partly? e.g. ?? still.
                    word="value" if cnt<=1 else "values"
                    # original: "1 value has been specified" , "2 values have been specified", "0 value has been specified"
                    verb="has" if cnt<=1 else "have"
                    self.error(1, f"{self.algo_name}: {cnt} {word} {verb} been specified for argument '{can}', whereas exactly {spec.min_count} {'was' if spec.min_count==1 else 'were'} expected.")
                if spec.max_count is not None and spec.max_count!=2147483647 and cnt>spec.max_count and not (spec.min_count==spec.max_count):
                    word="values"
                    self.error(1, f"{self.algo_name}: {cnt} values have been specified for argument '{can}', whereas at most {spec.max_count} were expected.")
                if spec.min_count is not None and cnt>0 and cnt<spec.min_count and not (spec.min_count==spec.max_count):
                    # e.g. list requiring at least 2 but got 1 via named: unknown wording; use exactly-like?
                    pass
        # Positional starting errors:
        if missing_positional and not is_b_type():
            # But if missing positional is due to variable list assignment (mosaic 1 token -> input missing), first.is_list min_count=1 not b-type, original for 1 token gave Required argument 'input', not Positional starting.
            # Heuristic: if positional tokens were supplied (>=1) and first positional is variable list with following output slot, then missing gives Required argument.
            first_can=node.positional[0] if node.positional else None
            first=node.args[first_can] if first_can else None
            variable_first = first and first.is_list and (first.max_count is None or first.max_count>1)
            if variable_first and len(parsed.positional_tokens)>=1:
                pass # fall through to required
            else:
                can=missing_positional[0]
                metavar=node.positional_metavars.get(can) or node.args[can].metavar or can.upper()
                # metavar may include <> in json? strip
                metavar_str=str(metavar).strip("<>")
                # for pixel-info position, metavar weird but okay
                self.error(1, f"{self.algo_name}: Positional arguments starting at '{metavar_str}' have not been specified.")
        # Required arguments (all) in some order: Original prints multiple required errors (for B-type) then usage.
        missing_required=[]
        # Order: Positional order first, then other required args in ??? json order? For footprint: input, output.
        ordered=[]
        for can in node.positional:
            if can not in ordered: ordered.append(can)
        for can,spec in node.args.items():
            if can not in ordered: ordered.append(can)
        for can in ordered:
            spec=node.args.get(can)
            if spec and spec.required and can not in parsed.specified:
                missing_required.append(can)
        if missing_required:
            # If we are here, either b-type or non-positional required or variable case.
            lines="".join([f"ERROR 1: {self.algo_name}: Required argument '{can}' has not been specified.\n" for can in missing_required])
            raise ParseError(lines+self.usage_appendix(), code=1, errnum=1, add_usage=False)
    def _apply_defaults(self, parsed):
        for can,spec in self.node.args.items():
            if can in parsed.specified:
                continue
            if spec.default is not None:
                d=spec.default
                # convert default based on type
                if spec.type=="integer":
                    try: v=int(d)
                    except: v=d
                elif spec.type=="real":
                    try: v=float(d)
                    except: v=d
                elif spec.type=="boolean":
                    v=bool(d) if isinstance(d,bool) else str(d).lower()=="true"
                elif spec.is_list:
                    v=d if isinstance(d,list) else [d]
                else:
                    v=d
                    if spec.choices:
                        # normalize case
                        for ch in spec.choices:
