            steps=[self.algo_name]
        for s in steps:
            eprint(f"Warning 1: {s}: Configuration options passed with the 'config' argument are ignored\n")

def get_handler(path_tuple):
    # lazy import operations registry
    try:
        import operations
        return operations.HANDLERS.get(tuple(path_tuple))
    except Exception as e:
        # during development, let it propagate as internal? return None
        # store exc for debugging when handler missing
        # print to stderr in dev? Keep silent in production fallback
        get_handler._exc=e
        return None

def dispatch_leaf(path_tuple, invoked_path, tokens):
    node=get_node(path_tuple)
    invoked_path=tuple(invoked_path)
    is_tile = tuple(path_tuple)==("gdal","raster","tile")
    tile_warned=False
    if is_tile:
        w=tms_warnings(1)
        if w:
            eprint(w); tile_warned=True
    # pipelines special
    if path_tuple[-1]=="pipeline" or tuple(path_tuple)==("gdal","pipeline"):
        import pipeline as pipemod
        return pipemod.run_pipeline(path_tuple, invoked_path, tokens, node)
    parser=ArgParser(node, invoked_path)
    parsed=parser.parse(tokens)
    # help / json usage
    if parsed.values.get("help") is True:
        if not tile_warned:
            cnt=_warning_count(node.help_stderr)
            if cnt: eprint(tms_warnings(cnt))
        sys.stdout.write(node.help_for_invocation(invoked_path))
        return 0
    if parsed.values.get("json-usage") is True:
        if not tile_warned:
            cnt=_warning_count(node.json_usage_stderr)
            if cnt: eprint(tms_warnings(cnt))
        sys.stdout.write(node.json_usage_text)
        return 0
    # If help/json explicitly false via = , original weird for raster info etc. Ignore for now.
    handler=get_handler(path_tuple)
    call=Call(parsed, node, invoked_path)
    if handler is None:
        # Check if this is a GEOS-only algo list later; for now generic run error
        # To avoid silent success in tests for unimplemented, emit a plausible error? Better raise run error indicating not implemented (?) will fail tests anyway.
        raise ParseError(f"ERROR 1: {node.path[-1]}: Not implemented\n", code=1)
    return handler(call)

def dispatch_group(path_tuple, invoked_path, tokens):
    node=get_node(path_tuple)
    invoked_path=tuple(invoked_path)
    # group internal options iter until first positional
    flags={}
    specified=set()
    config_equals=[]
    i=0
    first_pos_idx=None
    while i<len(tokens):
        tok=tokens[i]
        if tok.startswith("--"):
            if "=" in tok:
                name_tok, eqv=tok.split("=",1); has_eq=True
            else:
                name_tok=tok; eqv=None; has_eq=False
            can=node.alias_map.get(name_tok)
            if can is None:
                cand=[al[2:] for al in node.alias_map.keys() if al.startswith("--")]
                sug=suggest(name_tok[2:], cand)
                if sug:
                    raise ParseError(f"ERROR 5: {node.path[-1]}: Option '{name_tok}' is unknown. Do you mean '--{sug}'?\n", code=1, errnum=5)
                group_error(node, invoked_path, f"{node.path[-1]}: Option '{name_tok}' is unknown.", errnum=5)
            speca=node.args.get(can)
            if speca and speca.is_bool:
                if has_eq:
                    if eqv=="": val=True
                    elif eqv=="true": val=True
                    elif eqv=="false": val=False
                    else:
                        # generic error with group usage? use leaf style?
                        group_error(node, invoked_path, f"{node.path[-1]}: Invalid value '{eqv}' for boolean argument '{name_tok}'. Should be 'true' or 'false'.", errnum=5)
                else:
                    val=True
                flags[can]=val; specified.add(can); i+=1; continue
            else:
                # non bool group option (config)
                if has_eq:
                    raw=eqv; i+=1
                else:
                    if i+1>=len(tokens):
                        group_error(node, invoked_path, f"{node.path[-1]}: Expected value for argument '{name_tok}', but ran short of tokens", errnum=5)
                    raw=tokens[i+1]; i+=2
                if can=="config" and has_eq:
                    config_equals.append(raw)
                flags[can]=raw; specified.add(can); continue
        elif tok.startswith("-") and tok!="-":
            # short options
            chars=tok[1:]
            consumed=False
            for pos,ch in enumerate(chars):
                can=node.alias_map.get("-"+ch)
                if can is None:
                    long_names=[al[2:] for al in node.alias_map.keys() if al.startswith("--")]
                    if chars in long_names:
                        raise ParseError(f"ERROR 5: {node.path[-1]}: Short name option '{ch}' is unknown. Do you mean '--{chars}' (with leading double dash) ?\n", code=1, errnum=5)
                    group_error(node, invoked_path, f"{node.path[-1]}: Short name option '{ch}' is unknown.", errnum=5)
                speca=node.args.get(can)
                if speca and speca.is_bool:
                    flags[can]=True; specified.add(can)
                else:
                    group_error(node, invoked_path, f"{node.path[-1]}: Short name option '{ch}' is unknown.", errnum=5)
            i+=1; continue
        else:
            first_pos_idx=i; break
    remaining=tokens[first_pos_idx:] if first_pos_idx is not None else []
    # config= warnings for group terminal actions handled below (drivers/help etc mostly no warning? drivers gave warning gdal once)
    # Help priority
    if flags.get("help") is True:
        if config_equals:
            # --config=... --help at group? unknown; ignore
            pass
        cnt=_warning_count(node.help_stderr)
        if cnt: eprint(tms_warnings(cnt))
        sys.stdout.write(node.help_for_invocation(invoked_path))
        return 0
    if flags.get("json-usage") is True:
        cnt=_warning_count(node.json_usage_stderr)
        if cnt: eprint(tms_warnings(cnt))
        sys.stdout.write(node.json_usage_text)
        return 0
    if "drivers" in specified:
        if flags.get("drivers") is True:
            if remaining:
                group_error(node, invoked_path, f"{node.path[-1]}: Positional values starting at '{remaining[0]}' are not expected.", errnum=1)
            if config_equals:
                eprint(f"Warning 1: {node.path[-1]}: Configuration options passed with the 'config' argument are ignored\n")
            eprint(tms_warnings(1))
            scope=None
            if path_tuple==("gdal","raster"): scope="raster"
            elif path_tuple==("gdal","vector"): scope="vector"
            elif path_tuple==("gdal","mdim"): scope="mdim"
            sys.stdout.write(drivermod.drivers_json(scope))
            return 0
        elif flags.get("drivers") is False:
            if remaining:
                # fall through to dispatch? Unlikely
                pass
            else:
                if path_tuple==("gdal",):
                    return 0
                raise ParseError(f"ERROR 1: The Run() method should not be called directly on the \"{' '.join(path_tuple)}\" program.\n", code=1)
    if "version" in specified:
        # exact --version already handled globally; this is = form mainly
        if not remaining:
            return 0
        # if remaining, original weird fallback; fall through
    if not remaining:
        missing_word="Missing command name." if path_tuple==("gdal",) else "Missing subcommand name."
        group_error(node, invoked_path, f"{node.path[-1]}: {missing_word}", errnum=1)
    cmd=remaining[0]
    rest=remaining[1:]
    children=children_of(path_tuple)
    aliases=subcommand_aliases(" ".join(path_tuple))
    # root special children convert/info are in children
    if cmd in children:
        child_path=children[cmd]
        child_invoked=invoked_path+(cmd,)
        child_node=get_node(child_path)
        if child_node.is_group or child_path[-1] in ("overview","grid","sozip","cog","dataset","driver","mdim","raster","vector","vsi") and children_of(child_path):
            return dispatch_group(child_path, child_invoked, rest)
        else:
            # if child has children treat as group
            if children_of(child_path):
                return dispatch_group(child_path, child_invoked, rest)
            return dispatch_leaf(child_path, child_invoked, rest)
    if cmd in aliases:
        can=aliases[cmd]
        child_path=path_tuple+(can,)
        child_invoked=invoked_path+(cmd,)
        if children_of(child_path):
            return dispatch_group(child_path, child_invoked, rest)
        return dispatch_leaf(child_path, child_invoked, rest)
    # suggestion
    sug=suggest(cmd, list(children.keys()))
    if sug:
        raise ParseError(f"ERROR 1: Algorithm '{cmd}' is unknown. Do you mean '{sug}'?\n", code=1)
    if path_tuple==("gdal",):
        # root shortcuts
        return root_fallback(cmd, rest, tokens)
    group_error(node, invoked_path, f"{node.path[-1]}: Unknown command: '{cmd}'", errnum=1)

def root_fallback(cmd, rest, original_tokens):
    # cmd is first positional token, rest are remaining tokens after it,
    # but original_tokens may include group options before cmd (e.g. --format json file) where cmd would be value of --format? Our group parser would have rejected --format as unknown before reaching here in some cases.
    # This is called only when cmd not matched and no group options consumed beyond possibly help etc.
    # Case: read pipeline shortcut
    if cmd=="read":
        # Try pipeline with steps starting read
        # If no rest, unknown command ( handled below)
        if rest:
            import pipeline as pipemod
            try:
                return pipemod.run_root_read(rest)
            except ParseError as ex:
                # original prints first error line(s) from pipeline/read attempt, then root unknown
                # ex.message may include usage appendix for pipeline; we need strip usage? For read nonexistent, ex message should be just ERROR4...
                # If ex has a marker attribute root_fallback_msg use it
                msg=getattr(ex,"message","") or str(ex)
                # Take lines until a Usage: line
                lines=[]
                for ln in msg.splitlines(True):
                    if ln.startswith("Usage:"):
                        break
                    lines.append(ln)
                prefix="".join(lines)
                node=get_node(("gdal",))
                raise ParseError(prefix+f"ERROR 1: gdal: Unknown command: 'read'\n"+_root_group_usage_after_first(), code=1)
        # fall through unknown
    # Case: existing file -> info shortcut with all tokens as info args (cmd + rest)
    # To decide, check if file exists via VSI path handling (local file or /vsimem etc) - simple os.path.exists or special prefixes
    if _dataset_exists(cmd):
        # Invoke gdal info leaf with tokens = [cmd]+rest , but need include any info options that appeared before cmd in original_tokens? root_fallback loses those; group dispatch would have errored on --format before. For file-first case it's fine.
        try:
            return dispatch_leaf(("gdal","info"), ("gdal","info"), [cmd]+list(rest))
        except ParseError as ex:
            msg=getattr(ex,"message","") or str(ex)
            # If info succeeded parse but failed run due to file open etc, original for valid files would succeed. For errors like unknown option/extra positional, original prints first error line from info then root unknown.
            # Distinguish parse errors: if msg contains Usage: gdal info, it's a parse error from info leaf.
            if "Usage: gdal info" in msg or "ERROR 5:" in msg or "Positional values" in msg:
                lines=[]
                for ln in msg.splitlines(True):
                    if ln.startswith("Usage:"):
                        break
                    lines.append(ln)
                prefix="".join(lines)
                # Original weird extra positional case reports filename as not expected - our info will report extra token, not filename; accept.
                raise ParseError(prefix+f"ERROR 1: gdal: Unknown command: '{cmd}'\n"+_root_group_usage_after_first(), code=1)
            raise
    node=get_node(("gdal",))
    group_error(node, ("gdal",), f"gdal: Unknown command: '{cmd}'", errnum=1)

def _root_group_usage_after_first():
    node=get_node(("gdal",))
    return group_error_usage(node, ("gdal",))

def _dataset_exists(path):
    if os.path.exists(path):
        return True
    # GDAL virtual files / network etc.
    if path.startswith("/vsi") or path.startswith("http://") or path.startswith("https://") or ":" in path[:20]:
        # let info handler attempt and produce own errors?
        return False
    return False

def load_text_data(rel):
    return specmod.load_data(rel).decode("utf-8")

def preprocess(argv):
    """returns (cleaned_argv, exit_code_or_None) handling generic options sequentially"""
    clean=[]
    i=0
    # Use a mutable list as queue for optfile expansion
    queue=list(argv)
    idx=0
    while idx<len(queue):
        tok=queue[idx]
        if tok=="--config":
            if idx+1>=len(queue):
                eprint("ERROR 1: --config option given without a key=value argument.\n")
                return None,1
            nxt=queue[idx+1]
            if "=" in nxt:
                k,v=nxt.split("=",1)
                CTX.config[k.strip()]=v.strip() if False else v
                # key strip spaces as in "FOO =bar" maybe k contains spaces; strip them
                CTX.config[k.strip()]=v
                idx+=2; continue
            else:
                if idx+2>=len(queue):
                    eprint("ERROR 1: --config option given without a key and value argument.\nERROR 1: --config option given without a key and value argument.\n")
                    return None,1
                CTX.config[nxt]=queue[idx+2]
                idx+=3; continue
        elif tok=="--version":
            sys.stdout.write(VERSION_STRING+"\n"); return None,0
        elif tok=="--formats":
            eprint(tms_warnings(1))
            sys.stdout.write(load_text_data("data/formats.txt")); return None,0
        elif tok=="--license":
            sys.stdout.write(load_text_data("data/license.txt")); return None,0
        elif tok=="--help-general":
            sys.stdout.write(load_text_data("data/help_general.txt")); return None,0
        elif tok=="--build":
            sys.stdout.write(BUILD_TEXT); return None,0
        elif tok=="--debug":
            if idx+1>=len(queue):
                eprint("ERROR 1: --debug option given without debug level.\n"); return None,1
            CTX.debug=queue[idx+1]; idx+=2; continue
        elif tok=="--optfile":
            if idx+1>=len(queue):
                eprint("ERROR 1: --optfile option given without filename.\n"); return None,1
            fn=queue[idx+1]
            try:
                with open(fn,"r") as f:
                    content=f.read()
            except OSError:
                eprint(f"ERROR 1: Unable to open optfile '{fn}'.\nNo such file or directory\n"); return None,1
            # GDAL optfile: lines, # comments, tokens (?) Use shlex split with comments
            expanded=[]
            for line in content.splitlines():
                line=line.strip()
                if not line or line.startswith("#"):
                    continue
                try:
                    expanded.extend(shlex.split(line))
                except Exception:
                    expanded.extend(line.split())
            # Insert expanded after current position, skip optfile tokens
            queue = queue[:idx] + expanded + queue[idx+2:]
            continue
        elif tok=="--pause":
            sys.stdout.write("Hit <ENTER> to Continue.\n"); sys.stdout.flush()
            try:
                sys.stdin.readline()
            except Exception:
                pass
            idx+=1; continue
        elif tok=="--mempreload":
            if idx+1>=len(queue):
                eprint("ERROR 1: --mempreload option given without directory path.\n"); return None,1
            dirpath=queue[idx+1]
            if not os.path.isdir(dirpath):
                eprint("ERROR 1: --mempreload given invalid or empty directory.\n"); return None,1
            # Empty dir?
            entries=[]
            try:
                entries=sorted(os.listdir(dirpath))
            except Exception:
                entries=[]
            if not entries:
                eprint("ERROR 1: --mempreload given invalid or empty directory.\n"); return None,1
            # Copy files into /vsimem via vfs module if available
            try:
                import vfs as vfsmod
                for name in entries:
                    full=os.path.join(dirpath,name)
                    if os.path.isdir(full):
                        continue
                    try:
                        with open(full,"rb") as f:
                            data=f.read()
                    except Exception:
                        eprint(f"ERROR 3: Cannot open {full}\nERROR 1: Failed to copy {full} to /vsimem\n"); return None,1
                    vfsmod.MEMFS["/vsimem/"+name]=data
            except ImportError:
                pass
            idx+=2; continue
        elif tok=="--locale":
            if idx+1>=len(queue):
                # leave as token for parser to error unknown
                clean.append(tok); idx+=1; continue
            else:
                idx+=2; continue
        else:
            clean.append(tok); idx+=1; continue
    return clean,None

def main(argv):
    # Reset context
    CTX.config={}
    CTX.debug=None
    try:
        cleaned,code=preprocess(argv)
        if code is not None:
            return code
        # Special exact --format driver case
        if len(cleaned)==2 and cleaned[0]=="--format":
            drv=cleaned[1]
            import gzip, json
            try:
                data=json.loads(gzip.decompress(specmod.load_data("data/format_details.json.gz")).decode())
            except Exception:
                data={}
            if drv in data:
                ent=data[drv]
                if ent.get("stderr"):
                    # TMS warning only actual if GDAL_DATA not set
                    cnt=_warning_count(ent["stderr"])
                    eprint(tms_warnings(cnt))
                sys.stdout.write(ent.get("stdout",""))
                return ent.get("code",0)
            else:
                eprint(f"ERROR 1: --format option given with format '{drv}', but that format not\nrecognised.  Use the --formats option to get a list of available formats,\nand use the short code (i.e. GTiff or HFA) as the format identifier.\n\n")
                return 1
        # Root fallback where first tokens are options for info (e.g. --format json file, file) : Our group dispatch will treat --format as unknown.
        # Detect a pattern: first positional token (scanning options with values for info) is an existing file, and tokens before it are not a known command.
        # Simpler: try dispatch_group, and if it raises a root --format unknown etc, we could attempt info fallback. But implement pre-check:
        # If cleaned and cleaned[0] starts with '-' and cleaned[0] not in root alias map, and there is a token later that is an existing file, attempt info direct.
        # However options like --unknown file should produce info error + root unknown, which this path can approximate by dispatch_leaf info.
        if cleaned and cleaned[0].startswith("-") and cleaned[0] not in ("--help","-h","--json-usage","--drivers") and not cleaned[0].startswith("--config=") and not cleaned[0].startswith("--version"):
            # Check if any token is an existing dataset file (last such?)
            # and first token is not a root subcommand obviously.
            # Only attempt if the option is known to info shortcut OR unknown - original appears to attempt info regardless and then root unknown.
            # We need avoid hijacking cases like --unknown alone (no file) -> root unknown option error (not info)
            has_file=any(_dataset_exists(t) for t in cleaned if not t.startswith("-"))
            if has_file:
                try:
                    return dispatch_leaf(("gdal","info"), ("gdal","info"), cleaned)
                except ParseError as ex:
                    msg=getattr(ex,"message","") or str(ex)
                    if "Usage: gdal info" in msg or "ERROR 5:" in msg:
                        lines=[]
                        for ln in msg.splitlines(True):
                            if ln.startswith("Usage:"):
                                break
                            lines.append(ln)
                        prefix="".join(lines)
                        # then root unknown option for cleaned[0] basename
                        root_node=get_node(("gdal",))
                        # construct second error similar to original for --format: "ERROR 5: gdal: Option '--format' is unknown.\n" + root usage
                        optname=cleaned[0].split("=",1)[0]
                        raise ParseError(prefix+f"ERROR 5: gdal: Option '{optname}' is unknown.\n"+group_error_usage(root_node, ("gdal",)), code=1)
                    raise
        return dispatch_group(("gdal",), ("gdal",), cleaned)
    except ParseError as ex:
        msg=getattr(ex,"message",None) or str(ex)
        if msg and not msg.endswith("\n"):
            msg+="\n"
        eprint(msg)
        return getattr(ex,"code",1) or 1
    except BrokenPipeError:
        return 1
    except KeyboardInterrupt:
        return 1

if __name__=="__main__":
    sys.exit(main(sys.argv[1:]))
