def _split_zip(rest):
    if rest.startswith("{"):
        j=rest.find("}")
        if j!=-1:
            zp=rest[1:j]
            internal=rest[j+1:].lstrip("/")
            return zp, internal
    # find .zip/
    idx=rest.lower().find(".zip/")
    if idx!=-1:
        return rest[:idx+4], rest[idx+5:]
    return rest, ""

def write_binary(path, data):
    if is_mem_path(path):
        MEMFS[path]=bytes(data)
        # register dirs
        parts=path.strip("/").split("/")
        cur=""
        for part in parts[:-1]:
            cur+="/"+part
            MEMDIRS.add(cur)
            MEMDIRS.add(cur+"/")
        return
    if is_stdout_path(path):
        sys.stdout.buffer.write(data); sys.stdout.buffer.flush(); return
    if path.startswith("/vsizip/"):
        # writing zip datasets is complex; handle single file zip creation later in writers if needed
        rest=path[len("/vsizip/"):]
        zip_path, internal=_split_zip(rest)
        mode='a' if os.path.exists(zip_path) else 'w'
        with zipfile.ZipFile(zip_path, mode, compression=zipfile.ZIP_DEFLATED) as z:
            z.writestr(internal or os.path.basename(zip_path), data)
        return
    # ensure parent dir exists? GDAL does not create parent dirs generally; open will error appropriately
    with open(path,"wb") as f:
        f.write(data)

def exists(path):
    if is_mem_path(path):
        return path in MEMFS or path in MEMDIRS or any(k.startswith(path.rstrip("/")+"/") for k in list(MEMFS.keys()))
    if is_stdin_path(path) or is_stdout_path(path):
        return True
    if path.startswith("/vsizip/"):
        try:
            read_binary(path); return True
        except Exception:
            rest=path[len("/vsizip/"):]
            zp,internal=_split_zip(rest)
            return os.path.exists(zp)
    if path.startswith("/vsi"):
        # strip prefix attempt
        return os.path.exists(path)
    return os.path.exists(path)

def is_dir(path):
    if is_mem_path(path):
        return path not in MEMFS and exists(path)
    if path.startswith("/vsizip/"):
        rest=path[len("/vsizip/"):]
        zp,internal=_split_zip(rest)
        return internal=="" and os.path.exists(zp)
    return os.path.isdir(path)

def list_dir(path):
    # returns names (not full)
    if is_mem_path(path):
        prefix=path.rstrip("/")+"/"
        names=set()
        for k in MEMFS:
            if k.startswith(prefix):
                rest=k[len(prefix):]
                names.add(rest.split("/")[0])
        return sorted(names)
    if path.startswith("/vsizip/"):
        rest=path[len("/vsizip/"):]
        zp,internal=_split_zip(rest)
        with zipfile.ZipFile(zp) as z:
            names=[]
            for n in z.namelist():
                if internal and not n.startswith(internal.rstrip("/")+"/"):
                    continue
                rel=n[len(internal.rstrip("/")+"/"):] if internal else n
                if rel:
                    names.append(rel.split("/")[0])
            return sorted(set(names))
    return os.listdir(path)

def file_size(path):
    if is_mem_path(path):
        return len(MEMFS.get(path,b""))
    return os.path.getsize(path)

def remove(path):
    if is_mem_path(path):
        if path in MEMFS:
