    if path.startswith("/vsizip/"):
        rest=path[len("/vsizip/"):]
        zp,internal=_split_zip(rest)
        with zipfile.ZipFile(zp) as z:
            names=[]
            for n in z.namelist():
                if internal and not n.startswith(internal.rstrip("/")+"/"):
                    continue
                rel=n[len(internal.rstrip("/")+"/"):] if internal else n
                if rel:
                    names.append(rel.split("/")[0])
            return sorted(set(names))
