def file_size(path):
    if is_mem_path(path):
        return len(MEMFS.get(path,b""))
    return os.path.getsize(path)

def remove(path):
    if is_mem_path(path):
        if path in MEMFS:
            del MEMFS[path]; return True
        # dir
        keys=[k for k in MEMFS if k.startswith(path.rstrip("/")+"/")]
        for k in keys: del MEMFS[k]
        return bool(keys)
    if os.path.isdir(path):
        # remove recursively? GDAL delete directory may be recursive in some commands, caller decides
        os.rmdir(path); return True
    os.remove(path); return True

def rename(src,dst):
    if is_mem_path(src) or is_mem_path(dst):
        data=read_binary(src); write_binary(dst,data); remove(src); return
