        return crs.input_string
    if crs.epsg:
        return f"EPSG:{crs.epsg}"
    if crs.wkt:
        return crs.wkt
    return crs.input_string

# Transformations
def transform_point(src, dst, x,y,z=None):
    if src is None or dst is None:
        return (x,y) if z is None else (x,y,z)
    if src.epsg and dst.epsg and src.epsg==dst.epsg:
        return (x,y) if z is None else (x,y,z)
    res=_transform_libproj(src,dst,[(x,y,z or 0.0)])
    if res is not None:
        nx,ny,nz=res[0]
        return (nx,ny) if z is None else (nx,ny,nz)
    # Manual fallbacks
    se=src.epsg; de=dst.epsg
    if se==4326 and de==3857:
        R=6378137.0
        nx=R*math.radians(x)
        ny=R*math.log(math.tan(math.pi/4+math.radians(y)/2))
        return (nx,ny) if z is None else (nx,ny,z)
    if se==3857 and de==4326:
        R=6378137.0
        nx=math.degrees(x/R)
        ny=math.degrees(2*math.atan(math.exp(y/R))-math.pi/2)
        return (nx,ny) if z is None else (nx,ny,z)
    if se and de and se in (4326,4269,4258) and (32601<=de<=32660 or 32701<=de<=32760):
        return (*_utm_forward(x,y,de),) if z is None else (*_utm_forward(x,y,de),z)
    if de in (4326,4269,4258) and se and (32601<=se<=32660 or 32701<=se<=32760):
        return (*_utm_inverse(x,y,se),) if z is None else (*_utm_inverse(x,y,se),z)
    return (x,y) if z is None else (x,y,z)

def transform_coords_list(src,dst,coords):
    if src is None or dst is None or (src.epsg and dst.epsg and src.epsg==dst.epsg):
        return coords
    lst=[(c[0],c[1],c[2] if len(c)>2 else 0.0) for c in coords]
    res=_transform_libproj(src,dst,lst)
    if res is not None:
        out=[]
        for orig,(nx,ny,nz) in zip(coords,res):
            if len(orig)>=3:
                out.append((nx,ny,nz,*orig[3:]))
            else:
                out.append((nx,ny))
        return out
    return [transform_point(src,dst,c[0],c[1],c[2] if len(c)>2 else None) if len(c)>=2 else c for c in coords]

def _transform_libproj(src,dst,coords_xyz):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    sdef=crs_to_proj_string(src); ddef=crs_to_proj_string(dst)
    if not sdef or not ddef: return None
    # Cache operations
    key=(sdef,ddef)
    if not hasattr(_transform_libproj,"_cache"):
        _transform_libproj._cache={}
    op=_transform_libproj._cache.get(key)
    if op is None:
        lib.proj_create_crs_to_crs.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_char_p,ctypes.c_void_p]
        lib.proj_create_crs_to_crs.restype=ctypes.c_void_p
