    if not lib or not obj: return None
    import ctypes
    lib.proj_get_area_of_use.argtypes=[ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_double),ctypes.POINTER(ctypes.c_double),ctypes.POINTER(ctypes.c_double),ctypes.POINTER(ctypes.c_double),ctypes.POINTER(ctypes.c_char_p)]
    lib.proj_get_area_of_use.restype=ctypes.c_int
    w,s,e,n=[ctypes.c_double() for _ in range(4)]; name=ctypes.c_char_p()
    ok=lib.proj_get_area_of_use(_ctx,obj,ctypes.byref(w),ctypes.byref(s),ctypes.byref(e),ctypes.byref(n),ctypes.byref(name))
    if not ok: return None
    return (name.value.decode("utf-8") if name.value else "", w.value,s.value,e.value,n.value)

def _summary_from_wkt_and_obj(wkt, obj=None, name_override=None, epsg_override=None, include_area=True):
    lines=[]
    name=name_override
    auth=code=None
    if obj:
        name=name or _proj_name(obj)
        auth,code=_proj_id(obj)
    if not name and wkt:
        m=re.match(r'\s*\w+\s*\[\s*"([^"]*)"', wkt)
        if m: name=m.group(1)
    if epsg_override:
        auth="EPSG"; code=str(epsg_override)
    if name:
        lines.append(f"name: {name}")
    if auth and code:
        lines.append(f"ID: {auth}:{code}")
    # type from wkt root
    typ=None; conv_name=None; method_name=None; unit_name=None
    if wkt:
        root=re.match(r'\s*(\w+)', wkt).group(1) if re.match(r'\s*(\w+)', wkt) else ""
        if root in ("GEOGCRS","GEODCRS"):
            # CS dimension
            m=re.search(r'CS\[ellipsoidal,(\d+)\]', wkt)
            dim=m.group(1) if m else "2"
            typ=f"Geographic {dim}D"
        elif root=="GEOGCS":
            typ="Geographic 2D"
        elif root in ("PROJCRS","PROJCS"):
            typ="Projected"
            m=re.search(r'CONVERSION\["([^"]*)"', wkt)
            if m: conv_name=m.group(1)
            m=re.search(r'METHOD\["([^"]*)"', wkt)
            if m: method_name=m.group(1)
            # unit from CS axis lengthunit: find CS[Cartesian then LENGTHUNIT
            m=re.search(r'CS\[Cartesian,\d+\].*?LENGTHUNIT\["([^"]*)"', wkt, re.S)
            if m: unit_name=m.group(1)
        elif root in ("GEOCCRS","GEOCENTRICCRS"):
            typ="Geocentric"
        elif root in ("VERTCRS","VERT_CS"):
            typ="Vertical"
        elif root in ("COMPOUNDCRS","COMPD_CS"):
            typ="Compound"
        else:
            typ=root
    if typ:
        lines.append(f"type: {typ}")
    if typ=="Projected" and conv_name:
        if method_name and re.sub(r'[^a-z0-9]','',conv_name.lower()) != re.sub(r'[^a-z0-9]','',method_name.lower()):
            lines.append(f"projection type: {conv_name}, {method_name}")
        else:
            lines.append(f"projection type: {conv_name}")
    if typ=="Projected" and unit_name:
        lines.append(f"units: {unit_name}")
    if include_area and obj:
        area=_proj_area(obj)
        if area:
            aname,w,s,e,n=area
            aname=aname.rstrip()
            short=aname
            if short.endswith("."):
                short=short[:-1]
            if " - " in short:
                short=short.split(" - ")[0]+"..."
            elif ", " in short and len(short)>60:
                short=short.split(", ")[0]+"..."
            lines.append(f"area of use: {short}, west {w:.2f}, south {s:.2f}, east {e:.2f}, north {n:.2f}")
    return lines

def _axis_mapping_from_wkt(wkt):
    if not wkt: return [1,2]
    # Find AXIS clauses in order at CS level. Directions north/east etc.
    # For geographic lat/lon: axes are (north, east) CRS order, data GIS order is lon,lat -> mapping [2,1]
    # For projected east,north -> [1,2]
    # Parse AXIS["...",direction,
    dirs=re.findall(r'AXIS\["[^"]*",\s*([A-Za-z]+)', wkt)
    if len(dirs)>=2:
        d=[x.lower() for x in dirs]
        # geographic: first CRS axis north (lat), second east (lon) - data axis1 (x) corresponds CRS axis2
        if d[0] in ("north","n") and d[1] in ("east","e"):
            return [2,1] if len(d)==2 else [2,1,3]
        if d[0] in ("east","e") and d[1] in ("north","n"):
            return [1,2]
    # WKT1 no AXIS for geographic usually lon/lat GIS order but EPSG identification: In VRT SRS, dataAxisToSRSAxisMapping attribute gives mapping explicit in reader.
    return [1,2]

def epsg_crs(code, kind="epsg_db"):
    code_int=int(code)
    if kind=="geojson4326" and code_int==4326:
        tpl=templates().get("_geojson4326")
        if tpl:
            return CRS(epsg=4326,name="WGS 84",wkt=tpl.get("wkt"),projjson=tpl.get("projjson"),summary=tpl.get("summary"),axis_mapping=[2,1],kind="geojson4326",prj=tpl.get("prj"))
    if kind=="gtiff":
        tpl=templates().get(str(code_int))
        if tpl and tpl.get("wkt"):
            axis=[int(x) for x in tpl.get("axis").split(",")] if tpl.get("axis") else [1,2]
            name=None
            for s in tpl.get("summary",[]):
                if s.startswith("name: "): name=s[len("name: "):]
            return CRS(epsg=code_int,name=name,wkt=tpl.get("wkt"),projjson=tpl.get("projjson"),summary=tpl.get("summary"),axis_mapping=axis,kind="gtiff",prj=tpl.get("prj"))
    # epsg_db via libproj
    obj=_proj_obj_from_epsg(code_int)
    if obj:
        wkt=_proj_wkt(obj,2)
        pj=_proj_projjson(obj)
        name=_proj_name(obj)
        summary=_summary_from_wkt_and_obj(wkt,obj,name_override=name,epsg_override=code_int,include_area=True)
        axis=_axis_mapping_from_wkt(wkt)
        # For geographic, GDAL data axis mapping is [2,1] if CRS axis lat/lon as above.
        tpl=templates().get(str(code_int),{})
        return CRS(epsg=code_int,name=name,wkt=wkt,projjson=pj,summary=summary,axis_mapping=axis,kind="epsg_db",prj=tpl.get("prj"))
    # fallback to gtiff template
    tpl=templates().get(str(code_int))
    if tpl and tpl.get("wkt"):
        axis=[int(x) for x in tpl.get("axis").split(",")] if tpl.get("axis") else [1,2]
        name=None
        for s in tpl.get("summary",[]):
            if s.startswith("name: "): name=s[len("name: "):]
        return CRS(epsg=code_int,name=name,wkt=tpl.get("wkt"),projjson=tpl.get("projjson"),summary=tpl.get("summary"),axis_mapping=axis,kind="epsg_db",prj=tpl.get("prj"))
    return None

def crs_from_gtiff(code):
    return epsg_crs(code, kind="gtiff")

def geojson_crs():
    return epsg_crs(4326, kind="geojson4326")

def crs_from_wkt(wkt, axis_mapping=None, kind="wkt"):
    if wkt is None:
        return None
    wkt_str=wkt.strip()
    # Try identify EPSG from root authority for shapefile prj matching template
    # libproj create from WKT
    lib=_load_libproj()
    obj=None
    out_wkt=None; pj=None; epsg=None; name=None; summary=None
    if lib:
        import ctypes
        lib.proj_create_from_wkt.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_char_p)]
        lib.proj_create_from_wkt.restype=ctypes.c_void_p
        # signature in PROJ 8: proj_create_from_wkt(ctx,wkt,database_path,options,out_warnings?) Actually (ctx,wkt,options,out_warnings,out_grammar_errors?)
        # Try with 5 params: used in test below via helper fallback if fails
        try:
            out_warn=ctypes.c_char_p(); out_err=ctypes.c_char_p()
            obj=lib.proj_create_from_wkt(_ctx,wkt_str.encode(),None,ctypes.byref(out_warn),ctypes.byref(out_err))
        except Exception:
            obj=None
    if obj:
        out_wkt=_proj_wkt(obj,2)
        pj=_proj_projjson(obj)
        auth,code=_proj_id(obj)
        if auth=="EPSG" and code and str(code).isdigit():
            epsg=int(code)
        name=_proj_name(obj)
        # Summary for WKT-sourced CRS: do not include area if WKT had no USAGE? _proj_area for a WKT1 CRS returns no area in PROJ (probably), so include_area will add only if present.
        summary=_summary_from_wkt_and_obj(out_wkt,obj,name_override=name,epsg_override=epsg,include_area=True)
        axis=axis_mapping or _axis_mapping_from_wkt(out_wkt)
        return CRS(epsg=epsg,name=name,wkt=out_wkt,projjson=pj,summary=summary,axis_mapping=axis,kind=kind,wkt1=wkt_str)
    # fallback parsing
    # Extract epsg from AUTHORITY/ID at end
    epsg=None
    # root authority is last AUTHORITY in WKT1 generally
    auths=re.findall(r'AUTHORITY\["EPSG",\s*"?(\d+)"?\]', wkt_str)
    ids=re.findall(r'ID\["EPSG",\s*(\d+)\s*\](?=\s*\]*\s*$)', wkt_str)
    if ids:
        epsg=int(ids[-1])
    elif auths:
        epsg=int(auths[-1])
    m=re.match(r'\s*\w+\s*\[\s*"([^"]*)"', wkt_str)
    name=m.group(1) if m else None
    summary=_summary_from_wkt_and_obj(wkt_str,None,name_override=name,epsg_override=epsg,include_area=False)
    return CRS(epsg=epsg,name=name,wkt=wkt_str,projjson=None,summary=summary,axis_mapping=axis_mapping or _axis_mapping_from_wkt(wkt_str),kind=kind,wkt1=wkt_str)

def crs_from_prj(prj):
    if prj is None: return None
    text=prj.strip()
    # match templates prj exact (normalized whitespace)
    norm=re.sub(r'\s+','',text)
    for code,tpl in templates().items():
        if code.startswith("_"): continue
        p=tpl.get("prj")
        if p and re.sub(r'\s+','',p.strip())==norm:
            c=epsg_crs(int(code), kind="epsg_db")
            if c:
                c.prj=prj; return c
    return crs_from_wkt(text, kind="prj")

def parse_crs_input(value, special_allowed=()):
    """
    Returns (CRS_or_None, proj_error_lines list[str], ok)
    """
    if value is None:
        return None,[],False
    s=str(value).strip()
    if s in special_allowed:
        return None,[],True
    if s=="":
        return None,[],False
    low=s.lower()
    # EPSG:xxxx, EPSG:xxxx+yyyy (compound: treat as horizontal xxxx for our purposes but maybe preserve epsg? original creates compound CRS - raster Info might show compound. For now horizontal)
    m=re.fullmatch(r'(?:EPSG|epsg):(\d+)(?:\+(\d+))?', s)
    if m:
        code=int(m.group(1))
        c=epsg_crs(code, kind="epsg_db")
        if c is None or _proj_obj_from_epsg(code) is None and epsg_crs(code,"gtiff") is None:
            # Determine existence via libproj / templates
            if _proj_obj_from_epsg(code) is None:
                return None,["ERROR 1: PROJ: proj_create_from_database: crs not found"],False
        if c:
            c.input_string=s; return c,[],True
        return None,["ERROR 1: PROJ: proj_create_from_database: crs not found"],False
    m=re.fullmatch(r'(EPSG|epsg):(.*)', s)
    if m:
        # EPSG:abc, EPSG:
        return None,["ERROR 1: PROJ: proj_create_from_database: crs not found"],False
    # urn EPSG
    m=re.search(r'urn:ogc:def:crs:EPSG:(?:[^:]*):(\d+)$', s, re.I)
    if m:
        c=epsg_crs(int(m.group(1)),"epsg_db")
        return (c,[],True) if c else (None,["ERROR 1: PROJ: proj_create_from_database: crs not found"],False)
    if low=="wgs84" or low=="wgs 84":
        c=epsg_crs(4326,"epsg_db"); return c,[],True
    if low=="CRS84".lower():
        return None,[],False
    if low=="nad83":
        c=epsg_crs(4269,"epsg_db"); return c,[],True
    if low=="nad27":
        c=epsg_crs(4267,"epsg_db"); return c,[],True
    # File path? GDAL CRS can be a filename of a dataset or a file containing WKT - if a local file exists and is text, try
    if os.path.exists(s) and os.path.isfile(s) and len(s)<1000:
        try:
            with open(s,"r",errors="ignore") as f:
                content=f.read(10000).strip()
            if content.startswith(("{","[","GEOG","PROJ","+proj")) or "CRS" in content[:50]:
                return parse_crs_input(content, special_allowed)
        except Exception:
            pass
    # WKT
    if re.match(r'^(GEOG|GEOD|PROJ|VERT|COMPOUND|COMPD|GEOCC|LOCAL|FITTED)', s):
        c=crs_from_wkt(s)
        # validate by libproj if available - crs_from_wkt falls back parse even invalid; use libproj direct check
        ok=_validate_via_libproj(s)
        if ok is False:
            return None,[],False
        return c,[],True
    # PROJ string
    if s.startswith("+proj") or s.startswith("proj4:") or s.startswith("+init") or s.startswith("+"):
        projstr=s[6:].strip() if s.startswith("proj4:") else s
        # Try create CRS via proj_create from proj string, then identify epsg if simple longlat datum
        epsg=None
        if "+datum=WGS84" in projstr and ("+proj=longlat" in projstr or "+proj=latlong" in projstr):
            c=epsg_crs(4326,"epsg_db")
            if c:
                c.input_string=s; return c,[],True
        # Generic: create a CRS with wkt generated from proj string via libproj proj_create then as_wkt? proj_create returns operation, proj_as_wkt may give CRS?
        c=_crs_from_proj_string(projstr)
        if c:
            c.input_string=s; return c,[],True
        return None,[],False
    # could be a projjson string
    if s.startswith("{"):
        try:
            pj=json.loads(s, parse_float=RawNumber)
            code=None
            idobj=pj.get("id") if isinstance(pj,dict) else None
            if isinstance(idobj,dict) and idobj.get("authority")=="EPSG":
                return epsg_crs(int(idobj.get("code")),"epsg_db"),[],True
            name=pj.get("name") if isinstance(pj,dict) else None
            return CRS(name=name,projjson=pj,summary=None,kind="projjson",input_string=s),[],True
        except Exception:
            return None,[],False
    return None,[],False

def _validate_via_libproj(wkt):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    lib.proj_create_from_wkt.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_char_p),ctypes.POINTER(ctypes.c_char_p)]
    lib.proj_create_from_wkt.restype=ctypes.c_void_p
    out_warn=ctypes.c_char_p(); out_err=ctypes.c_char_p()
    obj=lib.proj_create_from_wkt(_ctx,wkt.encode(),None,ctypes.byref(out_warn),ctypes.byref(out_err))
    return bool(obj)

def _crs_from_proj_string(projstr):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    # proj_create(ctx, definition) returns a P* object for a CRS/operation from a proj string in PROJ 8 it may create a BoundCRS etc. Then proj_get_source_crs?
    try:
        lib.proj_create.argtypes=[ctypes.c_void_p,ctypes.c_char_p]; lib.proj_create.restype=ctypes.c_void_p
        obj=lib.proj_create(_ctx,projstr.encode())
        if not obj: return None
        # Try get source CRS if operation
        src=None
        try:
            lib.proj_get_source_crs.argtypes=[ctypes.c_void_p,ctypes.c_void_p]; lib.proj_get_source_crs.restype=ctypes.c_void_p
            src=lib.proj_get_source_crs(_ctx,obj)
        except Exception:
            src=None
        use=src or obj
        wkt=_proj_wkt(use,2)
        if wkt:
            c=crs_from_wkt(wkt)
            # store proj string for transformations
            c.input_string=projstr; return c
    except Exception:
        return None
    return None

def crs_to_proj_string(crs):
    if crs is None: return None
    if crs.input_string and (crs.input_string.startswith("+") or crs.input_string.startswith("proj4:")):
        return crs.input_string
    if crs.epsg:
        return f"EPSG:{crs.epsg}"
    if crs.wkt:
        return crs.wkt
    return crs.input_string

# Transformations
def transform_point(src, dst, x,y,z=None):
    if src is None or dst is None:
        return (x,y) if z is None else (x,y,z)
    if src.epsg and dst.epsg and src.epsg==dst.epsg:
        return (x,y) if z is None else (x,y,z)
    res=_transform_libproj(src,dst,[(x,y,z or 0.0)])
    if res is not None:
        nx,ny,nz=res[0]
        return (nx,ny) if z is None else (nx,ny,nz)
    # Manual fallbacks
    se=src.epsg; de=dst.epsg
    if se==4326 and de==3857:
        R=6378137.0
        nx=R*math.radians(x)
        ny=R*math.log(math.tan(math.pi/4+math.radians(y)/2))
        return (nx,ny) if z is None else (nx,ny,z)
    if se==3857 and de==4326:
        R=6378137.0
        nx=math.degrees(x/R)
        ny=math.degrees(2*math.atan(math.exp(y/R))-math.pi/2)
        return (nx,ny) if z is None else (nx,ny,z)
    if se and de and se in (4326,4269,4258) and (32601<=de<=32660 or 32701<=de<=32760):
        return (*_utm_forward(x,y,de),) if z is None else (*_utm_forward(x,y,de),z)
    if de in (4326,4269,4258) and se and (32601<=se<=32660 or 32701<=se<=32760):
        return (*_utm_inverse(x,y,se),) if z is None else (*_utm_inverse(x,y,se),z)
    return (x,y) if z is None else (x,y,z)

def transform_coords_list(src,dst,coords):
    if src is None or dst is None or (src.epsg and dst.epsg and src.epsg==dst.epsg):
        return coords
    lst=[(c[0],c[1],c[2] if len(c)>2 else 0.0) for c in coords]
    res=_transform_libproj(src,dst,lst)
    if res is not None:
        out=[]
        for orig,(nx,ny,nz) in zip(coords,res):
            if len(orig)>=3:
                out.append((nx,ny,nz,*orig[3:]))
            else:
                out.append((nx,ny))
        return out
    return [transform_point(src,dst,c[0],c[1],c[2] if len(c)>2 else None) if len(c)>=2 else c for c in coords]

def _transform_libproj(src,dst,coords_xyz):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    sdef=crs_to_proj_string(src); ddef=crs_to_proj_string(dst)
    if not sdef or not ddef: return None
    # Cache operations
    key=(sdef,ddef)
    if not hasattr(_transform_libproj,"_cache"):
        _transform_libproj._cache={}
    op=_transform_libproj._cache.get(key)
    if op is None:
        lib.proj_create_crs_to_crs.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_char_p,ctypes.c_void_p]
        lib.proj_create_crs_to_crs.restype=ctypes.c_void_p
        lib.proj_normalize_for_visualization.argtypes=[ctypes.c_void_p,ctypes.c_void_p]
        lib.proj_normalize_for_visualization.restype=ctypes.c_void_p
        raw=lib.proj_create_crs_to_crs(_ctx,sdef.encode(),ddef.encode(),None)
        if not raw:
            return None
        norm=lib.proj_normalize_for_visualization(_ctx,raw)
        # PROJ docs: free raw after normalize? It returns new object and raw should be destroyed; keep raw not freed to be safe
        op=norm or raw
        _transform_libproj._cache[key]=op
    class XYZT(ctypes.Structure):
        _fields_=[("x",ctypes.c_double),("y",ctypes.c_double),("z",ctypes.c_double),("t",ctypes.c_double)]
    class COORD(ctypes.Union):
        _fields_=[("xyzt",XYZT),("v",ctypes.c_double*4)]
    lib.proj_trans.argtypes=[ctypes.c_void_p,ctypes.c_int,COORD]
    lib.proj_trans.restype=COORD
    PJ_FWD=1
    out=[]
    for (x,y,z) in coords_xyz:
        c=COORD(); c.xyzt.x=x; c.xyzt.y=y; c.xyzt.z=z or 0.0; c.xyzt.t=0.0
        r=lib.proj_trans(op,PJ_FWD,c)
        out.append((r.xyzt.x,r.xyzt.y,r.xyzt.z))
    return out

def _utm_forward(lon,lat,epsg):
    zone=epsg-32600 if epsg>=32600 and epsg<32700 else epsg-32700
    south=epsg>=32700
    # WGS84 transverse mercator series
    a=6378137.0; f=1/298.257223563; k0=0.9996; e2=f*(2-f)
    lon0=math.radians((zone-1)*6-180+3)
    latr=math.radians(lat); lonr=math.radians(lon)
    ep2=e2/(1-e2)
    N=a/math.sqrt(1-e2*math.sin(latr)**2)
    T=math.tan(latr)**2; C=ep2*math.cos(latr)**2; A=(lonr-lon0)*math.cos(latr)
    M=a*((1-e2/4-3*e2**2/64-5*e2**3/256)*latr-(3*e2/8+3*e2**2/32+45*e2**3/1024)*math.sin(2*latr)+(15*e2**2/256+45*e2**3/1024)*math.sin(4*latr)-(35*e2**3/3072)*math.sin(6*latr))
    x=k0*N*(A+(1-T+C)*A**3/6+(5-18*T+T*T+72*C-58*ep2)*A**5/120)+500000
    y=k0*(M+N*math.tan(latr)*(A*A/2+(5-T+9*C+4*C*C)*A**4/24+(61-58*T+T*T+600*C-330*ep2)*A**6/720))
    if south: y+=10000000
    return x,y

def _utm_inverse(x,y,epsg):
    # Newton guess using forward iterative approx: use simple formulas via footpoint
    zone=epsg-32600 if epsg>=32600 and epsg<32700 else epsg-32700
    south=epsg>=32700
    a=6378137.0; f=1/298.257223563; k0=0.9996; e2=f*(2-f); ep2=e2/(1-e2)
    if south: y-=10000000
    x-=500000
    M=y/k0
    mu=M/(a*(1-e2/4-3*e2**2/64-5*e2**3/256))
