    lib.proj_create_from_database.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_char_p,ctypes.c_int,ctypes.c_int]
    lib.proj_create_from_database.restype=ctypes.c_void_p
    obj=lib.proj_create_from_database(_ctx,b"EPSG",str(code).encode(),3,0)
    return obj or None

