    if re.match(r'^(GEOG|GEOD|PROJ|VERT|COMPOUND|COMPD|GEOCC|LOCAL|FITTED)', s):
        c=crs_from_wkt(s)
        # validate by libproj if available - crs_from_wkt falls back parse even invalid; use libproj direct check
        ok=_validate_via_libproj(s)
        if ok is False:
            return None,[],False
        return c,[],True
    # PROJ string
    if s.startswith("+proj") or s.startswith("proj4:") or s.startswith("+init") or s.startswith("+"):
        projstr=s[6:].strip() if s.startswith("proj4:") else s
        # Try create CRS via proj_create from proj string, then identify epsg if simple longlat datum
        epsg=None
        if "+datum=WGS84" in projstr and ("+proj=longlat" in projstr or "+proj=latlong" in projstr):
            c=epsg_crs(4326,"epsg_db")
            if c:
                c.input_string=s; return c,[],True
        # Generic: create a CRS with wkt generated from proj string via libproj proj_create then as_wkt? proj_create returns operation, proj_as_wkt may give CRS?
        c=_crs_from_proj_string(projstr)
        if c:
            c.input_string=s; return c,[],True
        return None,[],False
    # could be a projjson string
    if s.startswith("{"):
        try:
            pj=json.loads(s, parse_float=RawNumber)
            code=None
            idobj=pj.get("id") if isinstance(pj,dict) else None
            if isinstance(idobj,dict) and idobj.get("authority")=="EPSG":
                return epsg_crs(int(idobj.get("code")),"epsg_db"),[],True
            name=pj.get("name") if isinstance(pj,dict) else None
            return CRS(name=name,projjson=pj,summary=None,kind="projjson",input_string=s),[],True
        except Exception:
            return None,[],False
    return None,[],False

def _validate_via_libproj(wkt):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    lib.proj_create_from_wkt.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_char_p),ctypes.POINTER(ctypes.c_char_p)]
    lib.proj_create_from_wkt.restype=ctypes.c_void_p
    out_warn=ctypes.c_char_p(); out_err=ctypes.c_char_p()
    obj=lib.proj_create_from_wkt(_ctx,wkt.encode(),None,ctypes.byref(out_warn),ctypes.byref(out_err))
    return bool(obj)

def _crs_from_proj_string(projstr):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    # proj_create(ctx, definition) returns a P* object for a CRS/operation from a proj string in PROJ 8 it may create a BoundCRS etc. Then proj_get_source_crs?
    try:
        lib.proj_create.argtypes=[ctypes.c_void_p,ctypes.c_char_p]; lib.proj_create.restype=ctypes.c_void_p
        obj=lib.proj_create(_ctx,projstr.encode())
        if not obj: return None
        # Try get source CRS if operation
        src=None
        try:
            lib.proj_get_source_crs.argtypes=[ctypes.c_void_p,ctypes.c_void_p]; lib.proj_get_source_crs.restype=ctypes.c_void_p
            src=lib.proj_get_source_crs(_ctx,obj)
        except Exception:
            src=None
        use=src or obj
        wkt=_proj_wkt(use,2)
        if wkt:
            c=crs_from_wkt(wkt)
            # store proj string for transformations
            c.input_string=projstr; return c
    except Exception:
        return None
    return None

def crs_to_proj_string(crs):
    if crs is None: return None
    if crs.input_string and (crs.input_string.startswith("+") or crs.input_string.startswith("proj4:")):
        return crs.input_string
    if crs.epsg:
        return f"EPSG:{crs.epsg}"
    if crs.wkt:
        return crs.wkt
    return crs.input_string

# Transformations
def transform_point(src, dst, x,y,z=None):
    if src is None or dst is None:
        return (x,y) if z is None else (x,y,z)
    if src.epsg and dst.epsg and src.epsg==dst.epsg:
        return (x,y) if z is None else (x,y,z)
    res=_transform_libproj(src,dst,[(x,y,z or 0.0)])
    if res is not None:
        nx,ny,nz=res[0]
        return (nx,ny) if z is None else (nx,ny,nz)
    # Manual fallbacks
    se=src.epsg; de=dst.epsg
    if se==4326 and de==3857:
        R=6378137.0
        nx=R*math.radians(x)
        ny=R*math.log(math.tan(math.pi/4+math.radians(y)/2))
        return (nx,ny) if z is None else (nx,ny,z)
    if se==3857 and de==4326:
        R=6378137.0
        nx=math.degrees(x/R)
        ny=math.degrees(2*math.atan(math.exp(y/R))-math.pi/2)
        return (nx,ny) if z is None else (nx,ny,z)
    if se and de and se in (4326,4269,4258) and (32601<=de<=32660 or 32701<=de<=32760):
        return (*_utm_forward(x,y,de),) if z is None else (*_utm_forward(x,y,de),z)
    if de in (4326,4269,4258) and se and (32601<=se<=32660 or 32701<=se<=32760):
        return (*_utm_inverse(x,y,se),) if z is None else (*_utm_inverse(x,y,se),z)
    return (x,y) if z is None else (x,y,z)

def transform_coords_list(src,dst,coords):
    if src is None or dst is None or (src.epsg and dst.epsg and src.epsg==dst.epsg):
        return coords
    lst=[(c[0],c[1],c[2] if len(c)>2 else 0.0) for c in coords]
    res=_transform_libproj(src,dst,lst)
    if res is not None:
        out=[]
        for orig,(nx,ny,nz) in zip(coords,res):
            if len(orig)>=3:
                out.append((nx,ny,nz,*orig[3:]))
            else:
                out.append((nx,ny))
        return out
    return [transform_point(src,dst,c[0],c[1],c[2] if len(c)>2 else None) if len(c)>=2 else c for c in coords]

def _transform_libproj(src,dst,coords_xyz):
    lib=_load_libproj()
    if not lib: return None
    import ctypes
    sdef=crs_to_proj_string(src); ddef=crs_to_proj_string(dst)
    if not sdef or not ddef: return None
    # Cache operations
    key=(sdef,ddef)
    if not hasattr(_transform_libproj,"_cache"):
        _transform_libproj._cache={}
    op=_transform_libproj._cache.get(key)
    if op is None:
        lib.proj_create_crs_to_crs.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_char_p,ctypes.c_void_p]
        lib.proj_create_crs_to_crs.restype=ctypes.c_void_p
        lib.proj_normalize_for_visualization.argtypes=[ctypes.c_void_p,ctypes.c_void_p]
        lib.proj_normalize_for_visualization.restype=ctypes.c_void_p
        raw=lib.proj_create_crs_to_crs(_ctx,sdef.encode(),ddef.encode(),None)
        if not raw:
            return None
        norm=lib.proj_normalize_for_visualization(_ctx,raw)
        # PROJ docs: free raw after normalize? It returns new object and raw should be destroyed; keep raw not freed to be safe
        op=norm or raw
        _transform_libproj._cache[key]=op
    class XYZT(ctypes.Structure):
        _fields_=[("x",ctypes.c_double),("y",ctypes.c_double),("z",ctypes.c_double),("t",ctypes.c_double)]
    class COORD(ctypes.Union):
        _fields_=[("xyzt",XYZT),("v",ctypes.c_double*4)]
    lib.proj_trans.argtypes=[ctypes.c_void_p,ctypes.c_int,COORD]
    lib.proj_trans.restype=COORD
    PJ_FWD=1
    out=[]
    for (x,y,z) in coords_xyz:
        c=COORD(); c.xyzt.x=x; c.xyzt.y=y; c.xyzt.z=z or 0.0; c.xyzt.t=0.0
        r=lib.proj_trans(op,PJ_FWD,c)
        out.append((r.xyzt.x,r.xyzt.y,r.xyzt.z))
    return out

def _utm_forward(lon,lat,epsg):
    zone=epsg-32600 if epsg>=32600 and epsg<32700 else epsg-32700
    south=epsg>=32700
    # WGS84 transverse mercator series
    a=6378137.0; f=1/298.257223563; k0=0.9996; e2=f*(2-f)
    lon0=math.radians((zone-1)*6-180+3)
    latr=math.radians(lat); lonr=math.radians(lon)
    ep2=e2/(1-e2)
    N=a/math.sqrt(1-e2*math.sin(latr)**2)
    T=math.tan(latr)**2; C=ep2*math.cos(latr)**2; A=(lonr-lon0)*math.cos(latr)
    M=a*((1-e2/4-3*e2**2/64-5*e2**3/256)*latr-(3*e2/8+3*e2**2/32+45*e2**3/1024)*math.sin(2*latr)+(15*e2**2/256+45*e2**3/1024)*math.sin(4*latr)-(35*e2**3/3072)*math.sin(6*latr))
    x=k0*N*(A+(1-T+C)*A**3/6+(5-18*T+T*T+72*C-58*ep2)*A**5/120)+500000
    y=k0*(M+N*math.tan(latr)*(A*A/2+(5-T+9*C+4*C*C)*A**4/24+(61-58*T+T*T+600*C-330*ep2)*A**6/720))
    if south: y+=10000000
    return x,y

def _utm_inverse(x,y,epsg):
    # Newton guess using forward iterative approx: use simple formulas via footpoint
    zone=epsg-32600 if epsg>=32600 and epsg<32700 else epsg-32700
    south=epsg>=32700
    a=6378137.0; f=1/298.257223563; k0=0.9996; e2=f*(2-f); ep2=e2/(1-e2)
    if south: y-=10000000
    x-=500000
    M=y/k0
    mu=M/(a*(1-e2/4-3*e2**2/64-5*e2**3/256))
    e1=(1-math.sqrt(1-e2))/(1+math.sqrt(1-e2))
    J1=3*e1/2-27*e1**3/32; J2=21*e1**2/16-55*e1**4/32; J3=151*e1**3/96; J4=1097*e1**4/512
    fp=mu+J1*math.sin(2*mu)+J2*math.sin(4*mu)+J3*math.sin(6*mu)+J4*math.sin(8*mu)
    C1=ep2*math.cos(fp)**2; T1=math.tan(fp)**2
    N1=a/math.sqrt(1-e2*math.sin(fp)**2); R1=a*(1-e2)/(1-e2*math.sin(fp)**2)**1.5
    D=x/(N1*k0)
    lat=fp-(N1*math.tan(fp)/R1)*(D*D/2-(5+3*T1+10*C1-4*C1*C1-9*ep2)*D**4/24+(61+90*T1+298*C1+45*T1*T1-252*ep2-3*C1*C1)*D**6/720)
    lon0=math.radians((zone-1)*6-180+3)
    lon=lon0+(D-(1+2*T1+C1)*D**3/6+(5-2*C1+28*T1-8*ep2+8*D*0+24*T1*T1+4*0))*0  # placeholder replaced below
    lon=lon0+(D-(1+2*T1+C1)*D**3/6+(5-2*C1+28*T1-8*ep2+24*T1*T1+4*C1+6*0)*D**5/120)/math.cos(fp) if False else lon0+(D-(1+2*T1+C1)*D**3/6+(5-2*C1+28*T1-8*ep2+24*T1*T1+4*C1)*D**5/120)/math.cos(fp)
    return math.degrees(lon), math.degrees(lat)

def wkt1_gdal_from_epsg(code):
    obj=_proj_obj_from_epsg(code)
    if obj:
        w=_proj_wkt(obj,4)
        if w:
            # GDAL compact WKT1: remove newlines and spaces except inside quotes
            # PROJ pretty WKT has newlines/indents. Compact by removing whitespace outside quotes
            out=""; inq=False
            for ch in w:
                if ch=='"': inq=not inq
                if not inq and ch in ' \n\r\t':
                    continue
                out+=ch
            return out
    return None

def prj_from_crs(crs):
    if crs is None: return None
    if crs.prj:
        return crs.prj
    if crs.epsg:
        tpl=templates().get(str(crs.epsg),{})
        if tpl.get("prj"):
            return tpl["prj"]
        obj=_proj_obj_from_epsg(crs.epsg)
        if obj:
            w=_proj_wkt(obj,5)  # ESRI WKT1 compact in PROJ output (no pretty)
            return w
    if crs.wkt:
        # create object from WKT and export ESRI
        c=crs_from_wkt(crs.wkt)
        if c and c.epsg:
            return prj_from_crs(c)
    return None
