                    parsed=json.loads(v)
                    return _compact_json_value(parsed,None,sig_figs)
                except Exception:
                    pass
        return _json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):
        return "["+",".join(_compact_json_value(x,None,sig_figs) for x in v)+"]"
    if isinstance(v,dict):
        return "{"+",".join(_json.dumps(str(k),ensure_ascii=False)+":"+_compact_json_value(val,None,sig_figs) for k,val in v.items())+"}"
    return _json.dumps(str(v),ensure_ascii=False)

def _geom_compact(geom, coord_decimals=15):
    if geom is None:return "null"
    t=geom.get("type")
    if t=="LinearRing": t="LineString"
    if t=="GeometryCollection" or "geometries" in geom:
        return '{"type":"GeometryCollection","geometries":['+",".join(_geom_compact(g,coord_decimals) for g in geom.get("geometries",[]))+"]}"
