def open_topojson(path,data=None):
    if data is None: data=vfs.read_binary(path)
    obj=json.loads(data.decode("utf-8",errors="replace"))
    if not isinstance(obj,dict) or obj.get("type")!="Topology":
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    arcs=obj.get("arcs",[])
    transform=obj.get("transform") or {}
    scale=transform.get("scale",[1,1]); translate=transform.get("translate",[0,0])
    def decode_arc(arc):
        pts=[]; x=0; y=0
        for pt in arc:
            if transform:
                x+=pt[0]; y+=pt[1]
                pts.append([x*scale[0]+translate[0], y*scale[1]+translate[1]])
            else:
                pts.append([float(pt[0]),float(pt[1])])
        return pts
    decoded=[decode_arc(a) for a in arcs]
    def arc_coords(idx):
        if idx>=0:
            return decoded[idx][:]
        else:
            return list(reversed(decoded[~idx]))
    def stitch(indexes):
        coords=[]
        for idx in indexes:
            seg=arc_coords(idx)
            if coords and seg and coords[-1]==seg[0]:
                coords.extend(seg[1:])
            else:
                coords.extend(seg)
        return coords
    def topo_geom(o):
        if o is None:return None
        t=o.get("type")
        if t=="Point":
            c=o.get("coordinates")
            if transform: c=[c[0]*scale[0]+translate[0],c[1]*scale[1]+translate[1]]
            return {"type":"Point","coordinates":_float_coords(c)}
        if t=="MultiPoint":
            pts=[]
            for c in o.get("coordinates",[]):
                if transform:c=[c[0]*scale[0]+translate[0],c[1]*scale[1]+translate[1]]
                pts.append(c)
            return {"type":"MultiPoint","coordinates":_float_coords(pts)}
        if t=="LineString":
            return {"type":"LineString","coordinates":stitch(o.get("arcs",[]))}
        if t=="MultiLineString":
            return {"type":"MultiLineString","coordinates":[stitch(a) for a in o.get("arcs",[])]}
        if t=="Polygon":
            return {"type":"Polygon","coordinates":[stitch(a) for a in o.get("arcs",[])]}
        if t=="MultiPolygon":
            return {"type":"MultiPolygon","coordinates":[[stitch(a) for a in poly] for poly in o.get("arcs",[])]}
        if t=="GeometryCollection":
            return {"type":"GeometryCollection","geometries":[topo_geom(g) for g in o.get("geometries",[])]}
        return None
    layers=[]
    for name, o in (obj.get("objects") or {}).items():
        geoms=[]
        if o.get("type")=="GeometryCollection":
            items=o.get("geometries",[])
        else:
