            features_raw.append(props); gms.append(topo_geom(item))
        fields,converted=infer_fields_and_convert(features_raw)
        features=[Feature(i,converted[i],gms[i]) for i in range(len(gms))]
        layers.append(Layer(name,fields,features,_layer_geom_type(features),crsmod.geojson_crs()))
    return VectorDataset("TopoJSON","TopoJSON",path,layers)

