def identify_vector_driver(path):
    # Return driver short name if recognized by extension/content, else None
    p=str(path)
    lower=p.lower()
    if vfs.is_dir(path):
        # directory may be shapefile dataset if contains shp/dbf
        try:
            names=vfs.list_dir(path)
            if any(n.lower().endswith((".shp",".dbf")) for n in names):
                return "ESRI Shapefile"
        except Exception: pass
        return None
    if lower.endswith((".shp",".dbf",".shz")) or lower.endswith(".shp.zip"):
        return "ESRI Shapefile"
    if lower.endswith((".geojsonl",".geojsons")):
        return "GeoJSONSeq"
    # need read content for json variants and extensionless
    try:
        data=vfs.read_binary(path)[:200000]
    except Exception:
        return None
    # quick binary check shape file code 9994
    if len(data)>=4 and data[:4]==b'\x00\x00\x27\x0a':
        return "ESRI Shapefile"
    text=data[:100000].decode("utf-8",errors="ignore").lstrip("\x1e \t\r\n")
    if text.startswith("{") or text.startswith("["):
        # Look for topology / esri indicators in head
        head=text[:5000]
        if '"type"' in head and '"Topology"' in head:
            return "TopoJSON"
        if '"geometryType"' in head and 'esri' in head.lower():
            return "ESRIJSON"
        # Could parse first json if small enough
        if lower.endswith((".geojson",".json",".topojson")) or lower.endswith(".txt") or "." not in os.path.basename(lower):
            # Try full parse if file size not huge? data may truncated - attempt read all in open stage identifies better. For identify heuristic:
            if '"arcs"' in head and '"objects"' in head:
                return "TopoJSON"
            if '"spatialReference"' in head and '"features"' in head:
                return "ESRIJSON"
            return "GeoJSON"
        return "GeoJSON"
    # GeoJSONSeq lines start with { handled above
    return None

def open_vector_dataset(path, input_formats=None, open_options=None, update=False):
    # open_options dict/list ignored for now except maybe
    if not vfs.exists(path) and not vfs.is_stdin_path(path):
        raise VectorOpenError([f"ERROR 4: {path}: No such file or directory"])
    driver=identify_vector_driver(path)
    # Input format restriction check in caller layer? Implement basic: if formats supplied and driver not in, error not recognized
    if input_formats:
        fmts=[str(f) for f in input_formats]
        if driver and driver not in fmts:
            raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
        if driver is None and fmts:
            # If format specified is GeoJSON etc, try that parser
            driver=fmts[0]
    if driver is None:
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    if driver=="GeoJSON":
        # Need distinguish Esri/Topo by content full parse maybe
        try:
            return open_geojson(path)
        except VectorOpenError:
            # try topo/esri
            data=vfs.read_binary(path)
            try:
                return open_topojson(path,data)
            except Exception:
                pass
            try:
                return open_esrijson(path,data)
            except Exception:
                pass
            raise
    elif driver=="GeoJSONSeq":
        return open_geojsonseq(path)
    elif driver=="ESRI Shapefile":
        return open_shapefile(path)
    elif driver=="TopoJSON":
        return open_topojson(path)
    elif driver=="ESRIJSON":
        return open_esrijson(path)
    elif driver=="MEM":
        # MEM output datasets cannot be reopened by name in standalone?
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])

# ---------- Writing ----------
def _options_dict(options):
    d={}
    if options:
        for opt in options:
            if isinstance(opt,tuple) and len(opt)==2:
                d[str(opt[0]).upper()]=str(opt[1])
            elif isinstance(opt,dict):
                for k,v in opt.items(): d[str(k).upper()]=str(v)
            else:
                s=str(opt)
                if "=" in s:
                    k,v=s.split("=",1); d[k.upper()]=v
    return d

def _bool_opt(v, default=False):
    if v is None:return default
    return str(v).upper() in ("YES","TRUE","1","ON")

def _compact_json_value(v, field=None, sig_figs=17, coord_decimals=None):
    import json as _json
    if v is None:return "null"
    if isinstance(v,bool):return "true" if v else "false"
    if field and field.type=="Integer" and field.subtype=="Boolean":
        return "true" if v else "false"
    if isinstance(v,int):return str(v)
    if isinstance(v,float):
        s=format(v,f'.{sig_figs}g')
        if re.fullmatch(r'-?\d+',s): s+=".0"
        return s
    if isinstance(v,str):
        if field and field.subtype=="JSON":
            t=v.strip()
            if t.startswith("{") or t.startswith("["):
                try:
                    parsed=json.loads(v)
                    return _compact_json_value(parsed,None,sig_figs)
                except Exception:
                    pass
        return _json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):
        return "["+",".join(_compact_json_value(x,None,sig_figs) for x in v)+"]"
    if isinstance(v,dict):
        return "{"+",".join(_json.dumps(str(k),ensure_ascii=False)+":"+_compact_json_value(val,None,sig_figs) for k,val in v.items())+"}"
    return _json.dumps(str(v),ensure_ascii=False)

def _geom_compact(geom, coord_decimals=15):
    if geom is None:return "null"
    t=geom.get("type")
    if t=="LinearRing": t="LineString"
    if t=="GeometryCollection" or "geometries" in geom:
        return '{"type":"GeometryCollection","geometries":['+",".join(_geom_compact(g,coord_decimals) for g in geom.get("geometries",[]))+"]}"
    def coord_str(c):
        if isinstance(c,list):
            if len(c)>0 and isinstance(c[0],(int,float)):
                return "["+",".join(format_coord(float(x),coord_decimals) for x in c)+"]"
            return "["+",".join(coord_str(x) for x in c)+"]"
        return str(c)
    return '{"type":'+json.dumps(t)+',"coordinates":'+coord_str(geom.get("coordinates",[]))+"}"

def write_geojson(ds, path, layer_options=None, creation_options=None, output_layer=None):
    opts=_options_dict(layer_options)
    copts=_options_dict(creation_options)
    opts.update(copts)  # creation opts for geojson are mostly layer opts passed via --lco in ops; callers pass properly
    rfc7946=_bool_opt(opts.get("RFC7946"),False)
    coord_dec=15
    if "COORDINATE_PRECISION" in opts:
        try: coord_dec=int(opts["COORDINATE_PRECISION"])
        except: coord_dec=15
    elif rfc7946:
        coord_dec=7
    sig=17
    if "SIGNIFICANT_FIGURES" in opts:
        try:sig=int(opts["SIGNIFICANT_FIGURES"])
        except: sig=17
    write_name=_bool_opt(opts.get("WRITE_NAME"),True)
    write_bbox=_bool_opt(opts.get("WRITE_BBOX"),False)
    # only first layer for single GeoJSON file (GDAL GeoJSON driver supports single layer; if multiple layers and output file, second layer error? We'll write first)
    layer=ds.layers[0] if ds.layers else Layer(output_layer or _basename_layer(path),[],[],"Unknown (any)",None)
    name=output_layer or layer.name
    lines=[]
    lines.append("{")
    lines.append('"type": "FeatureCollection",')
    if write_name and not rfc7946:
        lines.append(f'"name": {json.dumps(name,ensure_ascii=False)},')
    if opts.get("DESCRIPTION"):
        lines.append(f'"description": {json.dumps(opts["DESCRIPTION"],ensure_ascii=False)},')
    if layer.crs and not rfc7946:
        urn=None
        if layer.crs.epsg==4326:
            urn="urn:ogc:def:crs:OGC:1.3:CRS84"
        elif layer.crs.epsg:
            urn=f"urn:ogc:def:crs:EPSG::{layer.crs.epsg}"
        elif layer.crs.name:
            urn=layer.crs.name
        if urn:
            lines.append('"crs": { "type": "name", "properties": { "name": '+json.dumps(urn,ensure_ascii=False)+' } },')
    if write_bbox:
        ext=layer.extent()
        if ext:
            lines.append('"bbox": ['+",".join(format_coord(v,coord_dec) for v in ext)+'],')
    lines.append('"features": [')
    feat_lines=[]
    for feat in layer.features:
        props_items=[]
        # Properties in field order, skip unset
        if layer.fields:
            for fld in layer.fields:
                if fld.name in feat.properties:
                    v=feat.properties[fld.name]
                    props_items.append(json.dumps(fld.name,ensure_ascii=False)+":"+_compact_json_value(v,fld,sig))
            # also any properties not in schema (preserve in feat order after)
            field_names={f.name for f in layer.fields}
            for k,v in feat.properties.items():
                if k not in field_names:
                    props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        else:
            for k,v in feat.properties.items():
                props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        feat_str='{"type":"Feature","properties":{'+",".join(props_items)+'}'
        if write_bbox and feat.geometry is not None:
            b=geommod.bbox(feat.geometry)
            if b:
                feat_str+=',"bbox":['+",".join(format_coord(v,coord_dec) for v in b)+']'
        feat_str+=',"geometry":'+_geom_compact(feat.geometry,coord_dec)+'}'
        feat_lines.append(feat_str)
    content="\n".join(lines)+"\n"
    if feat_lines:
        content+=",\n".join(feat_lines)+"\n"
    content+="]\n}\n"
    vfs.write_binary(path, content.encode("utf-8"))

def write_geojsonseq(ds,path,layer_options=None,creation_options=None,output_layer=None):
    opts=_options_dict(layer_options); opts.update(_options_dict(creation_options))
    coord_dec=15
    if "COORDINATE_PRECISION" in opts:
        try:coord_dec=int(opts["COORDINATE_PRECISION"])
        except:pass
    sig=17
    layer=ds.layers[0] if ds.layers else Layer("layer",[],[])
    out=[]
    prefix="\x1e" if _bool_opt(opts.get("RS"),False) else ""
    for feat in layer.features:
        props_items=[]
        if layer.fields:
            for fld in layer.fields:
                if fld.name in feat.properties:
                    props_items.append(json.dumps(fld.name,ensure_ascii=False)+":"+_compact_json_value(feat.properties[fld.name],fld,sig))
            fn={f.name for f in layer.fields}
            for k,v in feat.properties.items():
                if k not in fn: props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        else:
            for k,v in feat.properties.items(): props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        out.append(prefix+'{"type":"Feature","properties":{'+",".join(props_items)+',"geometry":'+_geom_compact(feat.geometry,coord_dec)+'}')
    content="\n".join(out)
    if out: content+="\n"
    vfs.write_binary(path, content.encode("utf-8"))

def guess_vector_driver(output, output_format=None):
    if output_format:
        fmt=str(output_format)
        # normalized case-insensitive match against driver short names
        for dn in ["GeoJSON","GeoJSONSeq","ESRI Shapefile","MEM"]:
            if fmt.lower()==dn.lower():
                return dn
        return fmt  # caller validates
    p=str(output).lower()
    if p.endswith((".geojsonl",".geojsons")): return "GeoJSONSeq"
    if p.endswith((".geojson",".json")): return "GeoJSON"
    if p.endswith((".shp",".shp.zip",".shz",".dbf")): return "ESRI Shapefile"
    return None

def write_vector_dataset(ds, path, output_format=None, creation_options=None, layer_creation_options=None, output_layer=None, overwrite=False, append=False, update=False):
    drv=guess_vector_driver(path, output_format)
    if drv is None:
        return None
    if drv=="GeoJSON":
        write_geojson(ds,path,layer_creation_options,creation_options,output_layer)
    elif drv=="GeoJSONSeq":
        write_geojsonseq(ds,path,layer_creation_options,creation_options,output_layer)
    elif drv=="ESRI Shapefile":
        write_shapefile(ds,path,layer_creation_options,creation_options,output_layer)
    elif drv=="MEM":
        pass
    else:
        return None
    return drv
