    if v is None:
        return None
    t=field.type
    if t=="Integer" and field.subtype=="Boolean":
        return 1 if bool(v) else 0
    if t in ("Integer","Integer64"):
        return int(v)
    if t=="Real":
        return float(v)
    if t=="String" and field.subtype=="JSON":
        if isinstance(v,str):
            return v
        if isinstance(v,(dict,list)):
            return json_text_value(v)
        if isinstance(v,bool):
            return "true" if v else "false"
        if isinstance(v,float):
            # .17g?
            s=format(v,'.17g')
            return s
        return str(v)
    if t=="String":
        return v if isinstance(v,str) else str(v)
    if t=="IntegerList" or t=="Integer64List":
        return [int(x) for x in v]
    if t=="RealList":
        return [float(x) for x in v]
    if t=="StringList":
        return [str(x) for x in v]
    if t in ("Date","DateTime","Time"):
        return str(v)
    return v

def _layer_geom_type(features):
    types=[]
    for f in features:
        if f.geometry is not None:
            types.append(geommod.geom_type_name(f.geometry))
    if not types:
        return "Unknown (any)"
    uniq=[]
    for t in types:
        if t not in uniq: uniq.append(t)
    if len(uniq)==1:
        return uniq[0]
    # Promotion rules: Point+MultiPoint -> MultiPoint? OGR GeoJSON driver with mixed singular/multi often geometry Unknown. Keep Unknown.
    return "Unknown (any)"

def _parse_geojson_crs(crs_obj):
    if not isinstance(crs_obj,dict):
        return crsmod.geojson_crs()
    if crs_obj.get("type")=="name":
        props=crs_obj.get("properties") or {}
        name=props.get("name") or ""
        if name in ("urn:ogc:def:crs:OGC:1.3:CRS84","CRS84","urn:ogc:def:crs:OGC:1.3:CRS84h"):
            return crsmod.geojson_crs()
        c,err,ok=crsmod.parse_crs_input(name)
        return c if ok else None
    return crsmod.geojson_crs()

def _normalize_geom(g):
    if g is None or not isinstance(g,dict):
        return None
    # GeometryCollection may have geometries
    gg=copy.deepcopy(g)
    # Remove foreign bbox etc? Keep only type/coordinates/geometries
    out={"type":gg.get("type")}
    if "coordinates" in gg:
        out["coordinates"]=_float_coords(gg["coordinates"])
    if "geometries" in gg:
        out["geometries"]=[_normalize_geom(x) for x in gg["geometries"]]
        out["type"]="GeometryCollection"
    return out

def _float_coords(c):
    if isinstance(c,(list,tuple)):
        if len(c)>0 and isinstance(c[0],(int,float)) and not isinstance(c[0],bool):
            return [float(x) for x in c]
        return [_float_coords(x) for x in c]
    return c

def open_geojson(path, data=None, driver_short="GeoJSON", open_options=None):
    if data is None:
        data=vfs.read_binary(path)
    text=data.decode("utf-8",errors="replace")
    try:
        obj=json.loads(text)
    except Exception as e:
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    # maybe warn big ints: search raw token? Ignore for now.
    layers=[]
    if isinstance(obj,dict) and obj.get("type")=="FeatureCollection":
        layer_name=obj.get("name") or _basename_layer(path)
        crs=_parse_geojson_crs(obj.get("crs")) if "crs" in obj else crsmod.geojson_crs()
        features_raw=[]; geoms=[]; fids=[]
        for feat in obj.get("features") or []:
            props=[]
            if "id" in feat:
                props.append(("id", feat.get("id")))
            properties=feat.get("properties") or {}
            if isinstance(properties,dict):
                for k,v in properties.items():
                    # avoid duplicate id if later id property overrides? Keep first id from member if duplicate key - properties will be in dict(fr) last wins but duplicates list has two entries, dict(fr) chooses last; okay
                    props.append((k,v))
            features_raw.append(props)
            geoms.append(_normalize_geom(feat.get("geometry")) if feat.get("geometry") is not None else None)
        fields,converted=infer_fields_and_convert(features_raw)
        features=[Feature(i,converted[i],geoms[i]) for i in range(len(geoms))]
        layer=Layer(layer_name,fields,features,_layer_geom_type(features),crs)
        layers.append(layer)
    elif isinstance(obj,dict) and obj.get("type")=="Feature":
        layer_name=_basename_layer(path)
        props=[]
        if "id" in obj: props.append(("id",obj.get("id")))
        for k,v in (obj.get("properties") or {}).items(): props.append((k,v))
        fields,converted=infer_fields_and_convert([props])
        features=[Feature(0,converted[0],_normalize_geom(obj.get("geometry")))]
        layers.append(Layer(layer_name,fields,features,_layer_geom_type(features),crsmod.geojson_crs()))
    elif isinstance(obj,dict) and obj.get("type") in geommod.GEOM_TYPES:
        layer_name=_basename_layer(path)
        features=[Feature(0,{},_normalize_geom(obj))]
        layers.append(Layer(layer_name,[],features,_layer_geom_type(features),crsmod.geojson_crs()))
    elif isinstance(obj,list):
        # array of features?
        features_raw=[]; geoms=[]
        for feat in obj:
            if isinstance(feat,dict) and feat.get("type")=="Feature":
                props=[]
                if "id" in feat: props.append(("id",feat.get("id")))
                for k,v in (feat.get("properties") or {}).items(): props.append((k,v))
                features_raw.append(props); geoms.append(_normalize_geom(feat.get("geometry")))
        fields,converted=infer_fields_and_convert(features_raw)
        features=[Feature(i,converted[i],geoms[i]) for i in range(len(geoms))]
        layers.append(Layer(_basename_layer(path),fields,features,_layer_geom_type(features),crsmod.geojson_crs()))
    else:
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    return VectorDataset(driver_short,driver_short,path,layers)

def open_geojsonseq(path, data=None):
    if data is None: data=vfs.read_binary(path)
    text=data.decode("utf-8",errors="replace")
    lines=[]
    for part in re.split(r'[\n\x1e]+', text):
        p=part.strip()
        if p: lines.append(p.lstrip("\x1e"))
    features_raw=[]; geoms=[]
    for line in lines:
        try: obj=json.loads(line)
        except: continue
        if obj.get("type")=="Feature":
            props=[]
            if "id" in obj: props.append(("id",obj.get("id")))
            for k,v in (obj.get("properties") or {}).items(): props.append((k,v))
            features_raw.append(props); geoms.append(_normalize_geom(obj.get("geometry")))
        elif obj.get("type") in geommod.GEOM_TYPES:
            features_raw.append([]); geoms.append(_normalize_geom(obj))
    fields,converted=infer_fields_and_convert(features_raw)
    features=[Feature(i,converted[i],geoms[i]) for i in range(len(geoms))]
    layer=Layer(_basename_layer(path),fields,features,_layer_geom_type(features),crsmod.geojson_crs())
    return VectorDataset("GeoJSONSeq","GeoJSON Sequence",path,[layer])

def open_esrijson(path,data=None):
    if data is None: data=vfs.read_binary(path)
    obj=json.loads(data.decode("utf-8",errors="replace"))
    if not isinstance(obj,dict) or "geometryType" not in obj:
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    fields=[]
    type_map={"esriFieldTypeString":"String","esriFieldTypeInteger":"Integer","esriFieldTypeSmallInteger":"Integer","esriFieldTypeDouble":"Real","esriFieldTypeDate":"DateTime","esriFieldTypeOID":"Integer64"}
    for fld in obj.get("fields",[]):
        name=fld.get("name")
        if name:
            fields.append(Field(name,type_map.get(fld.get("type"),"String"),width=fld.get("length",0) or 0))
    sr=obj.get("spatialReference") or {}
    wkid=sr.get("latestWkid") or sr.get("wkid")
    crs=crsmod.epsg_crs(int(wkid),"epsg_db") if wkid else crsmod.geojson_crs()
    geom_type_esri=obj.get("geometryType")
    features=[]
    for i,feat in enumerate(obj.get("features",[])):
        attrs=feat.get("attributes") or {}
        # field conversion if predefined fields empty, infer later? use given props as-is with conversion per fields
        props={}
        for f in fields:
            if f.name in attrs:
                props[f.name]=_convert_value(attrs[f.name],f)
        if not fields:
            props=dict(attrs)
        geom=_esri_geom_to_geojson(feat.get("geometry"), geom_type_esri)
        features.append(Feature(i,props,geom))
    if not fields and features:
        fields_raw=[[ (k,v) for k,v in f.properties.items()] for f in features]
        fields,converted=infer_fields_and_convert(fields_raw)
        for f,c in zip(features,converted): f.properties=c
    layer=Layer(_basename_layer(path),fields,features,_layer_geom_type(features),crs)
    return VectorDataset("ESRIJSON","ESRIJSON",path,[layer])

def _esri_geom_to_geojson(g, gtype):
    if not g: return None
    if "x" in g and "y" in g:
        coords=[float(g["x"]),float(g["y"])]
        if "z" in g: coords.append(float(g["z"]))
        if "m" in g: coords.append(float(g["m"]))
        return {"type":"Point","coordinates":coords}
    if "points" in g:
        return {"type":"MultiPoint","coordinates":_float_coords(g["points"])}
    if "paths" in g:
        paths=_float_coords(g["paths"])
        if len(paths)==1:
            return {"type":"LineString","coordinates":paths[0]}
        return {"type":"MultiLineString","coordinates":paths}
    if "rings" in g:
        rings=_float_coords(g["rings"])
        return {"type":"Polygon","coordinates":rings}
    return None

def open_topojson(path,data=None):
    if data is None: data=vfs.read_binary(path)
    obj=json.loads(data.decode("utf-8",errors="replace"))
    if not isinstance(obj,dict) or obj.get("type")!="Topology":
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    arcs=obj.get("arcs",[])
    transform=obj.get("transform") or {}
    scale=transform.get("scale",[1,1]); translate=transform.get("translate",[0,0])
    def decode_arc(arc):
        pts=[]; x=0; y=0
        for pt in arc:
            if transform:
                x+=pt[0]; y+=pt[1]
                pts.append([x*scale[0]+translate[0], y*scale[1]+translate[1]])
            else:
                pts.append([float(pt[0]),float(pt[1])])
        return pts
    decoded=[decode_arc(a) for a in arcs]
    def arc_coords(idx):
        if idx>=0:
            return decoded[idx][:]
        else:
            return list(reversed(decoded[~idx]))
    def stitch(indexes):
        coords=[]
        for idx in indexes:
            seg=arc_coords(idx)
            if coords and seg and coords[-1]==seg[0]:
                coords.extend(seg[1:])
            else:
                coords.extend(seg)
        return coords
    def topo_geom(o):
        if o is None:return None
        t=o.get("type")
        if t=="Point":
            c=o.get("coordinates")
            if transform: c=[c[0]*scale[0]+translate[0],c[1]*scale[1]+translate[1]]
            return {"type":"Point","coordinates":_float_coords(c)}
        if t=="MultiPoint":
            pts=[]
            for c in o.get("coordinates",[]):
                if transform:c=[c[0]*scale[0]+translate[0],c[1]*scale[1]+translate[1]]
                pts.append(c)
            return {"type":"MultiPoint","coordinates":_float_coords(pts)}
        if t=="LineString":
            return {"type":"LineString","coordinates":stitch(o.get("arcs",[]))}
        if t=="MultiLineString":
            return {"type":"MultiLineString","coordinates":[stitch(a) for a in o.get("arcs",[])]}
        if t=="Polygon":
            return {"type":"Polygon","coordinates":[stitch(a) for a in o.get("arcs",[])]}
        if t=="MultiPolygon":
            return {"type":"MultiPolygon","coordinates":[[stitch(a) for a in poly] for poly in o.get("arcs",[])]}
        if t=="GeometryCollection":
            return {"type":"GeometryCollection","geometries":[topo_geom(g) for g in o.get("geometries",[])]}
        return None
    layers=[]
    for name, o in (obj.get("objects") or {}).items():
        geoms=[]
        if o.get("type")=="GeometryCollection":
            items=o.get("geometries",[])
        else:
            items=[o]
        features_raw=[]; gms=[]
        for item in items:
            props=[]
            if "id" in item: props.append(("id",item.get("id")))
            for k,v in (item.get("properties") or {}).items(): props.append((k,v))
            features_raw.append(props); gms.append(topo_geom(item))
        fields,converted=infer_fields_and_convert(features_raw)
        features=[Feature(i,converted[i],gms[i]) for i in range(len(gms))]
        layers.append(Layer(name,fields,features,_layer_geom_type(features),crsmod.geojson_crs()))
    return VectorDataset("TopoJSON","TopoJSON",path,layers)

# Shapefile implementation in separate module imported late to keep file manageable
from shapefile import open_shapefile, write_shapefile

def identify_vector_driver(path):
    # Return driver short name if recognized by extension/content, else None
    p=str(path)
    lower=p.lower()
    if vfs.is_dir(path):
        # directory may be shapefile dataset if contains shp/dbf
        try:
            names=vfs.list_dir(path)
            if any(n.lower().endswith((".shp",".dbf")) for n in names):
                return "ESRI Shapefile"
        except Exception: pass
        return None
    if lower.endswith((".shp",".dbf",".shz")) or lower.endswith(".shp.zip"):
        return "ESRI Shapefile"
    if lower.endswith((".geojsonl",".geojsons")):
        return "GeoJSONSeq"
    # need read content for json variants and extensionless
    try:
        data=vfs.read_binary(path)[:200000]
    except Exception:
        return None
    # quick binary check shape file code 9994
    if len(data)>=4 and data[:4]==b'\x00\x00\x27\x0a':
        return "ESRI Shapefile"
    text=data[:100000].decode("utf-8",errors="ignore").lstrip("\x1e \t\r\n")
    if text.startswith("{") or text.startswith("["):
        # Look for topology / esri indicators in head
        head=text[:5000]
        if '"type"' in head and '"Topology"' in head:
            return "TopoJSON"
        if '"geometryType"' in head and 'esri' in head.lower():
            return "ESRIJSON"
        # Could parse first json if small enough
        if lower.endswith((".geojson",".json",".topojson")) or lower.endswith(".txt") or "." not in os.path.basename(lower):
            # Try full parse if file size not huge? data may truncated - attempt read all in open stage identifies better. For identify heuristic:
            if '"arcs"' in head and '"objects"' in head:
                return "TopoJSON"
            if '"spatialReference"' in head and '"features"' in head:
                return "ESRIJSON"
            return "GeoJSON"
        return "GeoJSON"
    # GeoJSONSeq lines start with { handled above
    return None

def open_vector_dataset(path, input_formats=None, open_options=None, update=False):
    # open_options dict/list ignored for now except maybe
    if not vfs.exists(path) and not vfs.is_stdin_path(path):
        raise VectorOpenError([f"ERROR 4: {path}: No such file or directory"])
    driver=identify_vector_driver(path)
    # Input format restriction check in caller layer? Implement basic: if formats supplied and driver not in, error not recognized
    if input_formats:
        fmts=[str(f) for f in input_formats]
        if driver and driver not in fmts:
            raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
        if driver is None and fmts:
            # If format specified is GeoJSON etc, try that parser
            driver=fmts[0]
    if driver is None:
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    if driver=="GeoJSON":
        # Need distinguish Esri/Topo by content full parse maybe
        try:
            return open_geojson(path)
        except VectorOpenError:
            # try topo/esri
            data=vfs.read_binary(path)
            try:
                return open_topojson(path,data)
            except Exception:
                pass
            try:
                return open_esrijson(path,data)
            except Exception:
                pass
            raise
    elif driver=="GeoJSONSeq":
        return open_geojsonseq(path)
    elif driver=="ESRI Shapefile":
        return open_shapefile(path)
    elif driver=="TopoJSON":
        return open_topojson(path)
    elif driver=="ESRIJSON":
        return open_esrijson(path)
    elif driver=="MEM":
        # MEM output datasets cannot be reopened by name in standalone?
        raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])
    raise VectorOpenError([f"ERROR 4: `{path}' not recognized as being in a supported file format."])

# ---------- Writing ----------
def _options_dict(options):
    d={}
    if options:
        for opt in options:
            if isinstance(opt,tuple) and len(opt)==2:
                d[str(opt[0]).upper()]=str(opt[1])
            elif isinstance(opt,dict):
                for k,v in opt.items(): d[str(k).upper()]=str(v)
            else:
                s=str(opt)
                if "=" in s:
                    k,v=s.split("=",1); d[k.upper()]=v
    return d

def _bool_opt(v, default=False):
    if v is None:return default
    return str(v).upper() in ("YES","TRUE","1","ON")

def _compact_json_value(v, field=None, sig_figs=17, coord_decimals=None):
    import json as _json
    if v is None:return "null"
    if isinstance(v,bool):return "true" if v else "false"
    if field and field.type=="Integer" and field.subtype=="Boolean":
        return "true" if v else "false"
    if isinstance(v,int):return str(v)
    if isinstance(v,float):
        s=format(v,f'.{sig_figs}g')
        if re.fullmatch(r'-?\d+',s): s+=".0"
        return s
    if isinstance(v,str):
        if field and field.subtype=="JSON":
            t=v.strip()
            if t.startswith("{") or t.startswith("["):
                try:
                    parsed=json.loads(v)
                    return _compact_json_value(parsed,None,sig_figs)
                except Exception:
                    pass
        return _json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):
        return "["+",".join(_compact_json_value(x,None,sig_figs) for x in v)+"]"
    if isinstance(v,dict):
        return "{"+",".join(_json.dumps(str(k),ensure_ascii=False)+":"+_compact_json_value(val,None,sig_figs) for k,val in v.items())+"}"
    return _json.dumps(str(v),ensure_ascii=False)

def _geom_compact(geom, coord_decimals=15):
    if geom is None:return "null"
    t=geom.get("type")
    if t=="LinearRing": t="LineString"
    if t=="GeometryCollection" or "geometries" in geom:
        return '{"type":"GeometryCollection","geometries":['+",".join(_geom_compact(g,coord_decimals) for g in geom.get("geometries",[]))+"]}"
    def coord_str(c):
        if isinstance(c,list):
            if len(c)>0 and isinstance(c[0],(int,float)):
                return "["+",".join(format_coord(float(x),coord_decimals) for x in c)+"]"
            return "["+",".join(coord_str(x) for x in c)+"]"
        return str(c)
    return '{"type":'+json.dumps(t)+',"coordinates":'+coord_str(geom.get("coordinates",[]))+"}"

def write_geojson(ds, path, layer_options=None, creation_options=None, output_layer=None):
    opts=_options_dict(layer_options)
    copts=_options_dict(creation_options)
    opts.update(copts)  # creation opts for geojson are mostly layer opts passed via --lco in ops; callers pass properly
    rfc7946=_bool_opt(opts.get("RFC7946"),False)
    coord_dec=15
    if "COORDINATE_PRECISION" in opts:
        try: coord_dec=int(opts["COORDINATE_PRECISION"])
        except: coord_dec=15
    elif rfc7946:
        coord_dec=7
    sig=17
    if "SIGNIFICANT_FIGURES" in opts:
        try:sig=int(opts["SIGNIFICANT_FIGURES"])
        except: sig=17
    write_name=_bool_opt(opts.get("WRITE_NAME"),True)
    write_bbox=_bool_opt(opts.get("WRITE_BBOX"),False)
    # only first layer for single GeoJSON file (GDAL GeoJSON driver supports single layer; if multiple layers and output file, second layer error? We'll write first)
    layer=ds.layers[0] if ds.layers else Layer(output_layer or _basename_layer(path),[],[],"Unknown (any)",None)
    name=output_layer or layer.name
    lines=[]
    lines.append("{")
    lines.append('"type": "FeatureCollection",')
    if write_name and not rfc7946:
        lines.append(f'"name": {json.dumps(name,ensure_ascii=False)},')
    if opts.get("DESCRIPTION"):
        lines.append(f'"description": {json.dumps(opts["DESCRIPTION"],ensure_ascii=False)},')
    if layer.crs and not rfc7946:
        urn=None
        if layer.crs.epsg==4326:
            urn="urn:ogc:def:crs:OGC:1.3:CRS84"
        elif layer.crs.epsg:
            urn=f"urn:ogc:def:crs:EPSG::{layer.crs.epsg}"
        elif layer.crs.name:
            urn=layer.crs.name
        if urn:
            lines.append('"crs": { "type": "name", "properties": { "name": '+json.dumps(urn,ensure_ascii=False)+' } },')
    if write_bbox:
        ext=layer.extent()
        if ext:
            lines.append('"bbox": ['+",".join(format_coord(v,coord_dec) for v in ext)+'],')
    lines.append('"features": [')
    feat_lines=[]
    for feat in layer.features:
        props_items=[]
        # Properties in field order, skip unset
        if layer.fields:
            for fld in layer.fields:
                if fld.name in feat.properties:
                    v=feat.properties[fld.name]
                    props_items.append(json.dumps(fld.name,ensure_ascii=False)+":"+_compact_json_value(v,fld,sig))
            # also any properties not in schema (preserve in feat order after)
            field_names={f.name for f in layer.fields}
            for k,v in feat.properties.items():
                if k not in field_names:
                    props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        else:
            for k,v in feat.properties.items():
                props_items.append(json.dumps(k,ensure_ascii=False)+":"+_compact_json_value(v,None,sig))
        feat_str='{"type":"Feature","properties":{'+",".join(props_items)+'}'
        if write_bbox and feat.geometry is not None:
            b=geommod.bbox(feat.geometry)
            if b:
                feat_str+=',"bbox":['+",".join(format_coord(v,coord_dec) for v in b)+']'
        feat_str+=',"geometry":'+_geom_compact(feat.geometry,coord_dec)+'}'
        feat_lines.append(feat_str)
    content="\n".join(lines)+"\n"
    if feat_lines:
        content+=",\n".join(feat_lines)+"\n"
    content+="]\n}\n"
    vfs.write_binary(path, content.encode("utf-8"))

def write_geojsonseq(ds,path,layer_options=None,creation_options=None,output_layer=None):
    opts=_options_dict(layer_options); opts.update(_options_dict(creation_options))
    coord_dec=15
    if "COORDINATE_PRECISION" in opts:
        try:coord_dec=int(opts["COORDINATE_PRECISION"])
        except:pass
    sig=17
    layer=ds.layers[0] if ds.layers else Layer("layer",[],[])
    out=[]
    prefix="\x1e" if _bool_opt(opts.get("RS"),False) else ""
    for feat in layer.features:
        props_items=[]
        if layer.fields:
            for fld in layer.fields:
                if fld.name in feat.properties:
                    props_items.append(json.dumps(fld.name,ensure_ascii=False)+":"+_compact_json_value(feat.properties[fld.name],fld,sig))
