    closed = ring[0]==ring[-1]
    core=ring[:-1] if closed else ring[:]
    if len(core)<=1: return ring
    flipped=[core[0]]+list(reversed(core[1:]))
    if closed:
        flipped.append(core[0])
    return flipped

def _bbox_pts(pts):
    if not pts: return (0.0,0.0,0.0,0.0)
    return (min(p[0] for p in pts),min(p[1] for p in pts),max(p[0] for p in pts),max(p[1] for p in pts))

def _parts_content(shape_type, seqs, geom):
    pts=[]
    starts=[]
    for seq in seqs:
        starts.append(len(pts))
        for c in seq:
            pts.append([float(c[0]),float(c[1])])
    bbox=_bbox_pts(pts)
    out=struct.pack("<i",shape_type)+struct.pack("<dddd",*bbox)+struct.pack("<ii",len(seqs),len(pts))
    out+=struct.pack("<"+"i"*len(starts),*starts) if starts else b""
    for p in pts: out+=struct.pack("<dd",*p)
    if shape_type in (13,15):
        # Z range and array, M range/array 0
        zs=[]
        allcoords=[]
        for seq in seqs:
            for c in seq: allcoords.append(c)
        for c in allcoords:
            zs.append(float(c[2]) if len(c)>2 else 0.0)
        if zs:
            out+=struct.pack("<dd",min(zs),max(zs))+struct.pack("<"+"d"*len(zs),*zs)
            out+=struct.pack("<dd",0.0,0.0)+struct.pack("<"+"d"*len(zs),*([0.0]*len(zs)))
