def _shp_header(file_length_bytes, shape_type, bbox8):
    # bbox8: xmin,ymin,xmax,ymax,zmin,zmax,mmin,mmax
    h=bytearray(100)
    struct.pack_into(">i",h,0,9994)
    struct.pack_into(">i",h,24,file_length_bytes//2)
    struct.pack_into("<i",h,28,1000)
    struct.pack_into("<i",h,32,shape_type)
    struct.pack_into("<dddddddd",h,36,*bbox8)
    return bytes(h)

