def _make_dbf(layer, dbf_fields):
    num=len(layer.features)
    header_len=32+32*len(dbf_fields)+1
    record_len=1+sum(f["width"] for f in dbf_fields)
    today=datetime.date.today()
    header=bytearray(32)
    header[0]=0x03
    header[1]=today.year-1900
    header[2]=today.month
    header[3]=today.day
    struct.pack_into("<I",header,4,num)
    struct.pack_into("<H",header,8,header_len)
    struct.pack_into("<H",header,10,record_len)
    header[29]=0x57
    out=bytearray(header)
    for f in dbf_fields:
        desc=bytearray(32)
        name_bytes=f["name"].encode("utf-8")[:10]
        desc[0:len(name_bytes)]=name_bytes
        desc[11]=ord(f["dbf_type"])
        desc[16]=f["width"]
        desc[17]=f["dec"]
        out.extend(desc)
    out.append(0x0D)
    for idx,feat in enumerate(layer.features):
        rec=bytearray()
        rec.append(0x20)
        for f in dbf_fields:
            if f.get("dummy_fid"):
                value=idx
                is_set=True
            else:
                is_set=f["src_name"] in feat.properties
                value=feat.properties.get(f["src_name"]) if is_set else None
            rec.extend(_format_dbf_value(value,f,is_set))
        out.extend(rec)
    out.append(0x1A)
    return bytes(out)

def _format_dbf_value(value,f,is_set):
    w=f["width"]
    if not is_set or value is None:
        return b' '*w
    t=f["dbf_type"]
    if t=='C':
        if f.get("ogr_type")=="String" and isinstance(value,(list,dict)):
            from vectorio import json_text_value
            s=json_text_value(value)
        else:
            s=str(value)
        b=s.encode("utf-8")[:w]
        return b + b' '*(w-len(b))
    if t=='N':
        try:
            if f["dec"]>0:
                s=f"{float(value):.{f['dec']}f}"
            else:
                s=str(int(value))
        except Exception:
            s=str(value)
        if len(s)>w:
            # overflow: GDAL writes asterisks? It might truncate/warn. Use asterisks for numeric overflow as DBF convention
            return b'*'*w
        return s.rjust(w).encode()
    if t=='D':
        s=str(value).replace("-","").replace("/","")[:8]
        return s.ljust(w).encode()
    if t=='L':
        return b'T' if value else b'F'
    return str(value)[:w].ljust(w).encode()
