def _shape_type_to_geom_type(t):
    mapping={0:"Unknown (any)",1:"Point",3:"LineString",5:"Polygon",8:"MultiPoint",11:"Point Z",13:"LineString Z",15:"Polygon Z",18:"MultiPoint Z",21:"Point M",23:"LineString M",25:"Polygon M",28:"MultiPoint M",31:"MultiPatch"}
    if t in (11,13,15,18):
        # Types with Z and M in shapefile are ZM in OGR? Shape types 11 etc include m values optionally; OGR treats as ... If m values absent it may be Z. Use Z for now as probes likely point from geojson 2d only.
        pass
    return mapping.get(t,"Unknown (any)")

def _parse_dbf(data):
    if len(data)<32:
        return [],[],None
    version=data[0]
    y,m,d=data[1],data[2],data[3]
    dbf_date=None
    if y or m or d:
        dbf_date=f"{1900+y:04d}-{m:02d}-{d:02d}"
    num_records=struct.unpack("<I",data[4:8])[0]
    header_len=struct.unpack("<H",data[8:10])[0]
    record_len=struct.unpack("<H",data[10:12])[0]
    fields=[]
    descriptors=[]
    off=32
    while off+32<=len(data) and data[off]!=0x0D:
        desc=data[off:off+32]
        name=desc[0:11].split(b"\x00")[0].decode("utf-8",errors="replace")
        ftype=chr(desc[11])
        flen=desc[16]; fdec=desc[17]
        descriptors.append((name,ftype,flen,fdec))
        fields.append(_dbf_field_to_ogr(name,ftype,flen,fdec))
        off+=32
    records=[]
    rec_off=header_len
    enc="utf-8"
    for i in range(num_records):
        if rec_off+record_len>len(data): break
        rec=data[rec_off:rec_off+record_len]; rec_off+=record_len
        if not rec: continue
        if rec[0:1]==b'*':
            continue  # deleted - OGR skips? It counts? For our purposes skip and maintain fid mismatch - rare
        pos=1; props={}
        for (name,ftype,flen,fdec),fld in zip(descriptors,fields):
            raw=rec[pos:pos+flen]; pos+=flen
            value, is_set=_dbf_value(raw,ftype,fdec,fld)
            if is_set:
                props[fld.name]=value
        records.append(props)
    return fields, records, dbf_date

def _dbf_field_to_ogr(name,ftype,flen,fdec):
    if ftype=='C':
        return Field(name,"String",width=flen)
    if ftype=='N' or ftype=='F':
        if fdec>0:
            return Field(name,"Real",width=flen,precision=fdec)
        else:
            if flen>9 or ftype=='F':
                # F with 0 decimals is treated as Integer64? Need not.
                if ftype=='F': return Field(name,"Real",width=flen,precision=fdec)
                return Field(name,"Integer64",width=flen)
            return Field(name,"Integer",width=flen)
    if ftype=='D':
        return Field(name,"Date")
    if ftype=='L':
        return Field(name,"Integer",subtype="Boolean",width=1)
    if ftype=='I':
        return Field(name,"Integer",width=flen)
    if ftype=='Y':
        return Field(name,"Integer64",width=flen)
    return Field(name,"String",width=flen)

def _dbf_value(raw,ftype,fdec,field):
    text=raw.decode("utf-8",errors="replace")
    if ftype=='C':
        # Character fields are left justified, space padded. OGR returns trimmed trailing spaces (and maybe leading?)
        value=text.rstrip(" \x00")
        if value.strip()=="":
            # For an empty string field, GDAL feature dump may be unset? In shape record empty string becomes unset (?) Feature IsFieldSet false if all spaces
            return None, False
        return value, True
    if ftype in ('N','F','I','Y'):
        t=text.strip()
        if t=="" or set(t)=={"*"}:
            return None, False
        try:
            if field.type=="Real":
                return float(t), True
            elif field.type in ("Integer","Integer64"):
                # could have decimal point if N with decimals but field integer? parse int(float?) avoid
                return int(float(t)), True if '.' in t else int(t), True
            else:
                return float(t), True
        except Exception:
            return None, False
    if ftype=='D':
        t=text.strip()
        if t=="" or t=="00000000":
            return None,False
        if len(t)==8:
            return f"{t[0:4]}-{t[4:6]}-{t[6:8]}",True
        return t,True
    if ftype=='L':
        t=text.strip()
        if t in ('T','t','Y','y','1'): return 1,True
        if t in ('F','f','N','n','0'): return 0,True
        return None,False
    t=text.strip()
    return (t,True) if t else (None,False)

def _parse_shp(data):
    if len(data)<100: return [],0
    shape_type=struct.unpack("<i",data[32:36])[0]
    geoms=[]
    off=100
    while off+8<=len(data):
        rec_no, rec_len_words = struct.unpack(">ii",data[off:off+8])
        content_len=rec_len_words*2
        if content_len<4: break
        content=data[off+8:off+8+content_len]
        if len(content)<4: break
        st=struct.unpack("<i",content[0:4])[0]
        geoms.append(_parse_shape_content(content, st))
        off+=8+content_len
    return geoms, shape_type

