    pts=[]
    for i in range(count):
        x,y=struct.unpack_from("<dd",content,offset+i*16)
        pts.append([x,y])
    return pts

def _parse_shape_content(content, st):
    if st==0:
        return None
    if st==1:
        x,y=struct.unpack_from("<dd",content,4); return {"type":"Point","coordinates":[x,y]}
    if st==21:
        x,y,m=struct.unpack_from("<ddd",content,4); return {"type":"Point","coordinates":[x,y,m]}
    if st==11:
        x,y,z,m=struct.unpack_from("<dddd",content,4)
        # If m is NoData (very negative) treat as Z only
        if m < -1e38:
            return {"type":"Point","coordinates":[x,y,z]}
        return {"type":"Point","coordinates":[x,y,z,m]}
    if st==8 or st==28 or st==18:
        # bbox 32, npoints
        n=struct.unpack_from("<i",content,36)[0]
        pts=_read_points(content,40,n)
        if st==18:
            off=40+n*16
            # z range 16, z array, m range, m array
            if off+16+n*8<=len(content):
                zs=struct.unpack_from("<"+"d"*n,content,off+16)
                for p,z in zip(pts,zs): p.append(z)
