    if st in (3,5,13,15,23,25):
        # bbox, numParts, numPoints
        num_parts, num_points=struct.unpack_from("<ii",content,36)
        parts=list(struct.unpack_from("<"+"i"*num_parts,content,44)) if num_parts else []
        off=44+num_parts*4
        pts=_read_points(content,off,num_points)
        if st in (13,15):
            zoff=off+num_points*16
            # zmin,zmax then z array
            if zoff+16+num_points*8<=len(content):
                zs=struct.unpack_from("<"+"d"*num_points,content,zoff+16)
                for p,z in zip(pts,zs): p.append(z)
                # ignore m
        # build sequences
        seqs=[]
        for i,start in enumerate(parts):
            end=parts[i+1] if i+1<len(parts) else num_points
            seqs.append(pts[start:end])
        if st in (3,13,23):
            if len(seqs)==1:
                return {"type":"LineString","coordinates":seqs[0]}
            return {"type":"MultiLineString","coordinates":seqs}
        else:
            # Polygon: group rings by outer/hole classification
            return _rings_to_polygon_geom(seqs)
    return None

def _ring_signed_area(r):
    a=0.0
    n=len(r)
    for i in range(n):
        x1,y1=r[i][0],r[i][1]; x2,y2=r[(i+1)%n][0],r[(i+1)%n][1]
        a+=x1*y2-x2*y1
    return a/2.0

def _point_in_ring(pt, ring):
    # ray casting
    x,y=pt[0],pt[1]; inside=False
    n=len(ring)
    for i in range(n):
        x1,y1=ring[i][0],ring[i][1]; x2,y2=ring[(i+1)%n][0],ring[(i+1)%n][1]
        if ((y1>y)!=(y2>y)):
            xin=(x2-x1)*(y-y1)/(y2-y1)+x1
            if x<xin: inside=not inside
    return inside

def _rings_to_polygon_geom(seqs):
