    # Classify rings with signed area <0 as outer, >0 as holes. If first ring >0 and all rings follow opposite (?), OGR may flip logic if shape is written opposite. Use containment fallback if classification yields no outer.
    polys=[]
    holes=[]
    outers=[]
    for r in seqs:
        a=_ring_signed_area(r)
        if a<0:
            outers.append(r)
        elif a>0:
            holes.append(r)
        else:
            outers.append(r)
    if not outers:
        # Treat all as outer if no negative rings
        outers=seqs[:]; holes=[]
