        return struct.pack("<i",0)
    return struct.pack("<i",0)

def _flip_ring(ring):
    if len(ring)<2: return ring
    closed = ring[0]==ring[-1]
    core=ring[:-1] if closed else ring[:]
    if len(core)<=1: return ring
    flipped=[core[0]]+list(reversed(core[1:]))
    if closed:
        flipped.append(core[0])
    return flipped

def _bbox_pts(pts):
    if not pts: return (0.0,0.0,0.0,0.0)
    return (min(p[0] for p in pts),min(p[1] for p in pts),max(p[0] for p in pts),max(p[1] for p in pts))

def _parts_content(shape_type, seqs, geom):
