def _raw_numeric(raw,off,bits,fmt,endian):
    if fmt==3:
        if bits==16: return struct.unpack_from(endian+"e",raw,off)[0]
        if bits==32: return struct.unpack_from(endian+"f",raw,off)[0]
        if bits==64: return struct.unpack_from(endian+"d",raw,off)[0]
    if fmt==2 or fmt==5:
        if bits==8:return struct.unpack_from(endian+"b",raw,off)[0]
        if bits==16:return struct.unpack_from(endian+"h",raw,off)[0]
        if bits==32:return struct.unpack_from(endian+"i",raw,off)[0]
        if bits==64:return struct.unpack_from(endian+"q",raw,off)[0]
    if fmt==6:
        if bits==32:return struct.unpack_from(endian+"f",raw,off)[0]
        if bits==64:return struct.unpack_from(endian+"d",raw,off)[0]
    if bits==8:return raw[off]
    if bits==16:return struct.unpack_from(endian+"H",raw,off)[0]
    if bits==32:return struct.unpack_from(endian+"I",raw,off)[0]
    if bits==64:return struct.unpack_from(endian+"Q",raw,off)[0]
    return 0

def _assign_sample_values(result,x,y,samp_vals,bands_info):
    si=0
