                result[bi][y][x]=cast_value(samp_vals[si],dt)
            si+=1

def _assign_one_sample(result,x,y,v,sample_index,bands_info):
    si=0
    for bi,(dt,spb) in enumerate(bands_info):
        if spb==2:
            if sample_index==si:
                old=result[bi][y][x]; result[bi][y][x]=cast_value(complex(v, old.imag if isinstance(old,complex) else 0),dt)
            elif sample_index==si+1:
                old=result[bi][y][x]; result[bi][y][x]=cast_value(complex(old.real if isinstance(old,complex) else old, v),dt)
            si+=2
        else:
            if sample_index==si:
                result[bi][y][x]=cast_value(v,dt)
            si+=1

def _unpack_block_clipped(raw,x0,y0,bw,bh,imgw,imgh,result,bands_info,bits_list,formats,sample_byte_sizes,plane,endian):
    total_samples=sum(spb for _,spb in bands_info)
    # bits <8 packing
    if bits_list and bits_list[0]<8:
        bits=bits_list[0]
        samples_in_block=1 if plane is not None else total_samples
        idx=0
        total=bw*bh*samples_in_block
        vals=[]
        for i in range(total):
            bitpos=i*bits; bytepos=bitpos//8; shift=8-bits-(bitpos%8)
            vals.append((raw[bytepos]>>shift)&((1<<bits)-1) if bytepos<len(raw) else 0)
        p=0
        for yy in range(bh):
            for xx in range(bw):
                if x0+xx<imgw and y0+yy<imgh:
                    if plane is None:
                        _assign_sample_values(result,x0+xx,y0+yy,vals[p:p+total_samples],bands_info); p+=total_samples
                    else:
                        _assign_one_sample(result,x0+xx,y0+yy,vals[p],plane,bands_info); p+=1
                else:
                    p+=samples_in_block
        return
    if plane is not None:
        off=0; bsz=sample_byte_sizes[plane]
        for yy in range(bh):
            for xx in range(bw):
                if off+bsz>len(raw): return
                v=_raw_numeric(raw,off,bits_list[plane],formats[plane],endian); off+=bsz
                if x0+xx<imgw and y0+yy<imgh:
                    _assign_one_sample(result,x0+xx,y0+yy,v,plane,bands_info)
    else:
        off=0
        for yy in range(bh):
            for xx in range(bw):
                samp=[]
                for si in range(total_samples):
                    bsz=sample_byte_sizes[si]
                    if off+bsz>len(raw): return
                    samp.append(_raw_numeric(raw,off,bits_list[si],formats[si],endian)); off+=bsz
                if x0+xx<imgw and y0+yy<imgh:
                    _assign_sample_values(result,x0+xx,y0+yy,samp,bands_info)

def _parse_gdal_metadata(xml_text):
    ds_meta={}
    band_items=[]  # list dicts name,sample,domain,role,value
    if not xml_text: return ds_meta,band_items
    try:
        text=xml_text.strip("\x00")
        root=ET.fromstring(text)
    except Exception:
        return ds_meta,band_items
    for item in root.iter("Item"):
        name=item.get("name"); sample=item.get("sample"); domain=item.get("domain",""); role=item.get("role")
        val=item.text or ""
        # Some items contain Band elements? ignore nested
        if sample is None:
            if domain not in ds_meta: ds_meta[domain]={}
            ds_meta[domain][name]=val
        else:
            try:sample_i=int(sample)
            except:sample_i=0
            band_items.append(dict(name=name,sample=sample_i,domain=domain,role=role,value=val))
    return ds_meta,band_items

def _geotransform_from_tags(tags):
    gt=None; has=False; gcps=[]
