    ascii_text=ascii_params.decode("utf-8",errors="replace") if ascii_params else ""
    if "ESRI PE String =" in ascii_text:
        pe=ascii_text.split("ESRI PE String =",1)[1].strip().rstrip("\x00")
        if pe.endswith("|"): pe=pe[:-1]
        c=crsmod.crs_from_prj(pe)
        if c:
            return c,area_or_point
    if model==1 and proj_code and proj_code!=32767:
        return crsmod.crs_from_gtiff(proj_code),area_or_point
    if model==2 and geog_code and geog_code!=32767:
        return crsmod.crs_from_gtiff(geog_code),area_or_point
    if proj_code and proj_code!=32767:
        return crsmod.crs_from_gtiff(proj_code),area_or_point
    if geog_code and geog_code!=32767:
        # Could be base géographique for user-defined projected; if model ==1 and projection params present, constructing full CRS is complex. Use citation name maybe.
        if model==1:
            # Try use citations to identify: PCSCitation might be a WKT or name
            # For now use geog code as CRS (will be wrong for projected user-defined, e.g. Google Maps Global Mercator)
            # Check ascii citations for known projected names
            if "Google Maps Global Mercator" in ascii_text:
