        return crsmod.crs_from_gtiff(geog_code),area_or_point
    # user defined - use ascii citation first segment as name and construct a minimal CRS from libgeotiff keys via CRS wkt fallback unsupported
    if ascii_text:
        first=ascii_text.split("|")[0]
