    return None,area_or_point

def _color_interps(photo,samples,extras,bands_count):
    if photo==3:
        lst=["Palette"]+["Undefined"]*(bands_count-1); return lst
    if photo==2:
        base=["Red","Green","Blue"]
        lst=[]
        for i in range(bands_count):
