        if item["role"]=="scale":
            try: band.scale=float(item["value"])
            except: pass
        elif item["role"]=="offset":
            try: band.offset=float(item["value"])
            except: pass
        elif item["role"]=="unittype":
            band.unit=item["value"]
        elif item["role"]=="description":
            band.description=item["value"]
        elif item["role"]=="colorinterp":
            band.color_interp=item["value"]
        elif item["name"]=="COLORINTERP":
            band.color_interp=item["value"]
