        metadata[""]["AREA_OR_POINT"]=area_or_point
    # IMAGE_STRUCTURE metadata derived - original GTiff driver reports its metadata from file metadata domain IMAGE_STRUCTURE if stored? It also adds INTERLEAVE/COMPRESSION/LAYOUT derived from file structure.
