    for tags_ov in overview_ifds:
        ow=tags_ov[256].first(); oh=tags_ov[257].first()
        osamples=tags_ov[277].first(samples) if 277 in tags_ov else samples
        obits=tags_ov[258].list() if 258 in tags_ov else bits_list
        ofmts=tags_ov[339].list() if 339 in tags_ov else formats
