            band.overviews.append(ob)
    # Files include aux/ovr handled in generic open (PAM)
    return ds

def _parse_nodata_string(s,dtype):
    ss=s.strip()
    low=ss.lower()
    if low=="nan": return float("nan")
    if low in ("inf","+inf","infinity"): return float("inf")
    if low in ("-inf","-infinity"): return float("-inf")
    if low=="none": return None
    try:
        # complex format maybe "re,im" or "re+imj"
        if dtype and canon_dtype(dtype) in ("CInt16","CInt32","CFloat32","CFloat64"):
            if "," in ss:
                a,b=ss.split(",",1); return complex(float(a),float(b))
            return complex(float(ss),0)
        return float(ss)
    except Exception:
        return None
