    # Files list includes source files (for raster info Files): collect SourceFilename values resolved - GDAL file list includes source dataset filenames as they appear (relative_to_vrt resolved to VRT dir path as in info earlier /tmp/probe/epsg.tif)
    files=[str(path)]
    base_dir=os.path.dirname(str(path))
    for sf in root.iter("SourceFilename"):
        fn=(sf.text or "").strip()
        if not fn:continue
        rel=sf.get("relativeToVRT")
        if rel and rel not in ("0","false"):
            resolved=os.path.normpath(os.path.join(base_dir,fn)) if base_dir and not os.path.isabs(fn) and not fn.startswith("/") else fn
        else:
            resolved=fn
        if resolved not in files:
            files.append(resolved)
    ds.files=files
    # If warped dataset and no bands but warp options child: mark for lazy warp in rasterio open wrapper
    if subclass=="VRTWarpedDataset":
        ds._warped_options_xml=ET.tostring(root,encoding="unicode")
    return ds

def _read_vrt_band(bel,width,height,vrt_path,open_stack):
    dtype=bel.get("dataType") or "Byte"
    block_x=bel.get("blockXSize"); block_y=bel.get("blockYSize")
    band=Band(dtype,width,height)
    # defaults for VRT: block size is (width,1) if no sources? With SimpleSource, block adopts source block (SourceProperties BlockX/Y or opened source band block)
    band.block_size=(width,1)
    # Parse common children first (metadata etc known for sources processing)
    sources=[]
    for child in bel:
        if child.tag in ("SimpleSource","ComplexSource","AveragedSource","KernelFilteredSource"):
            sources.append(child)
    # First process sources to fill data
    # Initialize data with nodata? VRTRasterBand without sources is all zero, but if there is a NoDataValue, initial value is nodata? GDAL VRT band fill is nodata if set (?) Check: a VRT band with no sources and NoDataValue -9999 read pixels as -9999 or 0? Our band data init 0; after nodata parsed later, if no sources, pixels are 0 in GDAL I think (band has no source returns 0 silently). Pixel area outside sources in a sourced band is filled with nodata (or 0 if none) according to VRTSourcedRasterBand initial fill: it uses nodata if GetNoDataValue set ("initial fill").
    # We'll parse nodata first
    nodata=None
    nd_el=bel.find("NoDataValue")
    if nd_el is not None and nd_el.text is not None:
        nodata=_parse_nodata_string(nd_el.text.strip(),dtype)
    hide_nodata=(bel.findtext("HideNoDataValue") or "").strip()=="1"
    band.nodata=None if hide_nodata else nodata
    if sources:
        # initialize with nodata (if any) else 0
        fill=cast_value(nodata,band.dtype) if nodata is not None else cast_value(0,band.dtype)
        band.data=[[fill for _ in range(width)] for __ in range(height)]
        for src in sources:
            _apply_source(band,src,vrt_path,open_stack)
    # LUT
    lut_el=bel.find("LUT")
    if lut_el is not None and lut_el.text:
        try:
            lut=[float(x.strip()) for x in lut_el.text.strip().split(",") if x.strip()!='']
            new_data=[]
            for row in band.data:
                new=[]
                for v in row:
                    try:
                        idx=int(v)
                        new.append(cast_value(lut[idx],band.dtype) if 0<=idx<len(lut) else cast_value(v,band.dtype))
                    except:
                        new.append(v)
                new_data.append(new)
            band.data=new_data
        except Exception:
            pass
    # Derived band pixel function
    if bel.tag=="VRTDerivedRasterBand":
        _apply_pixel_function(band,bel,vrt_path,width,height,open_stack,sources)
    if bel.tag=="VRTRawRasterBand":
        _read_raw_band(band,bel,vrt_path)
    # Other properties
    desc=bel.findtext("Description")
    if desc is not None: band.description=desc or ""
    ci=bel.findtext("ColorInterp")
    if ci is not None: band.color_interp=ci.strip() or "Undefined"
    unit=bel.findtext("UnitType")
    if unit is not None: band.unit=unit or ""
    off=bel.findtext("Offset"); sca=bel.findtext("Scale")
    if off is not None:
        try:band.offset=float(off)
        except:pass
    if sca is not None:
        try:band.scale=float(sca)
        except:pass
    cat_el=bel.find("CategoryNames")
    if cat_el is not None:
        # child li elements text namespaced? just all child texts
        band.category_names=[(c.text or "") for c in list(cat_el)]
    ct_el=bel.find("ColorTable")
    if ct_el is not None:
        ct=[]
        for entry in ct_el.findall("Entry"):
            r=_i(entry.get("c1"));g=_i(entry.get("c2"));b=_i(entry.get("c3"));a=_i(entry.get("c4"),255)
            ct.append((r,g,b,a))
        if ct:band.color_table=ct
    for md in bel.findall("Metadata"):
        domain=md.get("domain","")
        d=band.metadata.setdefault(domain,{})
        for mdi in md.findall("MDI"):
            d[mdi.get("key")]=mdi.text or ""
    # Histogram
    hist=bel.find("Histograms/HistItem")
    if hist is not None:
        try:
            band.histogram=dict(min=_f(hist.findtext("HistMin")),max=_f(hist.findtext("HistMax")),buckets=_i(hist.findtext("BucketCount")),counts=[int(float(x)) for x in (hist.findtext("HistCounts") or "").replace("|",",").split(",") if x.strip()!=''],include_outside=_i(hist.findtext("IncludeOutOfRange")),approx=_i(hist.findtext("Approx")))
        except Exception:pass
    # Min/Max elements (for VRT info min/max printed)
    if bel.findtext("Min") is not None:
        try:band.min_value=float(bel.findtext("Min"))
        except:pass
    if bel.findtext("Max") is not None:
        try:band.max_value=float(bel.findtext("Max"))
        except:pass
    # block size attr on band element
    if block_x and block_y:
        band.block_size=(_i(block_x),_i(block_y))
    elif sources:
        # Band block already set in _apply_source from first source if available (attribute _block_hint)
        if hasattr(band,"_block_hint") and band._block_hint:
            band.block_size=band._block_hint
    else:
        # VRT band with no sources: block is complete image size (as observed)
        band.block_size=(width,height) if width and height else (width,1)
    # Overview elements inside band? <Overview> with a source filename / band? VRT overviews are represented as VRTRasterBand's Overview elements containing <SourceFilename>... complex - ignore.
    return band

def _resolve_source_path(src_filename, rel, vrt_path):
    fn=src_filename.strip()
    if rel and rel not in ("0","false") and not os.path.isabs(fn) and not fn.startswith("/vsi"):
        base=os.path.dirname(str(vrt_path))
        if base:
            return os.path.join(base,fn)
    return fn

def _open_source_dataset(path,open_stack):
    # circular protection
    if open_stack and path in open_stack:
        return None
    import rasterio as rio
    return rio.open_raster_dataset(path,_open_stack=(open_stack or [])+[])

def _apply_source(band,src,vrt_path,open_stack):
    fn_el=src.find("SourceFilename")
    if fn_el is None:return
    fn=_resolve_source_path(fn_el.text or "", fn_el.get("relativeToVRT"),vrt_path)
    band_no=1
    sb=src.findtext("SourceBand")
    source_dataset_name=None
    if sb:
        if sb.strip().startswith("DATASET:"):
            source_dataset_name=sb.strip().split(":",1)[1]
            band_no=1
        else:
            try:band_no=int(sb.strip())
            except:band_no=1
    sds=None
    try:
        import rasterio as rio
        sds=rio.open_raster_dataset(fn)
    except Exception:
        # If source cannot open, GDAL VRT would error on access; for info, source properties may suffice. Return without filling but record block from SourceProperties
        sp=src.find("SourceProperties")
        if sp is not None:
            band._block_hint=(_i(sp.get("BlockXSize"),band.width),_i(sp.get("BlockYSize"),1))
        return
    if sds is None or not sds.bands:return
    sband=sds.bands[band_no-1] if 1<=band_no<=len(sds.bands) else sds.bands[0]
    if not hasattr(band,"_block_hint") or band._block_hint is None:
        band._block_hint=sband.block_size
    sp=src.find("SourceProperties")
    source_w=_i(sp.get("RasterXSize"),sds.width) if sp is not None else sds.width
    source_h=_i(sp.get("RasterYSize"),sds.height) if sp is not None else sds.height
    src_rect=src.find("SrcRect"); dst_rect=src.find("DstRect")
    sx=_f(src_rect.get("xOff"),0) if src_rect is not None else 0; sy=_f(src_rect.get("yOff"),0) if src_rect is not None else 0
    sw=_f(src_rect.get("xSize"),source_w) if src_rect is not None else source_w; sh=_f(src_rect.get("ySize"),source_h) if src_rect is not None else source_h
    dx=_f(dst_rect.get("xOff"),0) if dst_rect is not None else 0; dy=_f(dst_rect.get("yOff"),0) if dst_rect is not None else 0
    dw=_f(dst_rect.get("xSize"),band.width) if dst_rect is not None else band.width; dh=_f(dst_rect.get("ySize"),band.height) if dst_rect is not None else band.height
    # ComplexSource extras
    scale_off=src.findtext("ScaleOffset"); scale_ratio=src.findtext("ScaleRatio")
    scale_offset=_f(scale_off,0.0) if scale_off is not None else 0.0
    scale_ratio_v=_f(scale_ratio,1.0) if scale_ratio is not None else 1.0
    src_nodata=None; dst_nodata=None
    nd=src.findtext("NODATA")
    if nd is not None:
        src_nodata=_parse_nodata_string(nd.strip(),sband.dtype)
    lut=None
    lut_el=src.find("LUT")
    if lut_el is not None and lut_el.text:
        try:lut=[float(x) for x in lut_el.text.strip().split(",") if x.strip()!='']
        except:lut=None
    color_table = src.find("ColorTable")
    use_mask = src.findtext("UseMaskBand")
    # For each dest pixel, nearest neighbor sampling mapping from dst rect to src rect.
    # VRT SimpleSource semantics: RasterIO from VRT band requests a window and source RasterIO scales.
    for y in range(int(math.floor(dy)), int(math.ceil(dy+dh))):
        if y<0 or y>=band.height:continue
        v=(y-dy+0.5)/dh if dh else 0
        src_y=int(math.floor(sy + v*sh))
        if src_y<0: src_y=0
        if src_y>=sds.height: src_y=sds.height-1
        for x in range(int(math.floor(dx)), int(math.ceil(dx+dw))):
            if x<0 or x>=band.width:continue
            u=(x-dx+0.5)/dw if dw else 0
            src_x=int(math.floor(sx+u*sw))
            if src_x<0:src_x=0
            if src_x>=sds.width:src_x=sds.width-1
            val=sband.data[src_y][src_x]
            if src_nodata is not None:
                if _is_nodata(val,src_nodata):
                    # ComplexSource: nodata values are not written (transparent) (?) If source is only source, result retains initial nodata fill.
                    continue
            if lut is not None:
                try:
                    iv=int(val)
                    if 0<=iv<len(lut): val=lut[iv]
                except:pass
            # Apply scale: dst = src * ScaleRatio + ScaleOffset (dst over source?) GDAL docs: value transformed by ScaleRatio and ScaleOffset.
            try:
                if isinstance(val,complex):
                    val=complex(val.real*scale_ratio_v+scale_offset, val.imag*scale_ratio_v)
                else:
                    val=val*scale_ratio_v+scale_offset
            except:pass
            band.data[y][x]=cast_value(val,band.dtype)

def _is_nodata(v,nd):
    if v is None:return False
    if isinstance(nd,float) and math.isnan(nd):
        return isinstance(v,float) and math.isnan(v)
    return v==nd

def _apply_pixel_function(band,bel,vrt_path,width,height,open_stack,sources):
    pf_type=(bel.findtext("PixelFunctionType") or "").strip()
    # Sources have already been applied sequentially into band, which is wrong for derived functions taking multiple sources. Recompute for common types if multiple sources.
    # We can reconstruct each source band data by reopening source datasets (via _apply_source on temp bands)
    src_bands=[]
    for src in sources:
        tb=Band(band.dtype,width,height)
        # initialize with 0
        _apply_source(tb,src,vrt_path,open_stack)
        src_bands.append(tb)
    args={}
    for arg in bel.findall("PixelFunctionArgument"):
        args[arg.get("name")]=arg.get("value")
    # buffer radius for dilation etc ignore
    def val_at(i,x,y):
        return src_bands[i].data[y][x] if i<len(src_bands) else 0
    out=[[cast_value(0,band.dtype) for _ in range(width)] for __ in range(height)]
    import math as _m
    for y in range(height):
        for x in range(width):
            vals=[val_at(i,x,y) for i in range(len(src_bands))]
            if pf_type=="real": r=vals[0].real if isinstance(vals[0],complex) else vals[0]
            elif pf_type=="imag": r=vals[0].imag if isinstance(vals[0],complex) else 0
            elif pf_type in ("complex",""): r=complex(vals[0],vals[1]) if len(vals)>1 else vals[0]
            elif pf_type=="mag": r=abs(vals[0])
            elif pf_type=="phase": r=_m.atan2(vals[0].imag,vals[0].real) if isinstance(vals[0],complex) else 0
            elif pf_type=="conj": r=vals[0].conjugate() if isinstance(vals[0],complex) else vals[0]
            elif pf_type=="sum": r=sum(vals)
            elif pf_type=="diff": r=vals[0]-vals[1] if len(vals)>1 else vals[0]
            elif pf_type=="mul":
                r=1
                for v in vals:r*=v
            elif pf_type=="div": r=vals[0]/vals[1] if len(vals)>1 and vals[1]!=0 else 0
            elif pf_type=="min": r=min(vals)
            elif pf_type=="max": r=max(vals)
            elif pf_type=="expression":
                # Pixel function expression may be in args or child Expression
                expr=args.get("expression") or bel.findtext("Expression") or ""
                # Names are source dataset names if SourceBand had DATASET:name - our source bands order; Map variables a,b? VRT expression typically uses band names - simplified handler in operations calc evaluator later.
                r=vals[0] if vals else 0
            else:
                # Unknown pixel function: keep previous sequential application result (band.data)
                return
            out[y][x]=cast_value(r,band.dtype)
    band.data=out

def _read_raw_band(band,bel,vrt_path):
    fn_el=bel.find("SourceFilename")
    if fn_el is None:return
    fn=_resolve_source_path(fn_el.text or "", fn_el.get("relativeToVRT"),vrt_path)
    try: raw=vfs.read_binary(fn)
    except Exception:return
    image_offset=_i(bel.findtext("ImageOffset"),0)
    pixel_offset=_i(bel.findtext("PixelOffset"),DTYPES[band.dtype]["bytes"])
    line_offset=_i(bel.findtext("LineOffset"),pixel_offset*band.width)
    byte_order=(bel.findtext("ByteOrder") or "LSB").strip()
    endian=">" if byte_order.upper().startswith("MSB") else "<"
    import struct as st
    fmt=DTYPES[band.dtype]["fmt"]; size=st.calcsize(endian+fmt)
    for y in range(band.height):
        for x in range(band.width):
            off=image_offset+y*line_offset+x*pixel_offset
            if off+size<=len(raw):
                if DTYPES[band.dtype]["kind"]=="complex":
                    v=complex(st.unpack_from(endian+fmt,raw,off)[0], st.unpack_from(endian+fmt,raw,off+size)[0] if off+2*size<=len(raw) else 0)
                else:
                    v=st.unpack_from(endian+fmt,raw,off)[0]
                band.data[y][x]=cast_value(v,band.dtype)

# ---------- Writing ----------
def _fmt_gt(v):
    # Observed value width: format with '%25.16e'? Counting from sample: "  0.0000000000000000e+00" len 24, negative " -1.000..." len 24?
    s=format(float(v),".16e")
    # GDAL VRT writes GeoTransform using CPLString().Printf("%24.16e", val) (?) Let's width 24
    return f"{s:>24s}"

def _esc(s):
    return saxutils.escape(str(s),{'\"':"&quot;"})

def write_vrt(ds,path,creation_options=None,relative_sources=True):
    # If ds has a prepared _vrt_xml string (set by operations), use it.
    xml=getattr(ds,"_vrt_xml",None)
    if xml:
        vfs.write_binary(path,xml.encode("utf-8"))
        return
    lines=[]
    lines.append(f'<VRTDataset rasterXSize="{ds.width}" rasterYSize="{ds.height}">')
    if ds.crs:
        wkt1=None
        if ds.crs.epsg:
            wkt1=crsmod.wkt1_gdal_from_epsg(ds.crs.epsg)
        if not wkt1 and ds.crs.wkt:
            wkt1=ds.crs.wkt
        if wkt1:
            axis=",".join(str(x) for x in ds.crs.axis_mapping_list())
            lines.append(f'  <SRS dataAxisToSRSAxisMapping="{axis}">{_esc(wkt1)}</SRS>')
    if ds.has_geotransform:
        gt_str=", ".join(_fmt_gt(v) for v in ds.geotransform)
        # GDAL format has values separated by comma+space and each already width; sample has two spaces before first because width24 string for 0.0... has leading spaces: ' ' + 23 chars? Our _fmt width24 gives that. But join with ", " adds space => second values have leading spaces from width too - original string after comma has two spaces before positive value. So join with "," only and each formatted string starts with space(s): Check sample: "<GeoTransform>  0.000...,  1.000..." after > is two spaces, after comma two spaces. Our width24 string for "0.0000000000000000e+00" len22 => 2 leading spaces. Join with "," (no extra space) would give ",  1..." (2 spaces from padding), correct.
        gt_str=",".join(_fmt_gt(v) for v in ds.geotransform)
        lines.append(f'  <GeoTransform>{gt_str}</GeoTransform>')
    # GCP list
    if ds.gcps:
        lines.append('  <GCPList Projection="'+_esc((ds.gcp_crs.wkt if ds.gcp_crs and ds.gcp_crs.wkt else ""))+'">')
        for g in ds.gcps:
            lines.append(f'    <GCP Id="{_esc(g.get("id",""))}" Info="{_esc(g.get("info",""))}" Pixel="{g.get("pixel")}" Line="{g.get("line")}" X="{g.get("x")}" Y="{g.get("y")}" Z="{g.get("z",0)}" />')
        lines.append('  </GCPList>')
    for domain,md in ds.metadata.items():
        if not md:continue
        if domain=="":
            lines.append('  <Metadata>')
        else:
            lines.append(f'  <Metadata domain="{_esc(domain)}">')
        for k,v in md.items():
            lines.append(f'    <MDI key="{_esc(k)}">{_esc(v)}</MDI>')
        lines.append('  </Metadata>')
    source_path=getattr(ds,"_vrt_source_path",None)
    if not source_path:
        # If ds description is an existing file and ds appears to be read from it (convert case caller sets this), operations should set it. Default to description if it isn't same as output and exists and ds.driver in GTiff/VRT
        if ds.description and str(ds.description)!=str(path) and vfs.exists(str(ds.description)):
            source_path=str(ds.description)
    source_band_map=getattr(ds,"_vrt_source_bands",None)  # list per band: (filename, bandNo, srcRect, dstRect, dict extra)
    for bi,band in enumerate(ds.bands):
        # Determine if this band is a derived or sourced in a custom representation stored in band attr
        custom=getattr(band,"_vrt_custom_xml",None)
        if custom:
            lines.append(custom)
            continue
        band_attrs=f'  <VRTRasterBand dataType="{band.dtype}" band="{bi+1}"'
        # block size attributes in VRT only if different? GDAL VRT serializer writes blockXSize/Y if set on band explicitly (?) Our written VRT for create has no attrs.
        band_attrs+='>'
        lines.append(band_attrs)
        if band.description:
            lines.append(f'    <Description>{_esc(band.description)}</Description>')
        if band.nodata is not None:
            lines.append(f'    <NoDataValue>{_esc(_fmt_nodata(band.nodata))}</NoDataValue>')
        if band.color_interp and band.color_interp!="Undefined":
            lines.append(f'    <ColorInterp>{band.color_interp}</ColorInterp>')
        if band.unit:
            lines.append(f'    <UnitType>{_esc(band.unit)}</UnitType>')
        if band.offset!=0.0:
            lines.append(f'    <Offset>{band.offset}</Offset>')
        if band.scale!=1.0:
            lines.append(f'    <Scale>{band.scale}</Scale>')
        if band.category_names:
            lines.append('    <CategoryNames>')
            for cn in band.category_names: lines.append(f'      <li>{_esc(cn)}</li>')
            lines.append('    </CategoryNames>')
        if band.color_table:
            lines.append('    <ColorTable>')
            for rgba in band.color_table:
                lines.append(f'      <Entry c1="{rgba[0]}" c2="{rgba[1]}" c3="{rgba[2]}" c4="{rgba[3]}" />')
            lines.append('    </ColorTable>')
        for domain,md in band.metadata.items():
            if not md:continue
            lines.append(f'    <Metadata>' if domain=="" else f'    <Metadata domain="{_esc(domain)}">')
            for k,v in md.items(): lines.append(f'      <MDI key="{_esc(k)}">{_esc(v)}</MDI>')
            lines.append('    </Metadata>')
        # Source mapping
        mapping=None
        if source_band_map and bi<len(source_band_map):
            mapping=source_band_map[bi]
        elif source_path:
            mapping=dict(filename=source_path,band=bi+1,src_rect=(0,0,ds.width,ds.height),dst_rect=(0,0,ds.width,ds.height),source_size=(ds.width,ds.height),source_dtype=band.dtype,source_block=band.block_size)
        if mapping:
            lines.extend(_source_xml(mapping,path,relative_sources))
        lines.append('  </VRTRasterBand>')
    lines.append('</VRTDataset>')
    content="\n".join(lines)+"\n"
    vfs.write_binary(path,content.encode("utf-8"))

def _fmt_nodata(v):
    if isinstance(v,complex): return f"{v.real},{v.imag}"
    if isinstance(v,float) and v==int(v): return str(int(v))
    return format(float(v),'.15g') if isinstance(v,float) else str(v)

def _source_xml(mapping, vrt_path, relative_sources=True):
    lines=[]
    # mapping may be a list of sources
    if isinstance(mapping,list):
        for m in mapping: lines.extend(_source_xml(m,vrt_path,relative_sources))
        return lines
    filename=mapping.get("filename") or ""
    # Relative path if possible
    rel="0"; fn_text=str(filename)
    if relative_sources and vrt_path and not str(filename).startswith("/vsi"):
        try:
            vrt_dir=os.path.dirname(os.path.abspath(str(vrt_path)))
            fn_abs=os.path.abspath(str(filename)) if not os.path.isabs(str(filename)) else str(filename)
            # only make relative if in same folder or sub (?) Original relativeToVRT simply uses relative path from source file to VRT if... It outputs basename if same dir, else maybe relative path like ../x.tif
            relpath=os.path.relpath(fn_abs,vrt_dir)
            # GDAL behavior: uses relative filename only if it's "relative" friendly? It typically stores the filename as provided relative to VRT if input was with that path? For /tmp/probe/out2.tif -> wrt out2.vrt in same dir, it stored "out2.tif".
            fn_text=relpath; rel="1"
        except Exception:
            rel="0"
    src_type=mapping.get("source_type","SimpleSource")
    lines.append(f'    <{src_type}>')
    lines.append(f'      <SourceFilename relativeToVRT="{rel}">{_esc(fn_text)}</SourceFilename>')
    lines.append(f'      <SourceBand>{mapping.get("band",1)}</SourceBand>')
    if mapping.get("source_size") or mapping.get("source_block"):
        sw,sh=mapping.get("source_size",(0,0))
        sb=mapping.get("source_block",(sw,1))
        sdtype=mapping.get("source_dtype","Byte")
        lines.append(f'      <SourceProperties RasterXSize="{sw}" RasterYSize="{sh}" DataType="{sdtype}" BlockXSize="{sb[0]}" BlockYSize="{sb[1]}" />')
    if mapping.get("src_rect"):
        sx,sy,sw,sh=mapping["src_rect"]; lines.append(f'      <SrcRect xOff="{_fmt_rect(sx)}" yOff="{_fmt_rect(sy)}" xSize="{_fmt_rect(sw)}" ySize="{_fmt_rect(sh)}" />')
    if mapping.get("dst_rect"):
