import os, re
import vfs
from rastermodel import RasterDataset
from tiffio import RasterOpenError, open_geotiff
from tiffwrite import write_gtiff
from vrtio import open_vrt, write_vrt
import pam as pammod

def identify_raster_driver(path):
    p=str(path); lower=p.lower()
    if vfs.is_dir(path):return None
    if lower.endswith(".vrt"):
        return "VRT"
    if lower.endswith((".tif",".tiff")):
        return "GTiff"
    try:
        data=vfs.read_binary(path)[:4096]
    except Exception:
        return None
    if data[:2] in (b'II',b'MM') and len(data)>=4 and data[2:4] in (b'*\x00',b'\x00*',b'+\x00',b'\x00+'):
        return "GTiff"
    txt=data[:1000].decode("utf-8",errors="ignore").lstrip()
    if txt.startswith("<VRTDataset"):
        return "VRT"
    return None

def open_raster_dataset(path,input_formats=None,open_options=None,update=False,_open_stack=None):
    if isinstance(path,RasterDataset):
        return path
    p=str(path)
    if not vfs.exists(p) and not vfs.is_stdin_path(p):
        raise RasterOpenError([f"ERROR 4: {p}: No such file or directory"])
    driver=identify_raster_driver(p)
    if input_formats:
        fmts=[str(f) for f in input_formats]
        if driver and driver not in fmts:
            raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
        if driver is None and fmts:
            # Try first format if it's GTiff/VRT
            if fmts[0] in ("GTiff","VRT"):driver=fmts[0]
    if driver is None:
        raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
    if driver=="GTiff":
        ds=open_geotiff(p)
    elif driver=="VRT":
        ds=open_vrt(p,open_stack=_open_stack)
        if getattr(ds,"_vrt_subclass",None)=="VRTWarpedDataset" and not getattr(ds,"_warped_applied",False):
            # Apply warp lazily via helper if available
            try:
                import warpedvrt
                ds2=warpedvrt.materialize_warped_vrt(ds,p)
                if ds2 is not None:
                    ds=ds2
            except Exception:
                pass
    else:
        raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
    ds.description=p
    # External overviews & PAM & file list
    files=[p]
    # For VRT, files already include source files from open_vrt; start with those
    if ds.files and ds.driver_short=="VRT":
        files=ds.files[:]
    aux=pammod.pam_filename(p)
    if aux and vfs.exists(aux):
        pammod.load_pam(ds,p)
        # GTiff file list includes .aux.xml after main file, before sources? For VRT, file list order in gdalinfo: main, source files, ... aux maybe after.
        if aux not in files:
            # insert after main for GTiff, append for VRT
            if ds.driver_short=="GTiff": files.insert(1,aux)
            else: files.append(aux)
    # external overviews .ovr
    ovr=p+".ovr"
    if vfs.exists(ovr) and ds.driver_short in ("GTiff","VRT"):
        # Only load if bands have no internal overviews
        if ds.bands and not ds.bands[0].overviews:
            try:
                ods=open_geotiff(ovr)
                # ods itself may be structured as main overview IFDS? In a .ovr TIFF, first IFD is an overview level (not main), subsequent are further levels. open_geotiff parses first as main bands and rest as its bands overviews. Flatten:
                levels=[]
                levels.append(ods.bands)
                if ods.bands and ods.bands[0].overviews:
                    for lvl in range(len(ods.bands[0].overviews)):
                        levels.append([b.overviews[lvl] for b in ods.bands])
                for lvl_bands in levels:
                    for bi,ob in enumerate(lvl_bands):
                        if bi<len(ds.bands): ds.bands[bi].overviews.append(ob)
            except Exception:
                pass
        if ovr not in files:
            # file list order original maybe after main/aux
            files.append(ovr)
    ds.files=files
    return ds

def guess_raster_driver(output, output_format=None):
    if output_format:
        fmt=str(output_format)
        for dn in ["GTiff","COG","VRT","MEM"]:
            if fmt.lower()==dn.lower():return dn
        return fmt
    p=str(output).lower()
    if p.endswith(".vrt"):return "VRT"
    if p.endswith((".tif",".tiff")):return "GTiff"
    return None

def write_raster_dataset(ds,path,output_format=None,creation_options=None,preserve_colorinterp=True,use_source_block=True):
    drv=guess_raster_driver(path,output_format)
    if drv is None:return None
    if drv=="GTiff":
        write_gtiff(ds,path,creation_options,preserve_colorinterp=preserve_colorinterp,use_source_block=use_source_block,is_cog=False)
    elif drv=="COG":
        write_gtiff(ds,path,creation_options,preserve_colorinterp=preserve_colorinterp,use_source_block=use_source_block,is_cog=True)
    elif drv=="VRT":
        write_vrt(ds,path,creation_options)
    elif drv=="MEM":
        pass
    else:
        return None
    return drv
