import os, re
import vfs
from rastermodel import RasterDataset
from tiffio import RasterOpenError, open_geotiff
from tiffwrite import write_gtiff
from vrtio import open_vrt, write_vrt
import pam as pammod

def identify_raster_driver(path):
    p=str(path); lower=p.lower()
    if vfs.is_dir(path):return None
    if lower.endswith(".vrt"):
        return "VRT"
    if lower.endswith((".tif",".tiff")):
        return "GTiff"
    try:
        data=vfs.read_binary(path)[:4096]
    except Exception:
        return None
    if data[:2] in (b'II',b'MM') and len(data)>=4 and data[2:4] in (b'*\x00',b'\x00*',b'+\x00',b'\x00+'):
        return "GTiff"
    txt=data[:1000].decode("utf-8",errors="ignore").lstrip()
    if txt.startswith("<VRTDataset"):
        return "VRT"
    return None

def open_raster_dataset(path,input_formats=None,open_options=None,update=False,_open_stack=None):
    if isinstance(path,RasterDataset):
        return path
    p=str(path)
    if not vfs.exists(p) and not vfs.is_stdin_path(p):
        raise RasterOpenError([f"ERROR 4: {p}: No such file or directory"])
    driver=identify_raster_driver(p)
    if input_formats:
        fmts=[str(f) for f in input_formats]
        if driver and driver not in fmts:
            raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
        if driver is None and fmts:
            # Try first format if it's GTiff/VRT
            if fmts[0] in ("GTiff","VRT"):driver=fmts[0]
    if driver is None:
        raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
    if driver=="GTiff":
        ds=open_geotiff(p)
    elif driver=="VRT":
        ds=open_vrt(p,open_stack=_open_stack)
        if getattr(ds,"_vrt_subclass",None)=="VRTWarpedDataset" and not getattr(ds,"_warped_applied",False):
            # Apply warp lazily via helper if available
            try:
                import warpedvrt
                ds2=warpedvrt.materialize_warped_vrt(ds,p)
                if ds2 is not None:
                    ds=ds2
            except Exception:
                pass
    else:
        raise RasterOpenError([f"ERROR 4: `{p}' not recognized as being in a supported file format."])
    ds.description=p
    # External overviews & PAM & file list
    files=[p]
    # For VRT, files already include source files from open_vrt; start with those
    if ds.files and ds.driver_short=="VRT":
        files=ds.files[:]
    aux=pammod.pam_filename(p)
    if aux and vfs.exists(aux):
        pammod.load_pam(ds,p)
        # GTiff file list includes .aux.xml after main file, before sources? For VRT, file list order in gdalinfo: main, source files, ... aux maybe after.
        if aux not in files:
            # insert after main for GTiff, append for VRT
            if ds.driver_short=="GTiff": files.insert(1,aux)
            else: files.append(aux)
    # external overviews .ovr
    ovr=p+".ovr"
