                if ods.bands and ods.bands[0].overviews:
                    for lvl in range(len(ods.bands[0].overviews)):
                        levels.append([b.overviews[lvl] for b in ods.bands])
                for lvl_bands in levels:
                    for bi,ob in enumerate(lvl_bands):
                        if bi<len(ds.bands): ds.bands[bi].overviews.append(ob)
            except Exception:
                pass
