        cc[key]=[FmtNumber(rx,format_json_float(rx) if not isinstance(rx,int) else str(rx)+".0" if isinstance(rx,float) else str(rx)), FmtNumber(ry,format_json_float(ry))]
        # Format numbers: GDAL json floats use .17g + .0, format_json_float does that but for rounded values like 149.1286118 .17g gives maybe122? It should give shortest (?) Python .17g for the rounded float (which is binary closest to 149.1286118) gives 149.12861179999999? Check: Python format(149.1286118,'.17g') maybe 149.12861180000001. But original JSON gave 149.1286118. This is because corner JSON numbers are created from a formatted string (round string) and json-c preserves string for that number (double_s). So use string repr(rx) after round, ensuring .0
        cc[key]=[FmtNumber(rx,_json_num_from_rounded(rx)),FmtNumber(ry,_json_num_from_rounded(ry))]
    obj["cornerCoordinates"]=cc
