        obj["gcps"]={"coordinateSystem":({"wkt":ds.gcp_crs.get_wkt(),"dataAxisToSRSAxisMapping":ds.gcp_crs.axis_mapping_list()} if ds.gcp_crs and ds.gcp_crs.get_wkt() else {}),"gcps":gcps} if ds.gcp_crs else {"gcps":gcps}
    # Bands
    band_objs=[]
