# ------- Vector info -------
def vector_info_object(ds,opts,layer_filter=None,features_flag=False,summary_flag=False):
    obj={}
    obj["description"]=ds.description
    obj["driverShortName"]=ds.driver_short
    obj["driverLongName"]=ds.driver_long
    layers=[]
    for layer in ds.layers:
        if layer_filter and layer.name not in layer_filter: continue
        if summary_flag:
            layers.append({"name":layer.name,"geometryType":[layer.geom_type] if not isinstance(layer.geom_type,list) else layer.geom_type})
            continue
        lo={}
        lo["name"]=layer.name
        lo["metadata"]=dict(layer.metadata) if layer.metadata else {}
        # geometry fields: one
        gf={}
        gf["name"]=layer.geom_field_name
        gf["type"]=layer.geom_type
        gf["nullable"]=True
        ext=layer.extent()
        if ext:
            gf["extent"]=[float(e) for e in ext]
        if layer.crs:
            cs={}
            wkt=layer.crs.get_wkt()
            if wkt:cs["wkt"]=wkt
            pj=layer.crs.get_projjson()
            if pj is not None:cs["projjson"]=pj
            cs["dataAxisToSRSAxisMapping"]=layer.crs.axis_mapping_list()
            gf["coordinateSystem"]=cs
        lo["geometryFields"]=[gf]
        lo["featureCount"]=len(layer.features)
        if getattr(layer,"_sql_geometry_column",None):
            lo["geometryColumn"]=layer._sql_geometry_column
        lo["fields"]=[f.json_dict() for f in layer.fields]
        if features_flag or opts.get("features"):
            limit=opts.get("limit")
            feats=[]
            features=layer.features[:int(limit)] if limit not in (None,"",0) else layer.features
            for feat in features:
                feats.append(_feature_json_obj(feat,layer))
            lo["features"]=feats
        layers.append(lo)
    obj["layers"]=layers
    if summary_flag:
        return obj
    obj["metadata"]=dict(ds.metadata.get("",{})) if isinstance(ds.metadata,dict) and ds.metadata else {}
    # Vector dataset metadata seems always flat {} (not domains)
    obj["domains"]={}
    obj["relationships"]={}
    return obj

def _feature_json_obj(feat,layer):
    o={}
    o["type"]="Feature"
    props={}
    # properties in field order with typed conversion for JSON (info json coords use coord formatting externally handled by from feature geometry)
    for fld in layer.fields:
        if fld.name in feat.properties:
            props[fld.name]=_vector_json_value(feat.properties[fld.name],fld)
    for k,v in feat.properties.items():
        if k not in props:
            props[k]=_vector_json_value(v,None)
    o["properties"]=props
    o["fid"]=feat.fid
    o["geometry"]=_geom_json_numbers(feat.geometry) if feat.geometry is not None else None
    return o

def _vector_json_value(v,field):
    if v is None:return None
    if field and field.type=="Integer" and field.subtype=="Boolean":
        return bool(v)
    if field and field.type=="Real":
        return float(v)
    if field and field.subtype=="JSON":
        # Info JSON Feature properties: fields that are String JSON - original outputs raw typed? For obj field it may output object, for s field string
        if isinstance(v,str):
            t=v.strip()
            if t.startswith("{") or t.startswith("["):
                try:return json.loads(v,parse_float=float)
                except:return v
            return v
        return v
    return v

def _geom_json_numbers(geom):
    if geom is None:return None
    from gutil import FmtNumber, format_coord
    def coords(c):
        if isinstance(c,list):
            if len(c)>0 and isinstance(c[0],(int,float)):
                return [FmtNumber(float(x),format_coord(float(x))) for x in c]
            return [coords(x) for x in c]
        return c
    out={"type":geom.get("type") if geom.get("type")!="LinearRing" else "LineString"}
    if "coordinates" in geom:out["coordinates"]=coords(geom["coordinates"])
    if "geometries" in geom:out["geometries"]=[_geom_json_numbers(g) for g in geom["geometries"]];out["type"]="GeometryCollection"
    return out

def vector_info_json(ds,opts,layer_filter=None):
    features_flag=bool(opts.get("features") or opts.get("limit") or opts.get("fid") is not None)
    summary=bool(opts.get("summary"))
    obj=vector_info_object(ds,opts,layer_filter,features_flag,summary)
    return gdal_json_dumps(obj)+"\n"

def _format_field_value_text(value,field):
    if value is None:return "(null)"
    if field and field.type in ("StringList","IntegerList","Integer64List","RealList"):
        vals=value if isinstance(value,list) else [value]
        fmt=[]
        for v in vals:
            if field.type=="RealList":fmt.append(fmt_real_text(v))
            else:fmt.append(str(v))
        return f"({len(vals)}:{','.join(fmt)})"
    if field and field.type=="Real":
        return fmt_real_text(value)
    if field and field.type=="Date":
        s=str(value);return s.replace("-","/")
    if field and field.type=="DateTime":
        s=str(value)
        # ISO YYYY-MM-DDTHH:MM:SSZ -> YYYY/MM/DD HH:MM:SS+00; fractional etc later
        s=s.replace("T"," ")
        if s.endswith("Z"):s=s[:-1]+"+00"
        s=s.replace("-","/",2)  # only date separators (first two -)
        # above replace count would also? python replace with count param: s.replace("-","/",2) not supported count kw? It is positional third arg - code above used count as third positional to replace works.
        return s
    if isinstance(value,bool):
        return "1" if value else "0"
    return str(value)

def vector_info_text(ds,opts,layer_filter=None,driver_null=False,sql_mode=False):
