                try:fid_val=int(fid_filter)
                except:fid_val=fid_filter
                feats=[f for f in feats if f.fid==fid_val]
            limit=opts.get("limit")
            if limit not in (None,""):
                try:feats=feats[:int(limit)]
                except:pass
            for feat in feats:
                lines.append(f"OGRFeature({layer.name}):{feat.fid}")
                for fld in layer.fields:
                    if fld.name in feat.properties:
                        value=feat.properties[fld.name]
                        type_disp=fld.type+(f"({fld.subtype})" if fld.subtype else "")
                        lines.append(f"  {fld.name} ({type_disp}) = {_format_field_value_text(value,fld)}")
                for k,v in feat.properties.items():
