def _stat_fmt_num(v):
    s=format(float(v),'.3f')
    return FmtNumber(float(s), format_json_float(float(s)))

def _nodata_json_value(band):
    nd=band.nodata
    if nd is None:return None
    from rastermodel import DTYPES
    kind=DTYPES[band.dtype]["kind"]
    if isinstance(nd,complex) or kind=="complex":
        # JSON nodata for complex? It may be a string? keep float real
        return float(nd.real) if isinstance(nd,complex) else float(nd)
    if kind=="int":
