        except:return nd
    return float(nd)

def _format_nodata_text(band):
    nd=band.nodata
    if nd is None:return None
    if isinstance(nd,complex):
        return f"{_plain_num(nd.real)},{_plain_num(nd.imag)}"
    if isinstance(nd,float):
        if math.isnan(nd):return "nan"
        if math.isinf(nd):return "inf" if nd>0 else "-inf"
        if nd==int(nd) and abs(nd)<1e15:return str(int(nd))
        return format(nd,'.15g')
    return str(nd)

def _plain_num(v):
    if isinstance(v,float):
        if v==int(v) and abs(v)<1e15:return str(int(v))
        return format(v,'.15g')
    return str(v)

def _corner_points(ds):
    gt=ds.geotransform
    def pt(px,py):
        return (gt[0]+px*gt[1]+py*gt[2], gt[3]+px*gt[4]+py*gt[5])
    return {
        "upperLeft":pt(0,0),
        "lowerLeft":pt(0,ds.height),
        "lowerRight":pt(ds.width,ds.height),
        "upperRight":pt(ds.width,0),
        "center":pt(ds.width/2,ds.height/2),
    }

def _corner_decimals(ds,x,y):
    if not ds.has_geotransform and not ds.crs:
        return (1,7)
    # per-point geography heuristic
    if -180<=x<=180 and -90<=y<=90:
        return (7,12)
    else:
        return (3,12)

def _round_corner(ds,x,y):
    dec,width=_corner_decimals(ds,x,y)
    return (round(float(x),dec),round(float(y),dec))

def _format_corner_text(ds,x,y):
    dec,width=_corner_decimals(ds,x,y)
    return (f"{x:{width}.{dec}f}", f"{y:{width}.{dec}f}")

def _dms_component(angle, is_lon):
    if is_lon and (angle<-180 or angle>180):
        return "Invalid angle"
    # Hemisphere
    hemi=""
    if is_lon:
        hemi="W" if angle<0 else "E"
    else:
        hemi="S" if angle<0 else "N"
    total=abs(float(angle))*3600.0+0.005
    deg=int(total//3600)
    rem=total-deg*3600
    minute=int(rem//60)
    sec=rem-minute*60
    # sec formatted width5 .2f could be 60.00 due binary addition, carry if >=59.995 and formatting would round up
    if sec>=59.995:
        sec=0.0; minute+=1
        if minute>=60:
            minute=0;deg+=1
    return f"{deg:3d}d{minute:2d}'{sec:5.2f}\"{hemi}"

def _transform_point_to_lonlat(ds,x,y):
    if not ds.crs:return None
    target=None
    crs=ds.crs
    # geographic base / itself
    if crs.is_geographic():
        return (x,y)
    # base_crs from projjson
    pj=crs.get_projjson() if hasattr(crs,"get_projjson") else None
    target_epsg=4326
    if isinstance(pj,dict):
        base=pj.get("base_crs") or {}
        idobj=base.get("id") if isinstance(base,dict) else None
        if isinstance(idobj,dict) and idobj.get("authority")=="EPSG":
            try:target_epsg=int(idobj.get("code"))
            except:pass
    target=crsmod.epsg_crs(target_epsg,"epsg_db")
    if target is None:return None
    try:
        return crsmod.transform_point(crs,target,x,y)
    except Exception:
        return None

def _metadata_selected(metadata_dict, opts, include_image_structure=False, is_band=False, list_mdd=False):
    if opts.get("no-md"):
        return {}
    metadata_dict=metadata_dict or {}
    selected={}
    mdd=opts.get("metadata-domain")
    domains=[]
    # default domains
    if "" in metadata_dict and metadata_dict[""]:
        domains.append("")
    if include_image_structure and "IMAGE_STRUCTURE" in metadata_dict and metadata_dict["IMAGE_STRUCTURE"]:
        domains.append("IMAGE_STRUCTURE")
    # if a band and metadata has default empty etc, original JSON always includes metadata:{} and no domains; selected empty.
    if mdd:
        if str(mdd).lower()=="all":
            for d in metadata_dict.keys():
                if d not in domains and metadata_dict[d]:
                    domains.append(d)
        else:
            if mdd in metadata_dict and metadata_dict[mdd] and mdd not in domains:
                domains.append(mdd)
    for d in domains:
        selected[d]=dict(metadata_dict[d])
    # If list_mdd, caller will insert metadataDomains first.
    return selected

