    md=metadata_dict or {}
    domains=[]
    for d,vals in md.items():
        if vals:
            domains.append("(default)" if d=="" else d)
    if not is_band:
        domains.append("DERIVED_SUBDATASETS")
    else:
        if driver=="VRT":
            domains.append("LocationInfo")
