        bo["type"]=band.dtype
        bo["colorInterpretation"]=band.color_interp
        if band.description:
            bo["description"]=band.description
        bi=stats_data.get(i,{}) if isinstance(stats_data,dict) else {}
        # stored/computed minmax
        stored_stats=statsmod.get_band_statistics_from_metadata(band)
        stored_minmax=statsmod.band_minmax_stored(band)
        if ds.driver_short=="VRT" and stored_minmax is None and "computed_minmax" not in bi:
            # VRT bands can compute min/max from sources
            try:
                mn,mx=statsmod.compute_minmax(band); stored_minmax=(mn,mx)
            except Exception:pass
        if stored_minmax is not None:
            bo["min"]=_stat_fmt_num(stored_minmax[0]); bo["max"]=_stat_fmt_num(stored_minmax[1])
        if opts.get("min-max") or opts.get("mm"):
            mn,mx=bi.get("computed_minmax") or statsmod.compute_minmax(band)
            bo["computedMin"]=_stat_fmt_num(mn);bo["computedMax"]=_stat_fmt_num(mx)
        stats_to_show=None
        if opts.get("stats") or opts.get("approx-stats"):
            stats_to_show=bi.get("stats") or statsmod.get_band_statistics_from_metadata(band) or statsmod.compute_statistics(band, approx=bool(opts.get("approx-stats")))
        elif stored_stats:
            stats_to_show=stored_stats
        if stats_to_show:
            bo["minimum"]=_stat_fmt_num(stats_to_show["minimum"]);bo["maximum"]=_stat_fmt_num(stats_to_show["maximum"]);bo["mean"]=_stat_fmt_num(stats_to_show["mean"]);bo["stdDev"]=_stat_fmt_num(stats_to_show["stddev"])
        if opts.get("checksum"):
            bo["checksum"]=bi.get("checksum", statsmod.checksum_band(band))
        if opts.get("hist"):
            hist=bi.get("histogram") or statsmod.histogram_for_info(band)
            bo["histogram"]={"count":hist["buckets"],"min":hist["min"],"max":hist["max"],"buckets":hist["counts"]}
        if band.nodata is not None and not opts.get("no-nodata"):
            bo["noDataValue"]=_nodata_json_value(band)
        if band.unit:
            bo["unit"]=band.unit
        if band.offset!=0.0:
            bo["offset"]=band.offset
        if band.scale!=1.0:
            bo["scale"]=band.scale
        if band.category_names:
            bo["categoryNames"]=list(band.category_names)
        if band.color_table and not opts.get("no-ct"):
            bo["colorTable"]={"palette":[[int(c[0]),int(c[1]),int(c[2]),int(c[3])] for c in band.color_table]}
            # Original key structure might differ; will adjust in palette probing.
        if band.overviews:
            ovs=[]
            for ov in band.overviews:
                ovs.append({"size":[ov.width,ov.height],"block":[int(ov.block_size[0]),int(ov.block_size[1])]})
            bo["overviews"]=ovs
        # mask not implemented
        if not opts.get("no-md"):
            md=_metadata_selected(band.metadata,opts,include_image_structure=False,is_band=True)
            if opts.get("list-mdd") or opts.get("list-metadata-domains"):
                domains_avail=_metadata_domains_available(band,True,ds.driver_short,band.metadata)
                newmd={"metadataDomains":domains_avail};newmd.update(md);md=newmd
            bo["metadata"]=md
        band_objs.append(bo)
    obj["bands"]=band_objs
    obj["stac"]=_stac_object(ds,opts,stats_data)
    return obj

def _json_num_from_rounded(v):
    s=repr(float(v))
    # Python repr may use exponent for very small/large; original corner json for 0.0000001 uses 0.0000001 not 1e-07, for 1e20 uses 1000...0
    if 'e' in s or 'E' in s:
        # expand to fixed using format .15f trimmed (?) corners rounded to 7 dec, so use repr of Decimal?
        s=format(float(v),'.15f').rstrip('0').rstrip('.')
        if '.' not in s:s+='.0'
    if re.fullmatch(r'-?\d+',s):s+='.0'
    return s

def _wgs84_extent(ds):
    # Ring in lon/lat EPSG4326, ordering UL, LL, LR, UR, UL. Densify edges with samples for large / rotated?
    gt=ds.geotransform
    pts=[]
    samples=20  # GDAL uses 20 interpolation steps per edge ??? For a simple bbox with a projected CRS, original output we saw for out2 only corners (5). For a larger UTM, need probe later.
    # To match simple cases, just corners.
    corners=[(0,0),(0,ds.height),(ds.width,ds.height),(ds.width,0),(0,0)]
    ring=[]
    target=crsmod.epsg_crs(4326,"epsg_db")
    for px,py in corners:
        x=gt[0]+px*gt[1]+py*gt[2];y=gt[3]+px*gt[4]+py*gt[5]
        if ds.crs.epsg==4326:
            lon,lat=x,y
        else:
            try:lon,lat=crsmod.transform_point(ds.crs,target,x,y)
            except Exception:return None
        ring.append([lon,lat])
    return {"type":"Polygon","coordinates":[ring]}

def _stac_object(ds,opts,stats_data):
    stac={}
    stac["proj:shape"]=[ds.height,ds.width]
    if ds.crs:
        wkt=ds.crs.get_wkt()
        if wkt:stac["proj:wkt2"]=wkt
        if ds.crs.epsg:stac["proj:epsg"]=int(ds.crs.epsg)
        pj=ds.crs.get_projjson()
        if pj is not None:stac["proj:projjson"]=pj
    if ds.has_geotransform:
        gt=ds.geotransform
        stac["proj:transform"]=[fmt_geotransform(gt[1]),fmt_geotransform(gt[2]),fmt_geotransform(gt[0]),fmt_geotransform(gt[4]),fmt_geotransform(gt[5]),fmt_geotransform(gt[3])]
    raster_bands=[]
    eo_bands=[]
    from rastermodel import DTYPES
    for i,band in enumerate(ds.bands):
        rb={}
        dt=DTYPES[band.dtype].get("stac")
        if dt:rb["data_type"]=dt
        else:rb["data_type"]=band.dtype.lower()
        bi=stats_data.get(i,{}) if isinstance(stats_data,dict) else {}
        stats_to_show=None
        if opts.get("stats") or opts.get("approx-stats"):
            stats_to_show=bi.get("stats") or statsmod.get_band_statistics_from_metadata(band) or statsmod.compute_statistics(band)
        elif statsmod.get_band_statistics_from_metadata(band):
            stats_to_show=statsmod.get_band_statistics_from_metadata(band)
        if band.nodata is not None and not opts.get("no-nodata"):
            rb["nodata"]=_nodata_json_value(band)
        if band.unit:
            rb["unit"]=band.unit
        if band.scale!=1.0 or band.offset!=0.0:
            # GDAL bug observed: outputs nulls
            rb["scale"]=None;rb["offset"]=None
        if stats_to_show:
            rb["stats"]={"minimum":_stat_fmt_num(stats_to_show["minimum"]),"maximum":_stat_fmt_num(stats_to_show["maximum"]),"mean":_stat_fmt_num(stats_to_show["mean"]),"stddev":_stat_fmt_num(stats_to_show["stddev"])}
        if opts.get("hist"):
            hist=bi.get("histogram") or statsmod.histogram_for_info(band)
            rb["histogram"]={"count":hist["buckets"],"min":hist["min"],"max":hist["max"],"buckets":hist["counts"]}
        raster_bands.append(rb)
        eo={"name":f"b{i+1}"}
        eo["description"]=band.description if band.description else band.color_interp
        eo_bands.append(eo)
    stac["raster:bands"]=raster_bands
    stac["eo:bands"]=eo_bands
    return stac

def raster_info_json(ds,opts,stats_data=None):
    obj=raster_info_object(ds,opts,stats_data)
    return gdal_json_dumps(obj)+"\n"

def format_text_metadata(metadata_dict, opts, include_image=False, is_band=False, indent=""):
    if opts.get("no-md"):return []
    out=[]
    # domains in selected order: default first, IMAGE_STRUCTURE, then other specified domains
    selected=_metadata_selected(metadata_dict,opts,include_image_structure=include_image,is_band=is_band)
    # Text titles: default "Metadata:", IMAGE_STRUCTURE "Image Structure Metadata:", other 'Metadata (DOMAIN):'
    for domain,vals in selected.items():
        if domain=="IMAGE_STRUCTURE":
            title="Image Structure Metadata:"
        elif domain=="":
            title="Metadata:"
        else:
            title=f"Metadata ({domain}):"
        out.append(indent+title)
        for k,v in vals.items():
            out.append(indent+f"  {k}={v}")
    return out

def raster_info_text(ds,opts,stats_data=None):
    lines=[]
    lines.append(f"Driver: {ds.driver_short}/{ds.driver_long}")
    if not opts.get("no-fl"):
        files=ds.files if ds.files else [ds.description]
        for i,f in enumerate(files):
            if i==0:lines.append(f"Files: {f}")
            else:lines.append(f"       {f}")
    lines.append(f"Size is {ds.width}, {ds.height}")
    # CRS
    crs_format=(opts.get("crs-format") or "AUTO")
    if ds.crs and str(crs_format).upper()=="WKT2":
        lines.append("Coordinate Reference System WKT:")
        wkt=ds.crs.get_wkt()
        if wkt:lines.extend(wkt.splitlines())
    elif ds.crs and str(crs_format).upper()=="PROJJSON":
        lines.append("Coordinate Reference System PROJJSON:")
        pj=ds.crs.get_projjson()
        if pj is not None:
            # Use std json with colon spaces like PROJ output. Need serialize RawNumber floats - convert to regular via json loads dumps trick
            pj_plain=json.loads(json.dumps(pj,default=float))
            lines.extend(json.dumps(pj_plain,indent=2,ensure_ascii=False).splitlines())
    elif ds.crs:
        lines.append("Coordinate Reference System:")
        for s in ds.crs.summary_lines():
            lines.append(f"  - {s}")
    if ds.crs:
        lines.append(f"Data axis to CRS axis mapping: {','.join(str(x) for x in ds.crs.axis_mapping_list())}")
    # GCP coordinate system / etc omitted
