    lines.append("Corner Coordinates:")
    corners=_corner_points(ds)
    labels=[("Upper Left  ","upperLeft"),("Lower Left  ","lowerLeft"),("Upper Right ","upperRight"),("Lower Right ","lowerRight"),("Center      ","center")]
    for label,key in labels:
        x,y=corners[key]
        xs,ys=_format_corner_text(ds,x,y)
        line=f"{label}({xs},{ys})"
        if ds.crs:
            ll=_transform_point_to_lonlat(ds,x,y)
            if ll is not None:
                lon,lat=ll
