        lines.append(f"Band {i+1} Block={band.block_size[0]}x{band.block_size[1]} Type={band.dtype}, ColorInterp={band.color_interp}")
        if band.description:
            lines.append(f"  Description = {band.description}")
        stored_minmax=statsmod.band_minmax_stored(band)
