            if vfs.exists(root+ext):
                try:vfs.remove(root+ext)
                except:pass
        return
    if vfs.is_dir(p):
        # remove directory dataset recursively
        import shutil
        try:
            if vfs.is_mem_path(p):vfs.remove(p)
            else:shutil.rmtree(p)
        except:pass
        return
    if vfs.exists(p):
        try:vfs.remove(p)
        except:pass
