def validate_output(call,output,output_format,kind):
    """Returns driver name. Raises parse error for existence/guess issues."""
    parsed=call.parsed
    # GDALG handled by caller before validate normally
    fmt=output_format
    if fmt and str(fmt).upper()=="GDALG":
        return "GDALG"
    if not fmt and _is_gdalg_output(output):
        return "GDALG"
    if kind=="raster":
        driver=guess_raster_driver(str(output),fmt) if not fmt or output is not None else fmt
    elif kind=="vector":
        driver=guess_vector_driver(str(output),fmt) if not fmt or output is not None else fmt
    elif kind=="mdim":
        driver=fmt or guess_raster_driver(str(output),fmt)
    else:
        driver=fmt
    if fmt:
        driver=fmt
    if not driver or driver not in ("GTiff","COG","VRT","MEM","GeoJSON","GeoJSONSeq","ESRI Shapefile"):
        if kind=="raster":
            raise_run_lines(call,[f"ERROR 1: Could not identify an output driver for {output}"])
        else:
            raise_run_lines(call,[f"ERROR 1: Cannot guess driver for {output}"])
    # existence
    overwrite=bool(parsed.values.get("overwrite",False))
    append=bool(parsed.values.get("append",False))
    update=bool(parsed.values.get("update",False))
    overwrite_layer=bool(parsed.values.get("overwrite-layer",False))
    upsert=bool(parsed.values.get("upsert",False))
    if driver!="MEM" and dataset_exists(output,driver) and not (overwrite or append or update or overwrite_layer or upsert):
        opts=_overwrite_suffix(call.node)
        # call.parse_error adds ERROR and usage
        raise ParseError(f"ERROR 1: {call.algo_name}: Dataset '{output}' already exists. You may specify the {opts} option.\n"+call.usage_appendix(),code=1)
    return driver

def prepare_output(call,output,driver):
    parsed=call.parsed
    overwrite=bool(parsed.values.get("overwrite",False))
    if overwrite and driver!="MEM":
        delete_dataset_files(output,driver)

def _overwrite_suffix(node):
    candidates=[("overwrite","--overwrite"),("overwrite-layer","--overwrite-layer"),("append","--append"),("update","--update")]
    present=[label for key,label in candidates if key in node.args]
    if not present:return "--overwrite"
    return "/".join(present)

def _is_gdalg_output(output):
    p=str(output).lower()
    return p.endswith(".gdalg.json") or p.endswith(".gdalg")

def config_warnings_for_operation(call,kind="generic"):
    # kinds: single, read_write, read_info, create etc.
    if not call.parsed.config_equals:return
    algo=call.algo_name
    if kind=="read_write":
        steps=[algo,"read","write"]
    elif kind=="read_info":
        steps=[algo,"read",algo]
    elif kind=="read":
        steps=[algo,"read"]
    elif kind=="shortcut_info":
        steps=["read","info"]
    elif kind=="shortcut_convert":
        # top-level convert success unknown; when output existed only one warning because failure before steps, callers for success may use read_write with algo convert?
        steps=[algo,"read","write"]
    else:
        steps=[algo]
    for s in steps:
        sys.stderr.write(f"Warning 1: {s}: Configuration options passed with the 'config' argument are ignored\n")

def one_config_warning(call):
    if call.parsed.config_equals:
        sys.stderr.write(f"Warning 1: {call.algo_name}: Configuration options passed with the 'config' argument are ignored\n")
        return True
    return False

def raise_not_implemented(call):
    raise_run_lines(call,[f"ERROR 1: {call.algo_name}: Not implemented"])

def geos_error(call):
    raise_run_lines(call,[f"ERROR 6: {call.algo_name}: This algorithm is only supported for builds against GEOS"])
