    # also specified that may not be in node.args? none
    exclude={"output","output-format","help","json-usage","config"}
    for k in keys:
        if k in exclude:continue
        spec=node.args.get(k)
        if spec is None:continue
        # Long canonical option: use --{k}
        opt="--"+k
        val=parsed.values.get(k)
        if spec.is_bool:
            if val is True:parts.append(opt)
            elif val is False:parts.append(opt+"=false")
            continue
        if spec.is_list:
            vals=val or []
            if spec.type in ("integer_list","real_list"):
                if vals:parts.extend([opt,",".join(_num(v) for v in vals)])
            elif spec.type=="dataset_list":
                for v in vals:parts.extend([opt,_quote(v)])
            else:
                for v in vals:parts.extend([opt,_quote(_num(v) if isinstance(v,(int,float)) else v)])
            continue
        # scalar
        parts.extend([opt,_quote(_num(val) if isinstance(val,(int,float)) and not isinstance(val,bool) else val)])
    if stream_output:
        parts.extend(["--output-format","stream","--output","streamed_dataset"])
    return " ".join(parts)

def write_gdalg(call,output,command_path=None):
    # existence check handled caller? Implement here based on parsed overwrite flags
    parsed=call.parsed
    if vfs.exists(str(output)) and not (parsed.values.get("overwrite") or parsed.values.get("append") or parsed.values.get("update") or parsed.values.get("overwrite-layer")):
        opts=[]
        for key,label in [("overwrite","--overwrite"),("overwrite-layer","--overwrite-layer"),("append","--append"),("update","--update")]:
            if key in call.node.args:opts.append(label)
        suffix="/".join(opts) if opts else "--overwrite"
        raise ParseError(f"ERROR 1: {call.algo_name}: File '{output}' already exists. You may specify the {suffix} option.\n"+call.usage_appendix(),code=1)
    cmd=serialize_call(call,command_path,stream_output=True)
    esc=cmd.replace('\\','\\\\').replace('"','\\"').replace('/','\\/')
    text='{\n  "type":"gdal_streamed_alg",\n  "command_line":"'+esc+'",\n  "gdal_version":"3130000"\n}'
    vfs.write_binary(str(output),text.encode("utf-8"))
    return 0
