                hist=band.histogram or statsmod.histogram_for_info(band)
                band.histogram=hist
                entry["histogram"]=hist
                # Histogram computation also creates stats in PAM / band metadata in original (as shown --hist output includes stats lines and PAM has stats)
                if not statsmod.get_band_statistics_from_metadata(band):
                    stats=statsmod.compute_statistics(band)
                    statsmod.set_band_statistics_metadata(band,stats)
                    entry["stats"]=stats
            if opts.get("checksum"):
                entry["checksum"]=statsmod.checksum_band(band)
            if opts.get("min-max") or opts.get("mm"):
                entry["computed_minmax"]=statsmod.compute_minmax(band)
            data[i]=entry
        # Write PAM (info only writes if stats/hist computed; original writes even if stats were already? It may rewrite same, no difference)
        if ds.description and not str(ds.description).startswith("/vsimem"):
            pammod.write_pam_stats(ds,ds.description)
    else:
        for i,band in enumerate(ds.bands):
            entry={}
            if opts.get("checksum"):entry["checksum"]=statsmod.checksum_band(band)
            if opts.get("min-max") or opts.get("mm"):entry["computed_minmax"]=statsmod.compute_minmax(band)
            if entry:data[i]=entry
    return data

def handler_raster_info(call):
    # Validate CRS format vs JSON after open? Original with input nonexistent gave Error4 before this? Open first.
    ds=open_raster(call)
    _check_crs_format_json(call)
    # config= warnings for success path
    config_warnings_for_operation(call,"read_info")
    sd=_raster_stats_data(call,ds)
    if call.parsed.values.get("subdataset"):
        idx=int(call.parsed.values.get("subdataset"))
        # subdataset support minimal: metadata domain SUBDATASETS contains keys SUBDATASET_1_NAME etc. If idx valid, open that.
        subs=ds.metadata.get("SUBDATASETS",{})
        name_key=f"SUBDATASET_{idx}_NAME"
        if name_key in subs:
            ds=open_raster_dataset(subs[name_key])
        else:
            call.run_error(f"Subdataset {idx} does not exist")
    if _is_json(call):
        sys.stdout.write(infomod.raster_info_json(ds,call.parsed.values,sd))
