def handler_vector_info(call):
    inputs=call.parsed.values.get("input") or []
    if len(inputs)>1:
        line="ERROR 1: read: 2 values have been specified for argument 'input', whereas exactly 1 was expected.\n"
        raise ParseError(line+line,code=1)
    _check_crs_format_json(call)
    ds=open_vector(call)
    config_warnings_for_operation(call,"read_info")
    # layer filtering
    layer_filter=call.parsed.values.get("input-layer") or []
    if layer_filter:
        names=[l.name for l in ds.layers]
        for lf in layer_filter:
            # can be index? OGR layer spec can be name or index. int index 0-based?
            if lf not in names:
                # Handle numeric index as string
                ok=False
                try:
                    idx=int(lf)
                    if 0<=idx<len(names):
                        # convert filter entry to name
                        layer_filter=[names[idx] if str(x)==str(lf) else x for x in layer_filter]; ok=True
                except:pass
                if not ok:
                    raise ParseError(f"ERROR 1: read: Cannot find source layer '{lf}'\n",code=1)
    driver_null=bool(layer_filter)
    # SQL/Where/FID processing on a copy
    out_ds=ds
    sql_mode=False
    # WHERE and SQL are handled in vectorsql module
    import vectorsql
    header=""
    # For SQL/where invalid errors, original already printed INFO header (text mode). We'll construct header for possible stdout on errors in text mode.
    if not _is_json(call):
        driver=("(null)" if driver_null else ds.driver_short)
        header=f"INFO: Open of `{ds.description}'\n      using driver `{driver}' successful.\n"
    try:
        if call.parsed.values.get("sql"):
            sql=call.parsed.values.get("sql")
            dialect=call.parsed.values.get("dialect")
            out_ds=vectorsql.apply_sql(ds,sql,dialect=dialect)
            sql_mode=True
            # info output for SELECT * showed Geometry Column line; for SELECT name only, no line. Determine based on whether query selects geometry - vectorsql marks layer.
        elif call.parsed.values.get("where"):
            try:
                out_ds=vectorsql.apply_where(ds,call.parsed.values.get("where"),layer_filter)
            except vectorsql.VectorSQLError as e:
                # Info where failure behavior: prints header to stdout, errors to stderr, exit 0 (text only). In JSON mode, likely same? It would print header ONLY (not valid JSON)?? We'll mimic text behavior and for JSON return header as stdout (bug-compatible maybe)
                sys.stdout.write(header)
                sys.stderr.write(str(e))
                if not str(e).endswith("\n"):sys.stderr.write("\n")
                return 0
    except vectorsql.VectorSQLError as e:
        err=ParseError(str(e),code=1)
        err.stdout=header
        raise err
    # Default text/json
    opts=dict(call.parsed.values)
    if call.parsed.values.get("fid") is not None:
        opts["fid"]=call.parsed.values.get("fid")
    if _is_json(call):
        sys.stdout.write(infomod.vector_info_json(out_ds,opts,layer_filter if layer_filter else None))
    else:
        txt=infomod.vector_info_text(out_ds,opts,layer_filter if layer_filter else None,driver_null=driver_null,sql_mode=getattr(out_ds,"_sql_mode",False))
        # FID not found quirk
        if opts.get("fid") is not None:
            fid_val=opts.get("fid")
            # Check across selected layers
            found=False
            for l in out_ds.layers:
                if layer_filter and l.name not in layer_filter:continue
                if any(str(f.fid)==str(fid_val) for f in l.features):found=True
            if not found:
                # insert before trailing? Original output puts Unable line after fields (no blank) and no trailing feature blank.
                # Our txt ends with \n after fields; append
                txt+=f"Unable to locate feature id {fid_val} on this layer.\n"
        sys.stdout.write(txt)
    return 0

