# ---------- helpers for raster creation/convert ----------
def _parse_nodata_arg(value, call, arg_name="nodata"):
    if value is None:return None,False
    s=str(value).strip()
    low=s.lower()
    if low=="none":return None,True
    if low=="nan":return float("nan"),False
    if low=="inf":return float("inf"),False
    if low=="-inf":return float("-inf"),False
    try:
        return float(s),False
    except:
        call.parse_error(f"{call.algo_name}: Value of '{arg_name}' should be 'none', a numeric value, 'nan', 'inf' or '-inf'",errnum=5)

def _validate_bbox(call,bbox):
    if bbox is None:return
    if len(bbox)!=4:return
    if bbox[0]>bbox[2] or bbox[1]>bbox[3]:
        raise ParseError("ERROR 1: Value of 'bbox' should be xmin,ymin,xmax,ymax with xmin <= xmax and ymin <= ymax\n"+call.usage_appendix(),code=1)

def _sort_metadata_inplace(ds):
    # Used for CreateCopy-like output preparation
    if isinstance(ds,RasterDataset):
        for dom in list(ds.metadata.keys()):
            ds.metadata[dom]=dict(sorted(ds.metadata[dom].items(),key=lambda kv:kv[0]))
        for b in ds.bands:
            for dom in list(b.metadata.keys()):
                b.metadata[dom]=dict(sorted(b.metadata[dom].items(),key=lambda kv:kv[0]))
    elif isinstance(ds,VectorDataset):
        pass

def _write_raster(call,ds,output,driver,creation_opts,preserve=True,use_source_block=True,progress=True):
    if driver=="COG":
        from gcontext import tms_warnings
        sys.stderr.write(tms_warnings(1))
    warn_creation_options(driver,creation_opts,None,call,kind="raster",output_path=output)
    prepare_output(call,output,driver)
    out_ds=ds
    # CreateCopy metadata sorting only if preserve and source had metadata? Use copy to avoid mutating input ds for subsequent pipeline steps.
    if preserve:
        out_ds=ds.copy();_sort_metadata_inplace(out_ds)
    from rasterio import write_raster_dataset
    co_list=[f"{k}={v}" for k,v in creation_opts]
    drv=write_raster_dataset(out_ds,output,output_format=driver,creation_options=co_list,preserve_colorinterp=preserve,use_source_block=use_source_block)
    if progress:
        call.progress()
    return drv

def handler_raster_create(call):
    p=call.parsed
    output=p.values.get("output")
    if isinstance(output,list):output=output[0] if output else None
    like_paths=p.values.get("input") or []
    like_ds=None
    if like_paths:
        like_ds=open_rasters(call,like_paths)[0]
    size=p.values.get("size") if p.has("size") else None
    if not size and not like_ds:
        one_config_warning(call)
        raise ParseError("ERROR 5: create: Argument 'size' should be specified, or 'like' dataset should be specified\n",code=1)
    # nodata validation
    nodata_val=None; nodata_none=False
    if p.has("nodata"):
        nodata_val,nodata_none=_parse_nodata_arg(p.values.get("nodata"),call)
