        one_config_warning(call)
        return gdalgmod.write_gdalg(call,output)
    one_config_warning(call)
    # Build dataset
    bands=[]
    for i in range(band_count):
        if dtype_arg:
            dt=canon_dtype(dtype_arg)
        elif like_ds and i<len(like_ds.bands):
            dt=like_ds.bands[i].dtype
        elif like_ds and like_ds.bands:
            dt=like_ds.bands[0].dtype
        else:
            dt="Byte"
        burn=0
        if burn_vals:
            burn=burn_vals[0] if len(burn_vals)==1 else burn_vals[i]
        data=[[cast_value(burn,dt) for _ in range(width)] for __ in range(height)]
        nd=None
        if p.has("nodata"):
            nd=None if nodata_none else nodata_val
        elif like_ds and i<len(like_ds.bands):
            nd=like_ds.bands[i].nodata
        ci="Undefined"
        desc="";unit="";scale=1.0;off=0.0
        if like_ds and i<len(like_ds.bands):
            lb=like_ds.bands[i]
            ci=lb.color_interp;desc=lb.description;unit=lb.unit;scale=lb.scale;off=lb.offset
        band=Band(dt,width,height,data,nodata=nd,description=desc,color_interp=ci,scale=scale,offset=off,unit=unit)
        bands.append(band)
    crs_obj=None
    if p.has("crs"):
        c,err,ok=crsmod.parse_crs_input(p.values.get("crs"))
        crs_obj=c if ok else None
    elif like_ds:
        crs_obj=like_ds.crs
    gt=None;has_gt=False
    if bbox:
        xmin,ymin,xmax,ymax=[float(x) for x in bbox]
        gt=(xmin,(xmax-xmin)/width if width else 0,0.0,ymax,0.0,-(ymax-ymin)/height if height else 0);has_gt=True
    elif like_ds and like_ds.has_geotransform:
        gt=like_ds.geotransform;has_gt=True
    metadata={}
    if like_ds and p.values.get("copy-metadata"):
        metadata=copy.deepcopy(like_ds.metadata)
        metadata.pop("IMAGE_STRUCTURE",None)
    # Apply metadata argument in order
    for k,v in parse_kv_options(p.values.get("metadata") or []):
        metadata.setdefault("",{})[k]=v
    # AREA_OR_POINT: if bbox/crs or like with CRS, original GTiff output derives Area from geokeys, not needed in internal metadata except VRT output written from a created dataset: When raster create --crs EPSG:4326 --format VRT, does VRT include AREA_OR_POINT metadata? The direct32633 VRT had no Metadata element, meaning create via VRT driver doesn't include it. When create GTiff and read, reader gives Area. So do not set.
    ds=RasterDataset(width,height,bands,gt,crs_obj,metadata,driver_short=driver if driver in ("GTiff","VRT","COG","MEM") else "MEM",driver_long=driver,description=str(output), has_geotransform=has_gt)
    if like_ds and p.values.get("copy-overviews"):
        for i,lb in enumerate(like_ds.bands):
            if i<len(bands):
                bands[i].overviews=[ov.copy() for ov in lb.overviews]
    creation_opts=parse_kv_options(p.values.get("creation-option") or [])
    # MEM
    if driver=="MEM":
        if burn_vals:
            pass
        return 0
    # VRT burn failure after writing empty file
    if driver=="VRT":
        # Write VRT with bands as zero (not burn)
        # Prepare bands set to 0 in a copy if burn specified, because original VRT file contents have VRTRasterBand empty (zero)
        prepare_output(call,output,driver)
        warn_creation_options(driver,creation_opts,None,call,kind="raster",output_path=output)
        # For VRT creation, ds protos: its band data are burn values in memory but VRT writer with no source would read back as zeros regardless - acceptable
        from rasterio import write_raster_dataset
        write_raster_dataset(ds,output,output_format="VRT",creation_options=[f"{k}={v}" for k,v in creation_opts])
