            msgs+="ERROR 1: create: Setting burn value failed\n"
            raise ParseError(msgs,code=1)
        return 0
    # GTiff/COG direct create: preserve=False and use_source_block = (like_ds is not None)
    _write_raster(call,ds,output,driver,creation_opts,preserve=False,use_source_block=bool(like_ds),progress=False)
