def handler_raster_convert(call):
    in_ds=open_raster(call)
    output=call.parsed.values.get("output")
    if isinstance(output,list):output=output[0] if output else None
    fmt=_output_format(call)
    driver=validate_output(call,output,fmt,"raster")
    if driver=="GDALG":
        one_config_warning(call)
        return gdalgmod.write_gdalg(call,output)
    config_warnings_for_operation(call,"read_write")
    creation_opts=parse_kv_options(call.parsed.values.get("creation-option") or [])
    out=in_ds.copy()
    if driver=="VRT":
        out._vrt_source_path=str(call.parsed.values.get("input")[0] if isinstance(call.parsed.values.get("input"),list) else call.parsed.values.get("input"))
        out._vrt_source_bands=[dict(filename=out._vrt_source_path,band=i+1,src_rect=(0,0,in_ds.width,in_ds.height),dst_rect=(0,0,in_ds.width,in_ds.height),source_size=(in_ds.width,in_ds.height),source_dtype=b.dtype,source_block=b.block_size) for i,b in enumerate(in_ds.bands)]
        # Creation options warnings etc
        warn_creation_options(driver,creation_opts,None,call,kind="raster",output_path=output)
        prepare_output(call,output,driver)
        _sort_metadata_inplace(out)
        from rasterio import write_raster_dataset
        write_raster_dataset(out,output,output_format="VRT",creation_options=[f"{k}={v}" for k,v in creation_opts])
        call.progress()
        return 0
    if driver=="MEM":
