def _write_vector(call,ds,output,driver,creation_opts,layer_opts,output_layer=None,progress=True):
    warn_creation_options(driver,creation_opts,layer_opts,call,kind="vector",output_path=output)
    prepare_output(call,output,driver)
    from vectorio import write_vector_dataset
    drv=write_vector_dataset(ds,output,output_format=driver,creation_options=[f"{k}={v}" for k,v in creation_opts],layer_creation_options=[f"{k}={v}" for k,v in layer_opts],output_layer=output_layer)
