def handler_vector_convert(call, pseudo_command_path=None):
    in_ds=open_vector(call)
    output=call.parsed.values.get("output")
    if isinstance(output,list):output=output[0] if output else None
    fmt=_output_format(call)
    driver=validate_output(call,output,fmt,"vector")
    if driver=="GDALG":
        one_config_warning(call)
        return gdalgmod.write_gdalg(call,output,command_path=pseudo_command_path)
    # Layer filtering
    ds=in_ds.copy()
    layer_filter=call.parsed.values.get("input-layer") or []
    if layer_filter:
        names=[l.name for l in ds.layers]
        selected=[]
        for lf in layer_filter:
            if lf in names:selected.append(ds.layers[names.index(lf)])
            else:
                raise ParseError(f"ERROR 1: read: Cannot find source layer '{lf}'\n",code=1)
        ds.layers=selected
    if call.parsed.values.get("output-layer") and len(ds.layers)>=1:
        ds.layers[0].name=call.parsed.values.get("output-layer")
    # Append/upsert etc basic
    append=bool(call.parsed.values.get("append") or call.parsed.values.get("upsert"))
    update=bool(call.parsed.values.get("update"))
    overwrite_layer=bool(call.parsed.values.get("overwrite-layer"))
    if (append or update or overwrite_layer) and dataset_exists(output,driver):
        try:
            existing=open_vector_dataset(str(output))
        except Exception:
            existing=None
        if existing:
            # If overwrite layer, just use new ds (prepare without deleting whole file? Generic prepare only deletes on overwrite flag, not overwrite-layer; writer will overwrite file)
            if append and not overwrite_layer:
                # merge features per layer name
                for new_layer in ds.layers:
                    target=None
                    for old in existing.layers:
                        if old.name==new_layer.name:target=old;break
                    if target:
                        start_fid=(max([f.fid for f in target.features])+1) if target.features else 0
                        for offset,f in enumerate(new_layer.features):
                            if call.parsed.values.get("upsert"):
                                # match by fid if present
                                replaced=False
                                for idx,oldf in enumerate(target.features):
                                    if oldf.fid==f.fid:
                                        target.features[idx]=f.copy();replaced=True;break
                                if not replaced:
                                    nf=f.copy();nf.fid=start_fid+offset;target.features.append(nf)
                            else:
                                nf=f.copy();nf.fid=start_fid+offset;target.features.append(nf)
                    else:
                        existing.layers.append(new_layer)
                ds=existing
            else:
                pass
    config_warnings_for_operation(call,"read_write")
    if call.parsed.values.get("no-create-empty-layers"):
        ds.layers=[l for l in ds.layers if len(l.features)>0]
        if not ds.layers:
            call.progress();return 0
    creation_opts=parse_kv_options(call.parsed.values.get("creation-option") or [])
    layer_opts=parse_kv_options(call.parsed.values.get("layer-creation-option") or [])
    if driver=="MEM":
        call.progress();return 0
    _write_vector(call,ds,output,driver,creation_opts,layer_opts,call.parsed.values.get("output-layer"),progress=True)
    return 0

def handler_vector_create(call):
