    # Build layer(s)
    fields=[]; geom_type=p.values.get("geometry-type") or None; crs_obj=None; layer_name=p.values.get("output-layer") or None
    if geom_type:
        normalized=_normalize_geom_type(geom_type)
        if normalized is None:
            call.parse_error(f"{call.algo_name}: Invalid geometry type '{geom_type}'",errnum=1)
        geom_type=normalized
    layers=[]
