        in_filters=p.values.get("input-layer") or []
        src_layers=like_ds.layers
        if in_filters:src_layers=[l for l in src_layers if l.name in in_filters]
        for src in src_layers:
            new=Layer(layer_name or src.name,[f.copy() for f in src.fields],[],geom_type or src.geom_type,src.crs)
            layers.append(new)
    elif p.has("schema"):
        values=_fields_from_schema(call,p.values.get("schema"))
        if values:
            layers=values
    else:
        # fields from --field
        for specf in p.values.get("field") or []:
