    _write_vector(call,ds,output,driver,creation_opts,layer_opts,layer_name,progress=False)
    return 0

def _normalize_geom_type(v):
    s=str(v).strip()
    lookup={
     "unknown":"Unknown (any)","geometry":"Unknown (any)","none":"None","point":"Point","linestring":"LineString","linearring":"LinearRing","polygon":"Polygon","multipoint":"MultiPoint","multilinestring":"MultiLineString","multipolygon":"MultiPolygon","geometrycollection":"GeometryCollection","circularstring":"CircularString","compoundcurve":"CompoundCurve","curvepolygon":"CurvePolygon","multicurve":"MultiCurve","multisurface":"MultiSurface"}
    parts=s.split()
    base=lookup.get(parts[0].lower()) if parts else None
    if base is None:return None
    return base

def _parse_field_spec(call,spe):
    # NAME:TYPE[(width[,precision])]
    m=re.match(r'^([^:]+):([^\(]+)(?:\((\d+)(?:,(\d+))?\))?$',str(spe).strip())
    if not m:
        call.parse_error(f"{call.algo_name}: Invalid field definition '{spe}'",errnum=1)
    name,typ,w,p=m.groups()
    type_lookup={"string":"String","integer":"Integer","integer64":"Integer64","real":"Real","date":"Date","datetime":"DateTime","time":"Time","binary":"Binary","stringlist":"StringList","integerlist":"IntegerList","integer64list":"Integer64List","reallist":"RealList"}
    sub=None
    t=typ.strip()
    if "." in t or "(" in t:
        pass
    if t.lower() not in type_lookup:
        # Subtype notation like String(JSON) not in spec? Type itself could be "Integer(Boolean)" but regex would have handled width as string and failed - leave error
        call.parse_error(f"{call.algo_name}: Unsupported field type: {typ}",errnum=1)
    return Field(name,type_lookup[t.lower()],width=int(w) if w else 0,precision=int(p) if p else 0)

def _fields_from_schema(call,schema):
    # Schema may be filename or JSON string
    import json as _json
    content=None
    if schema and vfs.exists(str(schema)):
        content=vfs.read_binary(str(schema)).decode()
    else:
        # original prints ERROR3 cannot open if invalid JSON string/file but still creates empty - mimic warning/error line and empty layer
        print(f"ERROR 3: Cannot open file '{schema}'",file=sys.stderr)
        return []
    try:
        obj=_json.loads(content)
    except Exception:
        return []
    layers=[]
    for lo in obj.get("layers",[]):
        fields=[]
        for fo in lo.get("fields",[]):
            fields.append(Field(fo.get("name"),fo.get("type","String"),fo.get("subType"),fo.get("width",0) or 0,fo.get("precision",0) or 0))
        gt="Unknown (any)"; crs_obj=None
        gfs=lo.get("geometryFields",[])
        if gfs:
            gt=gfs[0].get("type","Unknown (any)")
            cs=gfs[0].get("coordinateSystem") or {}
            auth=cs.get("authid")
            if auth:
                c,e,ok=crsmod.parse_crs_input(auth);crs_obj=c if ok else None
        layers.append(Layer(lo.get("name") or "layer",fields,[],gt,crs_obj))
    return layers

def _vector_layer_basename(output):
    base=os.path.basename(str(output).rstrip("/"))
    for ext in [".shp.zip",".geojsonl",".geojsons",".geojson",".json",".shp",".dbf"]:
        if base.lower().endswith(ext):return base[:-len(ext)]
    return os.path.splitext(base)[0] or base

def handler_convert_shortcut(call):
    import datasetio, vfs as _vfs
    input_path=call.parsed.values.get("input")
    if isinstance(input_path,list):input_path=input_path[0] if input_path else None
    if not _vfs.exists(str(input_path)):
        raise ParseError(f"ERROR 4: {input_path}: No such file or directory\n"+call.usage_appendix(),code=1)
    kind_driver=datasetio.identify(str(input_path))
    kind=kind_driver[1]
    if kind is None:
        raise ParseError(f"ERROR 4: `{input_path}' not recognized as being in a supported file format.\n"+call.usage_appendix(),code=1)
    # Create pseudo-call with node convert raster/vector (invoked path gdal convert raster) for usage/GDALG, but parse values are same object; node.args needed for handler functions (they access missing values with .get defaults)
    from cli import Call
    import spec as specmod
    child_node=specmod.get_node(("gdal","raster","convert") if kind=="raster" else ("gdal","vector","convert"))
    pcall=Call(call.parsed,child_node,("gdal","convert",kind))
    # In pseudo-call, algo_name is convert in errors after identification (examples show convert: Dataset exists)
    # Call class sets algo_name from node path last component = convert, good. Its usage_appendix will use raster convert node's usage line but replace canonical path with invoked gdal convert raster (?), our usage line method uses node.usage_line_for_invocation invoked path: node path is gdal raster convert, replacing prefix with gdal convert raster yields Usage: gdal convert raster ... as observed.
    if kind=="raster":
        return handler_raster_convert(pcall)
    else:
        return handler_vector_convert(pcall,pseudo_command_path=("gdal","convert","vector"))
