def handler_vsi_sync(call):
    src=call.parsed.values.get("source");dst=call.parsed.values.get("destination")
    strategy=call.parsed.values.get("strategy") or "timestamp"
    if not vfs.exists(str(src)):
        raise ParseError(f"ERROR 3: {src} does not exist\nERROR 3: sync: '{src}' does not exist or cannot be accessed\n",code=1)
    one_config_warning(call)
    # VSISync: sync source file/dir to destination. If source is dir, destination becomes dir containing contents (or nested if exists?). If strategy overwrite, always copy. Timestamp: copy if dst missing or src mtime > dst mtime.
    def should_copy(s,d):
        if not vfs.exists(str(d)):return True
        if strategy=="overwrite":return True
        if strategy=="ETag":
            return vfs.read_binary(str(s))!=vfs.read_binary(str(d))
        # timestamp
        ss=_vfs_stat(str(s));ds=_vfs_stat(str(d))
        return (ss and ds and ss["mtime"]>ds["mtime"]) or False
    if not vfs.is_dir(str(src)):
        dest=str(dst)
        if vfs.is_dir(dest):dest=os.path.join(dest,os.path.basename(str(src)))
        if should_copy(src,dest):_vfs_copy_one(src,dest)
