    vfs.mkdir(dest_root)
    def walk(d,rel=""):
        for name in vfs.list_dir(d):
            full=os.path.join(str(d),name);r=os.path.join(rel,name) if rel else name
            dest=os.path.join(dest_root,r)
            if vfs.is_dir(full):
                vfs.mkdir(dest)
                if call.parsed.values.get("recursive") or True:walk(full,r)
            else:
                if should_copy(full,dest):_vfs_copy_one(full,dest)
    walk(str(src))
    call.progress();return 0
