# ---------------- VSI ----------------
def _vfs_stat(path):
    p=str(path)
    if vfs.is_mem_path(p):
        if p in vfs.MEMFS:
            return dict(name=os.path.basename(p.rstrip("/")),type="file",size=len(vfs.MEMFS[p]),mtime=0,mode=0o644)
        if vfs.is_dir(p):
            return dict(name=os.path.basename(p.rstrip("/")) or "/",type="directory",size=0,mtime=0,mode=0o755)
        return None
    if p.startswith("/vsizip/"):
        # File inside zip
        try:
            if vfs.is_dir(p):
                return dict(name=os.path.basename(p.rstrip("/")),type="directory",size=0,mtime=0,mode=0o755)
            data=vfs.read_binary(p)
            return dict(name=os.path.basename(p),type="file",size=len(data),mtime=0,mode=0o644)
        except Exception:return None
    try:
        st=os.stat(p)
    except Exception:
        return None
    typ="directory" if stat_module_isdir(st.st_mode) else "file"
    return dict(name=os.path.basename(p.rstrip("/")),type=typ,size=st.st_size,mtime=st.st_mtime,mode=stat_module_mode(st.st_mode))

def stat_module_isdir(m):
    import stat as _st;return _st.S_ISDIR(m)
def stat_module_mode(m):return m

def _perm_string(st):
    import stat as _st
    mode=st["mode"] if isinstance(st,dict) else st
    # mode here may be permission bits (0o644) or full stat mode. Construct string
    is_dir=st["type"]=="directory" if isinstance(st,dict) else False
    perm=mode & 0o777
    chars="d" if is_dir else "-"
    for shift,chars_ in [(6,"rwx"),(3,"rwx"),(0,"rwx")]:
        bits=(perm>>shift)&0b111
        chars+=chars_[0] if bits&4 else "-"
        chars+=chars_[1] if bits&2 else "-"
        chars+=chars_[2] if bits&1 else "-"
    return chars

def handler_vsi_list(call):
    path=call.parsed.values.get("filename")
    if isinstance(path,list):path=path[0]
    st=_vfs_stat(str(path))
    if st is None:
        raise ParseError(f"ERROR 3: list: '{path}' does not exist or cannot be accessed\n",code=1)
    one_config_warning(call)
    fmt=(call.parsed.values.get("output-format") or "text")
