    def list_dir_entries(dirpath, rel_prefix="", current_depth=1):
        names=vfs.list_dir(dirpath)
        result=[]
        for name in names:
            full=os.path.join(str(dirpath),name)
            rel=(rel_prefix+"/"+name) if rel_prefix else name
            est=_vfs_stat(full)
            is_dir=est and est["type"]=="directory"
            if recursive:
                if depth is not None:
                    # Observed depth=1: only top-level regular files (no directory names, no nested)
                    if is_dir:
                        if current_depth < int(depth):
                            result.append((rel,full,est))
                            result.extend(list_dir_entries(full,rel,current_depth+1))
                        else:
                            # At max depth, skip dirs in depth=1 case; for depth>1 probably include dir names but don't descend. Approximation: if current_depth==depth and depth==1 skip, else include.
                            if int(depth)>1: result.append((rel,full,est))
                    else:
                        result.append((rel,full,est))
                else:
                    result.append((rel,full,est))
