            display_entries.append((display,full,est))
    else:
        raw_entries=list_dir_entries(str(path))
        display_entries=[]
        for rel,full,est in raw_entries:
            display=(str(path).rstrip("/")+"/"+rel) if abs_path else rel
            display_entries.append((display,full,est))
    if str(fmt).lower()=="json":
        if tree and st["type"]=="directory":
            # Build nested structure based on raw entries
            def build_tree(dirpath,depth_left=None):
                names=vfs.list_dir(dirpath)
                arr=[]
                for name in names:
                    full=os.path.join(str(dirpath),name);est=_vfs_stat(full)
                    if est and est["type"]=="directory":
                        if recursive:
                            arr.append({"name":name,"entries":build_tree(full)})
