                return arr
            arr=build_tree(str(path))
            sys.stdout.write(json.dumps(arr,indent=2));return 0
        if long_listing:
            arr=[_long_json_entry(display,est) for display,full,est in display_entries]
            sys.stdout.write(json.dumps(arr,indent=2));return 0
        arr=[display for display,_,_ in display_entries]
        sys.stdout.write(json.dumps(arr,indent=2));return 0
    # text
    for display,full,est in display_entries:
