    return 0

def _long_json_entry(name,est):
    dt=datetime.datetime.utcfromtimestamp(est["mtime"]) if est["mtime"] else datetime.datetime(1970,1,1)
    return {"name":name,"type":est["type"],"size":est["size"],"last_modification_date":dt.strftime("%Y-%m-%d %H:%M:%SZ"),"permissions":_perm_string(est)}

def _vfs_copy_one(src,dst):
    data=vfs.read_binary(str(src))
    vfs.write_binary(str(dst),data)
    return len(data)

def _vsi_copy(call,src,dst,action="copy"):
    if not vfs.exists(str(src)):
        # msg variants
        if action=="copy":
            raise ParseError(f"ERROR 3: copy: '{src}' cannot be accessed.\n",code=1)
        elif action=="move":
            raise ParseError(f"ERROR 3: move: '{src}' does not exist or cannot be accessed\n",code=1)
    if vfs.is_dir(str(src)):
        if action=="copy" and not call.parsed.values.get("recursive"):
            raise ParseError(f"ERROR 3: copy: {src} is a directory. Use -r/--recursive option\n",code=1)
        # Recursive copy/move directory
        # If destination exists as a dir, GDAL VSICopyDir may create dst/basename(src) (observed via sync?) The basic copy recursive -r srcDir to dest (non exist) should create dest with contents of src.
        dest_root=str(dst)
        if vfs.is_dir(dest_root):
            dest_root=os.path.join(dest_root,os.path.basename(str(src).rstrip("/")))
        vfs.mkdir(dest_root)
        # Walk recursively
        all_files=[]
        def walk(d,rel=""):
            for name in vfs.list_dir(d):
                full=os.path.join(d,name);r=os.path.join(rel,name) if rel else name
                if vfs.is_dir(full):
                    vfs.mkdir(os.path.join(dest_root,r));walk(full,r)
                else:
                    all_files.append((full,os.path.join(dest_root,r)))
        walk(str(src))
        for f,dest in all_files:
            vfs.write_binary(dest,vfs.read_binary(f))
            if action=="move":
                try:vfs.remove(f)
                except:pass
        if action=="move":
            # Remove empty dirs bottom-up roughly
            try:
                for root,dirs,files in os.walk(str(src),topdown=False):
                    try:os.rmdir(root)
                    except:pass
            except:pass
        call.progress();return 0
    # File copy
    dest=str(dst)
    # If dest = source same resolved file in copy to a dir case, original errors 0 bytes
    if vfs.is_dir(dest):
        dest_file=os.path.join(dest,os.path.basename(str(src)))
        if os.path.abspath(dest_file)==os.path.abspath(str(src)):
            sz=_vfs_stat(str(src))["size"]
            raise ParseError(f"ERROR 3: Copying of {src} to {dest_file} failed: 0 bytes were copied whereas {sz} were expected\n",code=1)
        dest=dest_file
    _vfs_copy_one(src,dest)
    if action=="move":
        try:vfs.remove(str(src))
        except:pass
    call.progress();return 0

def handler_vsi_copy(call):
    src=call.parsed.values.get("source");dst=call.parsed.values.get("destination")
    one_config_warning(call)
    try:
        return _vsi_copy(call,src,dst,"copy")
    except ParseError:raise
    except Exception as e:
        if call.parsed.values.get("skip-errors"):return 0
        raise

def handler_vsi_move(call):
    src=call.parsed.values.get("source");dst=call.parsed.values.get("destination")
    one_config_warning(call)
    # Move a dir: rename if same filesystem
    if vfs.exists(str(src)) and not vfs.is_dir(str(src)):
        # attempt direct rename for local
        if not vfs.is_mem_path(str(src)) and not str(dst).startswith("/vsi"):
            try:
                if vfs.is_dir(str(dst)):
                    dest_file=os.path.join(str(dst),os.path.basename(str(src)))
                else:dest_file=str(dst)
                os.rename(str(src),dest_file);call.progress();return 0
            except Exception:pass
    return _vsi_copy(call,src,dst,"move")

def handler_vsi_delete(call):
    path=call.parsed.values.get("filename")
    if isinstance(path,list):path=path[0]
    if not vfs.exists(str(path)):
        raise ParseError(f"ERROR 3: delete: '{path}' does not exist or cannot be accessed\n",code=1)
    one_config_warning(call)
    recursive=bool(call.parsed.values.get("recursive"))
    if vfs.is_dir(str(path)):
        if not recursive:
            raise ParseError(f"ERROR 3: delete: Cannot delete {path}\n",code=1)
        # delete recursively
        if vfs.is_mem_path(str(path)):
            vfs.remove(str(path))
        else:
            import shutil;shutil.rmtree(str(path))
        return 0
    vfs.remove(str(path));return 0

def handler_vsi_sync(call):
    src=call.parsed.values.get("source");dst=call.parsed.values.get("destination")
    strategy=call.parsed.values.get("strategy") or "timestamp"
    if not vfs.exists(str(src)):
        raise ParseError(f"ERROR 3: {src} does not exist\nERROR 3: sync: '{src}' does not exist or cannot be accessed\n",code=1)
    one_config_warning(call)
    # VSISync: sync source file/dir to destination. If source is dir, destination becomes dir containing contents (or nested if exists?). If strategy overwrite, always copy. Timestamp: copy if dst missing or src mtime > dst mtime.
    def should_copy(s,d):
        if not vfs.exists(str(d)):return True
        if strategy=="overwrite":return True
        if strategy=="ETag":
            return vfs.read_binary(str(s))!=vfs.read_binary(str(d))
        # timestamp
        ss=_vfs_stat(str(s));ds=_vfs_stat(str(d))
        return (ss and ds and ss["mtime"]>ds["mtime"]) or False
    if not vfs.is_dir(str(src)):
        dest=str(dst)
        if vfs.is_dir(dest):dest=os.path.join(dest,os.path.basename(str(src)))
        if should_copy(src,dest):_vfs_copy_one(src,dest)
        call.progress();return 0
    # Directory
    dest_root=str(dst)
    # VSISync semantics: if destination doesn't end with /, docs weird. Original sync /tmp/vsitest -> exist /tmp/vsitest2 created a nested vsitest dir at some point due prior copy; not reliable. Common behavior: target dir is synchronized to contain *contents* of source (source with trailing slash or not?) We'll do contents.
    vfs.mkdir(dest_root)
    def walk(d,rel=""):
        for name in vfs.list_dir(d):
            full=os.path.join(str(d),name);r=os.path.join(rel,name) if rel else name
            dest=os.path.join(dest_root,r)
            if vfs.is_dir(full):
                vfs.mkdir(dest)
                if call.parsed.values.get("recursive") or True:walk(full,r)
            else:
                if should_copy(full,dest):_vfs_copy_one(full,dest)
    walk(str(src))
    call.progress();return 0
