def _expr_fields(node,fields):
    if not isinstance(node,tuple):return
    if node and node[0]=="field":fields.append(node[1]);return
    for x in node[1:]:
        if isinstance(x,tuple):_expr_fields(x,fields)
        elif isinstance(x,list):
            for y in x:
                if isinstance(y,tuple):_expr_fields(y,fields)

def _has_aggregate(node):
    if isinstance(node,tuple):
        if node and node[0]=="func" and node[1] in aggregate_funcs:return True
        return any(_has_aggregate(x) for x in node[1:])
    if isinstance(node,list):return any(_has_aggregate(x) for x in node)
    return False

def _truth(v):
    if v is None:return None
    if isinstance(v,bool):return v
    if isinstance(v,(int,float)):return v!=0
    if isinstance(v,str):return v.lower() not in ("","0","false")
    return bool(v)

def evaluate(node, feature, layer, aggregate_context=None):
    kind=node[0]
    if kind=="lit":return node[1]
    if kind=="field":
        name=node[1]
        if name.upper()=="FID":return feature.fid if feature else None
        if name.upper() in ("OGR_GEOMETRY","_OGR_GEOMETRY_"):
            # As a string value in OGR SQL, geometry field returns WKT type name only when cast to string - return a special object
            g=feature.geometry if feature else None
            return geommod.geom_type_name(g,include_z=False).upper() if g else None
        if name.upper()=="OGR_GEOM_WKT":
            return geommod.geom_to_wkt(feature.geometry) if feature and feature.geometry else None
        if name.upper()=="OGR_GEOM_AREA":
            return geommod.geometry_area(feature.geometry) if feature else None
        # find field case-insensitive
        for k,v in (feature.properties.items() if feature else []):
            if k.lower()==name.lower():return v
        # field exists but unset
        if layer and layer.get_field(name):return None
        raise VectorSQLError(f'ERROR 1: "{name}" not recognised as an available field.\n')
    if kind=="not":
        v=_truth(evaluate(node[1],feature,layer,aggregate_context));return None if v is None else (not v)
    if kind=="neg":
        v=evaluate(node[1],feature,layer,aggregate_context);return -v if isinstance(v,(int,float)) else None
    if kind=="isnull":
        v=evaluate(node[1],feature,layer,aggregate_context);res=v is None;return (not res) if node[2] else res
    if kind=="in":
        v=evaluate(node[1],feature,layer,aggregate_context)
        vals=[evaluate(x,feature,layer,aggregate_context) for x in node[2]]
        return v in vals
    if kind=="between":
        v=evaluate(node[1],feature,layer,aggregate_context);lo=evaluate(node[2],feature,layer,aggregate_context);hi=evaluate(node[3],feature,layer,aggregate_context)
        try:return lo<=v<=hi
        except:return False
    if kind=="like":
        v=evaluate(node[1],feature,layer,aggregate_context);pat=evaluate(node[2],feature,layer,aggregate_context)
        if v is None or pat is None:return None
        pat_str=str(pat);regex="^"
        esc_char=None
        if node[3] is not None:
            ev=evaluate(node[3],feature,layer,aggregate_context);esc_char=str(ev)[0] if ev else None
        i=0
        while i<len(pat_str):
            c=pat_str[i]
            if esc_char and c==esc_char and i+1<len(pat_str):i+=1;regex+=re.escape(pat_str[i])
            elif c=='%':regex+='.*'
            elif c=='_':regex+='.'
            else:regex+=re.escape(c)
            i+=1
        regex+="$"
        return re.match(regex,str(v),flags=0) is not None
    if kind=="case":
        for cond,val in node[1]:
            if _truth(evaluate(cond,feature,layer,aggregate_context)):return evaluate(val,feature,layer,aggregate_context)
        return evaluate(node[2],feature,layer,aggregate_context) if node[2] else None
    if kind=="cast":
        return _cast_sql(evaluate(node[1],feature,layer,aggregate_context),node[2])
    if kind=="func":
        return _eval_func(node,feature,layer,aggregate_context)
    if kind=="bin":
        op=node[1]
        if op=="AND":
            a=_truth(evaluate(node[2],feature,layer,aggregate_context));b=_truth(evaluate(node[3],feature,layer,aggregate_context))
            if a is False or b is False:return False
            if a is None or b is None:return None
            return True
        if op=="OR":
            a=_truth(evaluate(node[2],feature,layer,aggregate_context));b=_truth(evaluate(node[3],feature,layer,aggregate_context))
            if a is True or b is True:return True
            if a is None or b is None:return None
            return False
        a=evaluate(node[2],feature,layer,aggregate_context);b=evaluate(node[3],feature,layer,aggregate_context)
        if op=="||":
            return ("" if a is None else str(a))+("" if b is None else str(b))
        if a is None or b is None:
            if op in ("=","!=","<>","<","<=",">",">=","+","-","*","/","%"):return None
        try:
            if op=="+":return a+b
            if op=="-":return a-b
            if op=="*":return a*b
            if op=="/":return a/b if b!=0 else None
            if op=="%":return a%b if b!=0 else None
            if op=="=":return a==b
            if op in ("!=","<>"):return a!=b
            if op=="<":return a<b
            if op=="<=":return a<=b
            if op==">":return a>b
            if op==">=":return a>=b
        except Exception:
            return None
    if kind=="star":return None
    return None

def _cast_sql(v,type_name):
    if v is None:return None
    t=type_name.upper()
    try:
        if t in ("INTEGER","INT","BIGINT"):return int(float(v)) if isinstance(v,str) else int(v)
        if t in ("REAL","FLOAT","DOUBLE","NUMERIC"):return float(v)
        if t in ("CHARACTER","VARCHAR","TEXT","STRING"):return str(v)
        if t=="DATE":return str(v)
    except:return None
    return v

def _eval_func(node,feature,layer,ctx):
    name=node[1];args=node[2]
    if name in aggregate_funcs:
        if ctx is None:
            raise VectorSQLError(f"ERROR 1: Aggregate function {name} used in invalid context\n")
        features=ctx.get("features",[])
        if name=="COUNT":
            if args and args[0]==("star",):return len(features)
            vals=[evaluate(args[0],f,layer,None) for f in features] if args else []
            return sum(1 for v in vals if v is not None)
        vals=[]
        if args:
            for f in features:
                v=evaluate(args[0],f,layer,None)
                if v is not None:vals.append(v)
        if not vals:return None
        if name=="SUM":return sum(vals)
        if name=="AVG":return sum(vals)/len(vals)
        if name=="MIN":return min(vals)
        if name=="MAX":return max(vals)
    vals=[evaluate(a,feature,layer,ctx) for a in args]
    try:
        if name in ("LOWER",):return str(vals[0]).lower() if vals[0] is not None else None
        if name in ("UPPER",):return str(vals[0]).upper() if vals[0] is not None else None
        if name in ("LENGTH","LEN"):return len(str(vals[0])) if vals[0] is not None else None
        if name in ("SUBSTR","SUBSTRING"):
            s=str(vals[0]);start=int(vals[1])-1 if len(vals)>1 else 0
            if start<0:start=max(0,len(s)+start)
            length=int(vals[2]) if len(vals)>2 else None
            return s[start:start+length] if length is not None else s[start:]
        if name=="ABS":return abs(vals[0])
        if name=="ROUND":
            digits=int(vals[1]) if len(vals)>1 else 0;return round(float(vals[0]),digits)
        if name=="COALESCE":
            for v in vals:
                if v is not None:return v
            return None
        if name=="NULLIF":return None if vals[0]==vals[1] else vals[0]
        if name in ("CONCAT",):return "".join(str(v) for v in vals if v is not None)
        if name in ("ST_ASTEXT","ST_AsText".upper()):
            return geommod.geom_to_wkt(feature.geometry) if feature else None
        if name=="ST_AREA":return geommod.geometry_area(feature.geometry) if feature else None
        if name=="ST_LENGTH":return geommod.geometry_length(feature.geometry) if feature else None
        if name=="AREA":return geommod.geometry_area(feature.geometry) if feature else None
    except Exception:
        return None
    raise VectorSQLError(f"ERROR 6: '{name}' is a unknown builtin function\n")

def parse_where(where):
    if where is None:return None
    toks=tokenize(str(where))
    p=Parser(toks,str(where))
    expr=p.parse_expression()
    if p.peek().kind!="eof":p.error()
    return expr

def _validate_fields(node,layer):
    names=[];_expr_fields(node,names)
    specials={"FID","OGR_GEOMETRY","_OGR_GEOMETRY_","OGR_GEOM_WKT","OGR_GEOM_AREA"}
    for n in names:
        if n.upper() in specials:continue
        if layer and not layer.get_field(n):
            raise VectorSQLError(f'ERROR 1: "{n}" not recognised as an available field.\n')

def evaluate_where(where,feature,layer):
    expr=parse_where(where) if isinstance(where,str) else where
    _validate_fields(expr,layer)
    return _truth(evaluate(expr,feature,layer))

def apply_where_dataset(ds,ds_where_text,layer_filter=None):
    """returns copy dataset with filtered layers"""
    where_text=ds_where_text
    if isinstance(where_text,str) and where_text.startswith("@"):
        import vfs
        where_text=vfs.read_binary(where_text[1:]).decode("utf-8")
    expr=parse_where(where_text)
    out=ds.copy()
    # validate all selected layers upfront (raises first line only)
    for layer in out.layers:
        if layer_filter and layer.name not in layer_filter:continue
        _validate_fields(expr,layer)
    for layer in out.layers:
        if layer_filter and layer.name not in layer_filter:continue
        filtered=[]
        for f in layer.features:
            if _truth(evaluate(expr,f,layer)):filtered.append(f)
        layer.features=filtered
    return out

def apply_where(ds,where,layer_filter=None):
    # Used by vector info: on error, caller adds SetAttributeFilter failed line if because apply_where wraps? We'll raise with both lines in apply_where if validation fails.
    try:
        return apply_where_dataset(ds,where,layer_filter)
    except VectorSQLError as e:
        msg=str(e)
        # preserve first error plus add in info caller separately? To match original info output, re-raise with just first line and let handler decide. We will tag.
        raise

def parse_select(sql):
    toks=tokenize(sql);p=Parser(toks,sql)
    p.expect_kw("SELECT")
    distinct=p.accept_kw("DISTINCT")
    items=[]
    while True:
        if p.accept_op("*"):
            items.append(dict(expr=("star",),alias=None))
        else:
            expr=p.parse_expression()
            alias=None
            if p.accept_kw("AS"):
                t=p.next();alias=t.text
            else:
                t=p.peek()
                if t.kind in ("ident","qident") and t.text.upper() not in ("FROM",):
                    alias=p.next().text
            items.append(dict(expr=expr,alias=alias))
        if p.accept_op(","):continue
        break
    p.expect_kw("FROM")
    t=p.next();layer_name=t.text
    # optional alias (ignore)
    if p.peek().kind=="ident" and p.peek().text.upper() not in ("WHERE","ORDER","GROUP"):p.next()
    where=None;order=[];group_by=[]
    if p.accept_kw("WHERE"):where=p.parse_expression()
    if p.accept_kw("GROUP"):
        p.expect_kw("BY")
        while True:
            group_by.append(p.parse_expression())
            if p.accept_op(","):continue
            break
    if p.accept_kw("ORDER"):
        p.expect_kw("BY")
        while True:
            e=p.parse_expression();desc=False
            if p.accept_kw("DESC"):desc=True
            elif p.accept_kw("ASC"):desc=False
            order.append((e,desc))
            if p.accept_op(","):continue
            break
    limit=None;offset=None
    if p.accept_kw("LIMIT"):
        tt=p.next();limit=int(float(tt.text)) if tt.kind=="number" else None
    if p.accept_kw("OFFSET"):
        tt=p.next();offset=int(float(tt.text)) if tt.kind=="number" else None
    if p.peek().kind!="eof" and not (p.peek().kind=="op" and p.peek().text==";"):
        p.error()
    return dict(distinct=distinct,items=items,layer=layer_name,where=where,order=order,group_by=group_by,limit=limit,offset=offset)

def apply_sql(ds,sql,dialect=None):
    # may be @filename
    sql_text=str(sql)
    if sql_text.startswith("@"):
        import vfs;sql_text=vfs.read_binary(sql_text[1:]).decode("utf-8")
    # Split statements by semicolon not in strings - sql command may pass multiple --sql args separately in handler. One string may include ;
    stmts=[s.strip() for s in sql_text.strip().split(";") if s.strip()]
    if not stmts:return ds
    if len(stmts)>1:
        result=ds
        for st in stmts:result=apply_sql(result,st,dialect)
        return result
    stmt=stmts[0]
    up=stmt.lstrip().upper()
    if up.startswith("ALTER TABLE"):
        return _apply_alter(ds,stmt)
    if up.startswith("UPDATE") or up.startswith("DELETE") or up.startswith("INSERT"):
        # Raise parse-like error compatible with default no update mode; handler where update requested calls mutation separately
        first_word=stmt.strip().split()[0]
        raise VectorSQLError(f"ERROR 1: SQL Expression Parsing Error: syntax error, unexpected identifier, expecting SELECT or '('. Occurred around :\n{stmt}\n^\nERROR 1: sql: Execution of the SQL statement '{stmt}' failed..\nPerhaps you need to specify the 'update' argument?\n")
    if not up.startswith("SELECT"):
        raise VectorSQLError(f"ERROR 1: SQL Expression Parsing Error: syntax error, unexpected identifier, expecting SELECT or '('. Occurred around :\n{stmt}\n^\n")
    sel=parse_select(stmt)
    return _execute_select(ds,sel)

def _layer_from_name(ds,name):
    for layer in ds.layers:
        if layer.name.lower()==str(name).lower():return layer
    raise VectorSQLError(f'ERROR 1: {"SQL Expression Parsing Error: "}Table {name} not recognised.\n' if False else f'ERROR 1: Table {name} not recognised.\n')

def _execute_select(ds,sel):
    src=_layer_from_name(ds,sel["layer"])
    # fields validation for all expressions
    if sel["where"]:_validate_fields(sel["where"],src)
    for item in sel["items"]:
        if item["expr"]!=("star",):_validate_fields(item["expr"],src)
    for e,d in sel["order"]: _validate_fields(e,src)
    rows=[]
    for f in src.features:
        if sel["where"] is None or _truth(evaluate(sel["where"],f,src)):
            rows.append(f)
    has_agg=any(_has_aggregate(it["expr"]) for it in sel["items"]) or bool(sel["group_by"])
    out_features=[];out_fields=[]
    geom_field_name=""
    is_star=any(it["expr"]==("star",) for it in sel["items"])
    if is_star:
        geom_field_name="_ogr_geometry_"
    # Build result features
    if has_agg and not sel["group_by"]:
        ctx={"features":rows}
        feature=Feature(0,{},None)
        props={}
        for item in sel["items"]:
            if item["expr"]==("star",):continue
            val=evaluate(item["expr"],rows[0] if rows else Feature(0,{},None),src,ctx)
            fname=_item_name(item,src)
            props[fname]=val
        feature.properties=props
        out_features=[feature]
        out_fields=_infer_output_fields(sel["items"],src,out_features)
        layer=Layer(src.name,out_fields,out_features,"None",None,geom_field_name=geom_field_name)
        out=VectorDataset(ds.driver_short,ds.driver_long,ds.description,[layer])
        out._sql_mode=is_star
        return out
    if sel["group_by"]:
        # simple grouping by values of group expressions (first feature per group as prototype)
        groups={};order=[]
        for f in rows:
            key=tuple(evaluate(e,f,src) for e in sel["group_by"])
            if key not in groups:groups[key]=[];order.append(key)
            groups[key].append(f)
        for idx,key in enumerate(order):
            grp=groups[key];proto=grp[0]
            props={}
            for item in sel["items"]:
                if item["expr"]==("star",):
                    for fld in src.fields:
                        if fld.name in proto.properties:props[fld.name]=proto.properties[fld.name]
                    continue
                val=evaluate(item["expr"],proto,src,{"features":grp})
                props[_item_name(item,src)]=val
            out_features.append(Feature(idx,props,copy.deepcopy(proto.geometry)))
        out_fields=_infer_output_fields(sel["items"],src,out_features)
        layer=Layer(src.name,out_fields,out_features,src.geom_type,src.crs,geom_field_name=geom_field_name)
        out=VectorDataset(ds.driver_short,ds.driver_long,ds.description,[layer]);out._sql_mode=is_star;return out
    for idx,f in enumerate(rows):
        props={}
        for item in sel["items"]:
            if item["expr"]==("star",):
                for fld in src.fields:
                    if fld.name in f.properties:props[fld.name]=f.properties[fld.name]
                continue
            val=evaluate(item["expr"],f,src)
            props[_item_name(item,src)]=val
        nf=Feature(f.fid,props,copy.deepcopy(f.geometry))
        out_features.append(nf)
    # Order by (evaluate before field removal? Order can refer original fields not in select, need evaluate on original rows matched)
    if sel["order"]:
        paired=list(zip(rows,out_features))
        # sort multiple keys stable reverse application
        for expr,desc in reversed(sel["order"]):
            paired.sort(key=lambda pair:_sort_key(evaluate(expr,pair[0],src)),reverse=desc)
        out_features=[p[1] for p in paired]
        # Renumber fids? OGR SQL result stream might preserve source FID (feature dump showed fid0 for filtered first even if source fid0). For order desc, feature IDs in result likely sequential result index or source? Need test later. Keep source fid.
    if sel["distinct"]:
        seen=[];uniq=[]
        for f in out_features:
            key=(tuple(f.properties.items()),str(f.geometry))
            if key not in seen:seen.append(key);uniq.append(f)
        out_features=uniq
    if sel["offset"]:out_features=out_features[int(sel["offset"]):]
    if sel["limit"] is not None:out_features=out_features[:int(sel["limit"])]
    out_fields=_infer_output_fields(sel["items"],src,out_features)
    layer=Layer(src.name,out_fields,out_features,src.geom_type,src.crs,geom_field_name=geom_field_name)
    # If only aggregate could have set above. If no geometry columns but org geometry exists, geometry type remains from source (as info)
    out=VectorDataset(ds.driver_short,ds.driver_long,ds.description,[layer])
    out._sql_mode=is_star
    return out

def _sort_key(v):
    if v is None:return (0,0)
    if isinstance(v,(int,float)):return (1,float(v))
    return (2,str(v))

def _item_name(item,src):
    if item["alias"]:return item["alias"]
    e=item["expr"]
    if e[0]=="field":return src.get_field(e[1]).name if src.get_field(e[1]) else e[1]
    if e[0]=="func":return e[1].lower() if e[1]!="COUNT" else "count"
    return "expr"

def _infer_output_fields(items,src,out_features):
    fields=[]
    # For star, copy src fields
    for item in items:
        if item["expr"]==("star",):
            fields.extend([f.copy() for f in src.fields]);continue
        alias=_item_name(item,src)
        if item["expr"][0]=="field" and not item["alias"]:
            srcf=src.get_field(item["expr"][1])
            if srcf:fields.append(srcf.copy());continue
        if item["expr"][0]=="field" and item["alias"]:
            srcf=src.get_field(item["expr"][1])
            if srcf:
