        else:
            expr=p.parse_expression()
            alias=None
            if p.accept_kw("AS"):
                t=p.next();alias=t.text
            else:
                t=p.peek()
                if t.kind in ("ident","qident") and t.text.upper() not in ("FROM",):
                    alias=p.next().text
            items.append(dict(expr=expr,alias=alias))
        if p.accept_op(","):continue
        break
    p.expect_kw("FROM")
    t=p.next();layer_name=t.text
    # optional alias (ignore)
    if p.peek().kind=="ident" and p.peek().text.upper() not in ("WHERE","ORDER","GROUP"):p.next()
    where=None;order=[];group_by=[]
    if p.accept_kw("WHERE"):where=p.parse_expression()
    if p.accept_kw("GROUP"):
        p.expect_kw("BY")
        while True:
            group_by.append(p.parse_expression())
            if p.accept_op(","):continue
            break
    if p.accept_kw("ORDER"):
        p.expect_kw("BY")
        while True:
            e=p.parse_expression();desc=False
            if p.accept_kw("DESC"):desc=True
            elif p.accept_kw("ASC"):desc=False
            order.append((e,desc))
            if p.accept_op(","):continue
            break
