    if p.accept_kw("LIMIT"):
        tt=p.next();limit=int(float(tt.text)) if tt.kind=="number" else None
    if p.accept_kw("OFFSET"):
        tt=p.next();offset=int(float(tt.text)) if tt.kind=="number" else None
    if p.peek().kind!="eof" and not (p.peek().kind=="op" and p.peek().text==";"):
        p.error()
    return dict(distinct=distinct,items=items,layer=layer_name,where=where,order=order,group_by=group_by,limit=limit,offset=offset)

def apply_sql(ds,sql,dialect=None):
    # may be @filename
    sql_text=str(sql)
    if sql_text.startswith("@"):
        import vfs;sql_text=vfs.read_binary(sql_text[1:]).decode("utf-8")
    # Split statements by semicolon not in strings - sql command may pass multiple --sql args separately in handler. One string may include ;
    stmts=[s.strip() for s in sql_text.strip().split(";") if s.strip()]
    if not stmts:return ds
    if len(stmts)>1:
        result=ds
        for st in stmts:result=apply_sql(result,st,dialect)
        return result
    stmt=stmts[0]
    up=stmt.lstrip().upper()
    if up.startswith("ALTER TABLE"):
        return _apply_alter(ds,stmt)
    if up.startswith("UPDATE") or up.startswith("DELETE") or up.startswith("INSERT"):
        # Raise parse-like error compatible with default no update mode; handler where update requested calls mutation separately
        first_word=stmt.strip().split()[0]
        raise VectorSQLError(f"ERROR 1: SQL Expression Parsing Error: syntax error, unexpected identifier, expecting SELECT or '('. Occurred around :\n{stmt}\n^\nERROR 1: sql: Execution of the SQL statement '{stmt}' failed..\nPerhaps you need to specify the 'update' argument?\n")
    if not up.startswith("SELECT"):
        raise VectorSQLError(f"ERROR 1: SQL Expression Parsing Error: syntax error, unexpected identifier, expecting SELECT or '('. Occurred around :\n{stmt}\n^\n")
