        vals=[]
        for f in out_features:
            if alias in f.properties and f.properties[alias] is not None:vals.append(f.properties[alias])
        if vals and all(isinstance(v,int) and not isinstance(v,bool) for v in vals):
            typ="Integer64" if item["expr"][0]=="func" and item["expr"][1] in ("SUM",) or any(abs(v)>2147483647 for v in vals) else "Integer"
            if item["expr"][0]=="func" and item["expr"][1]=="COUNT":typ="Integer"
            fields.append(Field(alias,typ))
        elif vals and all(isinstance(v,(int,float)) for v in vals):fields.append(Field(alias,"Real"))
        elif vals and all(isinstance(v,str) for v in vals):fields.append(Field(alias,"String"))
