    if v is None:return None
    t=new_field.type
    try:
        if t in ("Integer","Integer64"):return int(float(v)) if isinstance(v,str) else int(v)
        if t=="Real":return float(v)
        if t=="String":
            if isinstance(v,float):
                from gutil import fmt_real_text;return fmt_real_text(v)
            return str(v)
        if t in ("IntegerList","Integer64List"):return [int(float(x)) for x in v] if isinstance(v,list) else [int(float(v))]
        if t=="RealList":return [float(x) for x in v] if isinstance(v,list) else [float(v)]
        if t=="StringList":return [str(x) for x in v] if isinstance(v,list) else [str(v)]
    except Exception:
