def _promote_to_multi(g):
    t=g.get("type")
    if t=="Point":return {"type":"MultiPoint","coordinates":[g["coordinates"]]}
    if t in ("LineString","LinearRing"):return {"type":"MultiLineString","coordinates":[g["coordinates"]]}
    if t=="Polygon":return {"type":"MultiPolygon","coordinates":[g["coordinates"]]}
    return g

def _explode_single(g):
    t=g.get("type")
    if t=="MultiPoint":return [{"type":"Point","coordinates":c} for c in g["coordinates"]]
    if t=="MultiLineString":return [{"type":"LineString","coordinates":c} for c in g["coordinates"]]
    if t=="MultiPolygon":return [{"type":"Polygon","coordinates":c} for c in g["coordinates"]]
    if t=="GeometryCollection":return list(g.get("geometries",[]))
    return [g]

def _curve_to_linear(g):
    # CircularString approximated as LineString through its points; CompoundCurve etc not in our data model
    if g.get("type")=="CircularString":return {"type":"LineString","coordinates":g["coordinates"]}
    return g

def _linear_to_curve(g):
    return g

def _force_dim(g,dim):
    nd={"XY":2,"XYZ":3,"XYM":3,"XYZM":4}.get(str(dim).upper(),2)
