def _combine_geoms(geoms,keep_nested=False):
    types=[g.get("type") for g in geoms]
    if all(t=="Point" for t in types):return {"type":"MultiPoint","coordinates":[g["coordinates"] for g in geoms]}
    if all(t in ("LineString","MultiLineString") for t in types):
