def handler_filter(call):
    def tr(ds):
        # bbox filter spatial: keep features whose envelope intersects bbox (or geometry intersects functionally). GDAL filter bbox is a spatial filter on geometry envelope? It sets spatial rect filter, test on geometry envelope intersecting.
        bbox=call.parsed.values.get("bbox") if call.parsed.has("bbox") else None
        where=call.parsed.values.get("where")
        for layer in ds.layers:
            feats=layer.features
            if bbox:
                xmin,ymin,xmax,ymax=[float(x) for x in bbox]
                new=[]
                for f in feats:
                    b=geommod.bbox(f.geometry)
                    if b and not (b[2]<xmin or b[0]>xmax or b[3]<ymin or b[1]>ymax):new.append(f)
                feats=new
            if where:
                expr=vectorsql.parse_where(where[1:] if where.startswith("@") else where)
                # @filename handled in info apply_where but here parse raw filename content
                if where.startswith("@"):
                    import vfs;expr=vectorsql.parse_where(vfs.read_binary(where[1:]).decode())
                vectorsql._validate_fields(expr,layer)
                feats=[f for f in feats if vectorsql._truth(vectorsql.evaluate(expr,f,layer))]
            layer.features=feats
            # update extent: stored extent should be cleared/based on features; if --update-extent, original updates layer extent metadata - our model computes dynamically except shape header extent stored. Clear stored extent if filtered and update-extent or spatial filter with shape? When writing shape, header extent will be from geometry points in writer, not stored.
            if bbox or where:
                layer.stored_extent=None
        return ds
    # Parse where errors should be raised before output creation: run_vector opens input then validates output before transform; if where invalid, error likely during read step setup before output. This transform runs after output validation but before creation - acceptable.
    return run_vector(call,tr)

def handler_select(call):
    def tr(ds):
        fields_arg=call.parsed.values.get("fields") or []
        # Fields can be packed comma separated by parser because string_list packed_values_allowed true (spec)
        selected=[]
        for val in fields_arg:
            # Values may come as strings separated by comma already split by parser if packed
            selected.append(str(val))
        exclude=bool(call.parsed.values.get("exclude"))
        ignore=bool(call.parsed.values.get("ignore-missing-fields"))
        for layer in ds.layers:
            # validate
            chosen=[]
            if exclude:
                excluded=[]
                for namev in selected:
                    fld=layer.get_field(namev)
                    if not fld and not ignore:
                        raise ParseError(f"ERROR 1: select: Field '{namev}' not found\n",code=1)
                    if fld:excluded.append(fld.name)
                chosen=[f for f in layer.fields if f.name not in excluded]
            else:
                for namev in selected:
                    fld=layer.get_field(namev)
                    if not fld:
                        if ignore:continue
                        raise ParseError(f"ERROR 1: select: Field '{namev}' not found\n",code=1)
                    chosen.append(fld)
            chosen_names=[f.name for f in chosen]
            for f in layer.features:
                f.properties={k:v for k,v in f.properties.items() if k in chosen_names}
            layer.fields=chosen
        return ds
    return run_vector(call,tr)

def handler_edit(call):
    def tr(ds):
        # edit options can be combined
        if call.parsed.has("geometry-type"):
            gt=_normalize_geom_type(call.parsed.values.get("geometry-type"))
            if gt is None:
                call.parse_error(f"{call.algo_name}: Invalid geometry type '{call.parsed.values.get('geometry-type')}'")
            for layer in ds.layers:layer.geom_type=gt
        if call.parsed.has("crs"):
            c,e,ok=crsmod.parse_crs_input(call.parsed.values.get("crs"))
            if ok:
                for l in ds.layers:l.crs=c
        for k,v in parse_kv_options(call.parsed.values.get("metadata") or []):
            ds.metadata.setdefault("",{})[k]=v
        for k in call.parsed.values.get("unset-metadata") or []:
            ds.metadata.get("",{}).pop(k,None)
        for k,v in parse_kv_options(call.parsed.values.get("layer-metadata") or []):
            for l in ds.layers:l.metadata[k]=v
        for k in call.parsed.values.get("unset-layer-metadata") or []:
            for l in ds.layers:l.metadata.pop(k,None)
        if call.parsed.values.get("unset-fid"):
            for l in ds.layers:
                l.fid_column=None
        return ds
    return run_vector(call,tr)

def handler_sql(call):
    sqls=call.parsed.values.get("sql") or []
    output=call.parsed.values.get("output")
    if isinstance(output,list):output=output[0] if output else None
    in_ds=open_vector(call)
    dialect=call.parsed.values.get("dialect")
    # Mutating statements with update flag
    is_update=bool(call.parsed.values.get("update"))
    # Statement processing
    current=in_ds.copy()
    output_layers=[]
    result_ds=None
    for sql_text in sqls:
        txt=str(sql_text)
        if txt.startswith("@"):
            import vfs;txt=vfs.read_binary(txt[1:]).decode()
        up=txt.lstrip().upper()
        if up.startswith("SELECT"):
            out=vectorsql.apply_sql(current,txt,dialect=dialect)
            output_layers.extend(out.layers)
            result_ds=out
        elif up.startswith("ALTER"):
            current=vectorsql.apply_sql(current,txt,dialect=dialect)
            result_ds=current
        elif up.startswith(("UPDATE","DELETE","INSERT","CREATE","DROP")):
            if not is_update:
                # apply_sql will raise expected parse error
                vectorsql.apply_sql(current,txt,dialect=dialect)
            else:
                current=_apply_mutating_sql(current,txt)
                result_ds=current
        else:
            vectorsql.apply_sql(current,txt,dialect=dialect)
    if output is None:
        if output_layers and not is_update:
            # Each SELECT returned results ignored with warning per statement unless quiet
            if not call.parsed.values.get("quiet"):
                for sql_text in sqls:
                    txt=str(sql_text)
                    if txt.lstrip().upper().startswith("SELECT"):
                        sys.stderr.write(f"Warning 1: sql: Execution of the SQL statement '{txt}' returned a result set. It will be ignored. You may silence this warning with the 'quiet' argument.\n")
            one_config_warning(call)
            return 0
        # Mutating input in update mode: write back to input filename using driver guess from extension
        if is_update and result_ds is not None:
            inpath=call.parsed.values.get("input");inpath=inpath[0] if isinstance(inpath,list) else inpath
            from vectorio import write_vector_dataset
            write_vector_dataset(result_ds,str(inpath))
        one_config_warning(call)
        return 0
    # With output: if only ALTER etc and no SELECT, output is mutated current
    out_ds=result_ds if result_ds is not None else current
    if output_layers and len(sqls)>1:
        out_ds=VectorDataset(in_ds.driver_short,in_ds.driver_long,str(output),output_layers)
    # Output layer names list can rename
    olayers=call.parsed.values.get("output-layer") or []
    if olayers:
        if isinstance(olayers,str):olayers=[olayers]
        for layer,newname in zip(out_ds.layers,olayers):layer.name=newname
    fmt=call.parsed.values.get("output-format")
    driver=validate_output(call,output,fmt,"vector")
    if driver=="GDALG":
        one_config_warning(call);return gdalgmod.write_gdalg(call,output)
    config_warnings_for_operation(call,"read_write")
    creation_opts=parse_kv_options(call.parsed.values.get("creation-option") or []);layer_opts=parse_kv_options(call.parsed.values.get("layer-creation-option") or [])
    warn_creation_options(driver,creation_opts,layer_opts,call,kind="vector",output_path=output)
    prepare_output(call,output,driver)
    from vectorio import write_vector_dataset
    write_vector_dataset(out_ds,output,output_format=driver,creation_options=[f"{k}={v}" for k,v in creation_opts],layer_creation_options=[f"{k}={v}" for k,v in layer_opts],output_layer=(olayers[0] if olayers else None))
    call.progress()
    return 0

def _apply_mutating_sql(ds,sql):
    # Very basic UPDATE/DELETE/INSERT for update mode
    txt=sql.strip()
    m=re.match(r'(?is)UPDATE\s+(\w+)\s+SET\s+(.+?)(?:\s+WHERE\s+(.+))?$',txt)
    if m:
        layername,assign,where=m.group(1),m.group(2),m.group(3)
        layer=next((l for l in ds.layers if l.name.lower()==layername.lower()),None)
        if layer is None:raise vectorsql.VectorSQLError(f"ERROR 1: Table {layername} not recognised.\n")
        assigns=[]
        for part in assign.split(","):
            if "=" in part:
                k,e=part.split("=",1)
                assigns.append((k.strip(),vectorsql.parse_where(e.strip())))
        expr=vectorsql.parse_where(where) if where else None
        for f in layer.features:
            if expr is None or vectorsql._truth(vectorsql.evaluate(expr,f,layer)):
                for k,e in assigns:f.properties[k]=vectorsql.evaluate(e,f,layer)
        return ds
    m=re.match(r'(?is)DELETE\s+FROM\s+(\w+)(?:\s+WHERE\s+(.+))?$',txt)
    if m:
        layer=next((l for l in ds.layers if l.name.lower()==m.group(1).lower()),None)
        if layer:
            expr=vectorsql.parse_where(m.group(2)) if m.group(2) else None
            layer.features=[f for f in layer.features if expr is None or not vectorsql._truth(vectorsql.evaluate(expr,f,layer))]
        return ds
    return ds

def handler_reproject(call):
    def tr(ds):
        dst_txt=call.parsed.values.get("dst-crs")
        dst,e,ok=crsmod.parse_crs_input(dst_txt)
        if not ok:
            return ds
        src_override=None
        if call.parsed.has("src-crs"):
            src_override,e,ok=crsmod.parse_crs_input(call.parsed.values.get("src-crs"))
        for layer in ds.layers:
            src=src_override or layer.crs or crsmod.geojson_crs()
            for f in layer.features:
                if f.geometry is not None:
                    f.geometry=_transform_geom(f.geometry,src,dst)
            layer.crs=dst
            layer.stored_extent=None
        return ds
    return run_vector(call,tr)

def _transform_geom(geom,src,dst):
    if geom is None:return None
    # collect coordinates flat for batch transform (preserve structure via transform_coords which calls point one by one; okay small)
    return geommod.transform_coords(geom,lambda c:crsmod.transform_point(src,dst,c[0],c[1],c[2] if len(c)>2 else None) if len(c)>=2 else c)

def handler_swap_xy(call):
    def tr(ds):
        for layer in _active_layers(ds,call):
            for f in layer.features:
                if f.geometry is not None:
                    f.geometry=geommod.transform_coords(f.geometry,lambda c:(c[1],c[0],*c[2:]) if len(c)>=2 else c)
            layer.stored_extent=None
            # If CRS axis mapping swaps? GDAL swap XY just coordinates, CRS remains as is.
        return ds
    return run_vector(call,tr)

def handler_make_point(call):
    def tr(ds):
        xfield=call.parsed.values.get("x");yfield=call.parsed.values.get("y");zfield=call.parsed.values.get("z");mfield=call.parsed.values.get("m")
        dst=None
        if call.parsed.has("dst-crs"):
            dst,e,ok=crsmod.parse_crs_input(call.parsed.values.get("dst-crs"))
        for layer in ds.layers:
            for fldname in [xfield,yfield]:
                if fldname and not layer.get_field(fldname):
                    raise ParseError(f'ERROR 1: make-point: Field "{fldname}" does not exist in layer "{layer.name}"\n',code=1)
            for f in layer.features:
                def getval(nm):
                    if nm is None:return None
                    fn=layer.get_field(nm)
                    if fn and fn.name in f.properties:
                        try:return float(f.properties[fn.name])
                        except:return None
                    # A field name argument could be a constant numeric? OGR make-point might accept field names only.
                    try:return float(nm)
                    except:return None
                x=getval(xfield);y=getval(yfield);z=getval(zfield) if zfield else None;m=getval(mfield) if mfield else None
                coords=[x,y]
                if z is not None:coords.append(z)
                if m is not None:
                    if z is None:coords.append(0.0)
                    coords.append(m)
                geom={"type":"Point","coordinates":coords}
                if dst and layer.crs:
                    geom=_transform_geom(geom,layer.crs,dst)
                f.geometry=geom
            layer.geom_type="Point Z" if zfield else "Point"
            if dst:layer.crs=dst
            layer.stored_extent=None
        return ds
    return run_vector(call,tr)

def handler_segmentize(call):
    maxlen=float(call.parsed.values.get("max-length"))
    def segmentize_seq(seq):
        if len(seq)<2:return seq
        out=[seq[0]]
        for a,b in zip(seq,seq[1:]):
            dist=math.hypot(float(b[0])-float(a[0]),float(b[1])-float(a[1]))
            if dist>maxlen:
                n=int(math.ceil(dist/maxlen))
                for i in range(1,n):
                    t=i/n
                    pt=[]
                    for dim in range(len(a)):
                        pt.append(float(a[dim])+(float(b[dim])-float(a[dim]))*t)
                    out.append(pt)
            out.append(b)
        return out
    def seg_geom(g):
        if g is None:return None
        t=g.get("type")
        if t in ("LineString","LinearRing"):
            return {"type":t,"coordinates":segmentize_seq(g["coordinates"])}
        if t=="Polygon":
            return {"type":t,"coordinates":[segmentize_seq(r) for r in g["coordinates"]]}
        if t=="MultiLineString":
            return {"type":t,"coordinates":[segmentize_seq(r) for r in g["coordinates"]]}
        if t=="MultiPolygon":
            return {"type":t,"coordinates":[[segmentize_seq(r) for r in poly] for poly in g["coordinates"]]}
        if "geometries" in g:
            return {"type":"GeometryCollection","geometries":[seg_geom(x) for x in g["geometries"]]}
        return g
    def tr(ds):
        for layer in _active_layers(ds,call):
            for f in layer.features:f.geometry=seg_geom(f.geometry)
        return ds
    return run_vector(call,tr)

def handler_rename_layer(call):
    # Special: input/output algorithm but only rename logic options (ASCII etc). It transforms layer names based on options, but original usage apparently takes input and output and generates layer names automatically from input names (sanitize). Let's inspect in operations probing after coding stubs: apply transformations to layer names.
    def sanitize(name):
        s=str(name)
        if call.parsed.values.get("lower-case"):s=s.lower()
        if call.parsed.values.get("ascii"):
            s=s.encode("ascii",errors="ignore").decode()
        if call.parsed.values.get("filename-compatible"):
            s=re.sub(r'[^A-Za-z0-9_.-]', call.parsed.values.get("replacement-character") or "_", s)
        res=call.parsed.values.get("reserved-characters")
        if res:
            rep=call.parsed.values.get("replacement-character") or "_"
            for ch in res:s=s.replace(ch,rep)
        maxlen=call.parsed.values.get("max-length")
        if maxlen:s=s[:int(maxlen)]
        return s
    def tr(ds):
        seen={}
        for l in ds.layers:
            new=sanitize(l.name)
            orig=new;i=2
            while new in seen:
                new=f"{orig}{i}";i+=1
            seen[new]=True;l.name=new
        return ds
    # output-layer from generic run_vector would overwrite first layer name after transform - rename-layer has no output-layer option? It might (common write), but if user provides it, fine.
    return run_vector(call,tr)

def handler_set_field_type(call):
    def tr(ds):
        field_name=call.parsed.values.get("field-name");src_type=call.parsed.values.get("src-field-type");new_type_raw=call.parsed.values.get("field-type")
        # Field type strings like 'Integer', 'Integer(Boolean)' etc parsing
        new_field=_parse_field_type(new_type_raw)
        for layer in ds.layers:
            for fld in layer.fields:
                if fld.name.lower()==str(field_name).lower():
                    # Only convert if source type matches? Argument name src-field-type is required and operation checks it? It likely identifies fields by name AND current type - if different, maybe skip/error.
                    converted=[]
                    for f in layer.features:
                        if fld.name in f.properties:
                            f.properties[fld.name]=_convert_field_value(f.properties[fld.name],new_field)
                    fld.type=new_field.type;fld.subtype=new_field.subtype;fld.width=new_field.width;fld.precision=new_field.precision
        return ds
    return run_vector(call,tr)

def _parse_field_type(s):
    t=str(s).strip()
    # Parse forms String, String(JSON), Integer(Boolean), Real, etc and width in parens numeric maybe Type(width.prec)
    m=re.match(r'^(\w+)(?:\(([^)]+)\))?$',t)
    if not m:return Field("x","String")
    base=m.group(1);inside=m.group(2)
    subtype=None;width=0;prec=0
    if inside:
        if re.match(r'^\d+(?:\.\d+)?$',inside):
            if '.' in inside:width,prec=map(int,inside.split('.'))
            else:width=int(inside)
        else:subtype=inside
    lookup={"string":"String","integer":"Integer","integer64":"Integer64","real":"Real","date":"Date","datetime":"DateTime","time":"Time","binary":"Binary","stringlist":"StringList","integerlist":"IntegerList","integer64list":"Integer64List","reallist":"RealList"}
    return Field("x",lookup.get(base.lower(),"String"),subtype,width,prec)

def _convert_field_value(v,new_field):
    if v is None:return None
    t=new_field.type
    try:
        if t in ("Integer","Integer64"):return int(float(v)) if isinstance(v,str) else int(v)
        if t=="Real":return float(v)
        if t=="String":
            if isinstance(v,float):
                from gutil import fmt_real_text;return fmt_real_text(v)
            return str(v)
        if t in ("IntegerList","Integer64List"):return [int(float(x)) for x in v] if isinstance(v,list) else [int(float(v))]
        if t=="RealList":return [float(x) for x in v] if isinstance(v,list) else [float(v)]
        if t=="StringList":return [str(x) for x in v] if isinstance(v,list) else [str(v)]
    except Exception:
        return None
    return v

def handler_set_geom_type(call):
    def tr(ds):
        gt_txt=call.parsed.values.get("geometry-type")
        target=None
        if gt_txt:
            target=_normalize_geom_type(gt_txt)
        for layer in _active_layers(ds,call):
            new_feats=[]
            encountered_type=None
            for f in layer.features:
                g=f.geometry
                if g is not None:
                    if call.parsed.values.get("multi"):
                        g=_promote_to_multi(g)
                    if call.parsed.values.get("single"):
                        # Explode multi into singles (creates multiple features)
                        singles=_explode_single(g)
                        if len(singles)!=1:
                            for sg in singles:
                                nf=f.copy();nf.geometry=sg;new_feats.append(nf)
                            continue
                        g=singles[0]
                    if call.parsed.values.get("linear"):
                        g=_curve_to_linear(g)
                    if call.parsed.values.get("curve"):
                        g=_linear_to_curve(g)
                    dim=call.parsed.values.get("dim")
                    if dim:
                        g=_force_dim(g,dim)
                    if target:
                        # If target is specific, check/convert
                        conv=_convert_geom_to_type(g,target)
                        if conv is None:
                            if call.parsed.values.get("skip"):continue
                            else:g=conv
                        else:g=conv
                f.geometry=g
                if g is not None:encountered_type=geommod.geom_type_name(g)
                new_feats.append(f)
            if not call.parsed.values.get("feature-only"):
                # Layer geom type
                candidates=[]
                for f in new_feats:
                    if f.geometry is not None:candidates.append(geommod.geom_type_name(f.geometry))
                if candidates and len(set(candidates))==1:
                    layer.geom_type=candidates[0]
                elif target:
                    layer.geom_type=target
                elif candidates:
                    layer.geom_type="Unknown (any)"
            layer.features=new_feats
            layer.stored_extent=None
        return ds
    return run_vector(call,tr)

def _promote_to_multi(g):
    t=g.get("type")
    if t=="Point":return {"type":"MultiPoint","coordinates":[g["coordinates"]]}
    if t in ("LineString","LinearRing"):return {"type":"MultiLineString","coordinates":[g["coordinates"]]}
    if t=="Polygon":return {"type":"MultiPolygon","coordinates":[g["coordinates"]]}
    return g

def _explode_single(g):
    t=g.get("type")
    if t=="MultiPoint":return [{"type":"Point","coordinates":c} for c in g["coordinates"]]
    if t=="MultiLineString":return [{"type":"LineString","coordinates":c} for c in g["coordinates"]]
    if t=="MultiPolygon":return [{"type":"Polygon","coordinates":c} for c in g["coordinates"]]
    if t=="GeometryCollection":return list(g.get("geometries",[]))
    return [g]

def _curve_to_linear(g):
    # CircularString approximated as LineString through its points; CompoundCurve etc not in our data model
    if g.get("type")=="CircularString":return {"type":"LineString","coordinates":g["coordinates"]}
    return g

def _linear_to_curve(g):
    return g

def _force_dim(g,dim):
    nd={"XY":2,"XYZ":3,"XYM":3,"XYZM":4}.get(str(dim).upper(),2)
    def f(c):
        vals=list(c)
        if str(dim).upper()=="XYM":
            if len(vals)>=4:return [vals[0],vals[1],vals[3]]
            while len(vals)<3:vals.append(0.0)
            return vals[:3]
        while len(vals)<nd:vals.append(0.0)
        return vals[:nd]
    return geommod.transform_coords(g,f)

def _convert_geom_to_type(g,target):
    base=target.split()[0]
    t=g.get("type")
    if base=="MultiPoint" and t=="Point":return _promote_to_multi(g)
    if base=="MultiLineString" and t in ("LineString","LinearRing"):return _promote_to_multi(g)
    if base=="MultiPolygon" and t=="Polygon":return _promote_to_multi(g)
    if base=="Point" and t=="MultiPoint" and len(g["coordinates"])==1:return {"type":"Point","coordinates":g["coordinates"][0]}
    if base=="LineString" and t=="MultiLineString" and len(g["coordinates"])==1:return {"type":"LineString","coordinates":g["coordinates"][0]}
    if base=="Polygon" and t=="MultiPolygon" and len(g["coordinates"])==1:return {"type":"Polygon","coordinates":g["coordinates"][0]}
    if base==t:return g
    if base=="Unknown" or base=="GeometryCollection":return g
    return None

def handler_explode_collections(call):
    def tr(ds):
        target=call.parsed.values.get("geometry-type")
        for layer in _active_layers(ds,call):
            new=[]
            for f in layer.features:
                parts=_explode_single(f.geometry) if f.geometry and f.geometry.get("type") in ("MultiPoint","MultiLineString","MultiPolygon","GeometryCollection") else [f.geometry]
                # GeometryCollection may contain nested collections/multi; explode recursively if targetType etc
                expanded=[]
                def expand(g):
                    if g and g.get("type")=="GeometryCollection":
                        for sub in g.get("geometries",[]):expand(sub)
                    elif g and g.get("type") in ("MultiPoint","MultiLineString","MultiPolygon"):
                        # Only explode multi if target set? explode-collections step explodes multi-geometries into single parts as classic ogr2ogr -explodecollections.
                        for sub in _explode_single(g):expanded.append(sub)
                    else:expanded.append(g)
                expanded=[];expand(f.geometry)
                for g in expanded:
                    if target:
                        norm=_normalize_geom_type(target)
                        if norm and g is not None and geommod.geom_type_name(g,include_z=False).split()[0]!=norm.split()[0]:
                            if call.parsed.values.get("skip-on-type-mismatch"):continue
                    nf=f.copy();nf.geometry=g;new.append(nf)
            layer.features=new
            # reassign fids sequential for output GeoJSON (fid only matters info); Original explodecollections keeps source fids duplicated? Feature dump after explode would show new fids 0.. because written/read GeoJSON assigns fids by order anyway.
            for i,f in enumerate(new):f.fid=i
            types=[geommod.geom_type_name(f.geometry) for f in new if f.geometry is not None]
            layer.geom_type=types[0] if types and len(set(types))==1 else "Unknown (any)"
