def _field_union(layer_list, strategy="union"):
    fields=[];names=set()
    if strategy=="intersection":
        if not layer_list:return []
        common=[]
        first=layer_list[0].fields
        for f in first:
            if all(any(ff.name.lower()==f.name.lower() for ff in l.fields) for l in layer_list):
                common.append(f.copy())
        return common
    for layer in layer_list:
        for f in layer.fields:
            if f.name.lower() not in names:
                fields.append(f.copy());names.add(f.name.lower())
            else:
                # promote type if conflict int->int64/real/string
                existing=next(x for x in fields if x.name.lower()==f.name.lower())
                existing.type=_promote_field_type(existing.type,f.type)
    return fields

def _promote_field_type(a,b):
    if a==b:return a
    if "String" in (a,b):return "String"
    if a=="Integer" and b=="Integer64":return "Integer64"
    if b=="Integer" and a=="Integer64":return "Integer64"
    if a in ("Integer","Integer64") and b=="Real":return "Real"
    if b in ("Integer","Integer64") and a=="Real":return "Real"
    return "String"

