def _sort_hilbert(features):
    if len(features)<=1:return features
    pts=[]
    for f in features:
        c=geommod.centroid(f.geometry) if f.geometry else None
        pts.append((c["coordinates"] if c else (0,0)))
    minx=min(p[0] for p in pts);maxx=max(p[0] for p in pts);miny=min(p[1] for p in pts);maxy=max(p[1] for p in pts)
    order=16
    def hilbert_index(x,y):
        # normalize to grid 2^order
        gx=int((x-minx)/(maxx-minx)*((1<<order)-1)) if maxx>minx else 0
        gy=int((y-miny)/(maxy-miny)*((1<<order)-1)) if maxy>miny else 0
        d=0;s=1<<(order-1)
        # xy2d algorithm from standard Hilbert curve algorithm
        rx=ry=0
        xx,yy=gx,gy
        while s>0:
            rx=1 if (xx & s) else 0;ry=1 if (yy & s) else 0
            d+=s*s*((rx*3)^ry)
            if ry==0:
                if rx==1:xx=s-1-xx;yy=s-1-yy
                xx,yy=yy,xx
            s//=2
        return d
    paired=sorted(zip([hilbert_index(p[0],p[1]) for p in pts],features),key=lambda pair:pair[0])
    return [f for _,f in paired]

def _sort_strtree(features):
    # STR packing: tile by x slices then y. Simplified sort by centroid x then y in groups of ceil(sqrt(n))
    if len(features)<=1:return features
    def center(f):
        c=geommod.centroid(f.geometry) if f.geometry else None;return c["coordinates"] if c else (0,0)
    n=len(features);slices=max(1,int(math.ceil(math.sqrt(n))))
    sorted_x=sorted(features,key=lambda f:center(f)[0])
    result=[]
    per_slice=int(math.ceil(n/slices))
    for i in range(0,n,per_slice):
        group=sorted_x[i:i+per_slice]
        result.extend(sorted(group,key=lambda f:center(f)[1]))
    return result
