def _grid_linear(cx,cy,filtered,points,nodata):
    # Delaunay barycentric - implement simple incremental triangulation might be heavy. Use nearest 3 non-collinear points and barycentric if inside their triangle, else invdist-like nearest triangle search over all combos of near points limited.
    # Take up to nearest 10 points and search triangles containing point.
    cand=filtered[:12] if filtered else []
    for i in range(len(cand)):
        for j in range(i+1,len(cand)):
            for k in range(j+1,len(cand)):
                p=[cand[i],cand[j],cand[k]]
                coords=[(q[1],q[2],q[3]) for q in p]
                det=(coords[1][1]-coords[2][1])*(coords[0][0]-coords[2][0])+(coords[2][0]-coords[1][0])*(coords[0][1]-coords[2][1])
                if det==0:continue
                l1=((coords[1][1]-coords[2][1])*(cx-coords[2][0])+(coords[2][0]-coords[1][0])*(cy-coords[2][1]))/det
                l2=((coords[2][1]-coords[0][1])*(cx-coords[2][0])+(coords[0][0]-coords[2][0])*(cy-coords[2][1]))/det
                l3=1-l1-l2
                if l1>=-1e-9 and l2>=-1e-9 and l3>=-1e-9:
                    return l1*coords[0][2]+l2*coords[1][2]+l3*coords[2][2]
