def _compute_overview_band(band,factor,resampling):
    ow=int(math.ceil(band.width/factor));oh=int(math.ceil(band.height/factor))
    ob=Band(band.dtype,ow,oh,nodata=band.nodata,color_interp=band.color_interp)
    method=(resampling or "nearest").lower()
    for y in range(oh):
        sy=(y+0.5)*factor-0.5
