            sx=(x+0.5)*factor-0.5
            v=sample_band(band,sx,sy,method,factor)
            if v is None:v=band.nodata if band.nodata is not None else 0
            ob.data[y][x]=cast_value(v,band.dtype)
    ob.block_size=(min(band.block_size[0],ow) if band.block_size else ow,min(band.block_size[1],oh) if band.block_size and len(band.block_size)>1 else oh)
    # Original overview block often 128x128 for external / same tiles - leave as source block clamped.
    return ob

def _default_overview_factors(ds,min_size=None):
    factors=[];factor=2
    max_dim=max(ds.width,ds.height)
    limit=int(min_size) if min_size else 256
    while True:
        w=int(math.ceil(ds.width/factor));h=int(math.ceil(ds.height/factor))
        if max(w,h)<=limit and factors:
