def _apply_pixel_function(name,vals,args):
    fvals=[float(v.real if isinstance(v,complex) else v) for v in vals]
    n=str(name).lower()
    if n=="sum":return sum(fvals)
    if n=="mean":return sum(fvals)/len(fvals)
    if n=="min":return min(fvals)
    if n=="max":return max(fvals)
    if n=="median":
        s=sorted(fvals);return s[len(s)//2] if len(s)%2 else (s[len(s)//2-1]+s[len(s)//2])/2
    if n=="mode":
        from collections import Counter;return Counter(vals).most_common(1)[0][0]
    if n=="diff":return fvals[0]-fvals[1] if len(fvals)>1 else fvals[0]
    if n=="div":return fvals[0]/fvals[1] if len(fvals)>1 and fvals[1]!=0 else 0
    if n=="mul":
        r=1
        for v in fvals:r*=v
        return r
    if n=="norm_diff":return (fvals[0]-fvals[1])/(fvals[0]+fvals[1]) if len(fvals)>1 and fvals[0]+fvals[1]!=0 else 0
    if n=="geometric_mean":return math.exp(sum(math.log(v) for v in fvals if v>0)/len([v for v in fvals if v>0])) if any(v>0 for v in fvals) else 0
    if n=="harmonic_mean":return len(fvals)/sum(1/v for v in fvals if v!=0) if all(v!=0 for v in fvals) else 0
    if n=="pow":return fvals[0]**(float(dict(args).get("power",fvals[1] if len(fvals)>1 else 1)))
    if n=="sqrt":return math.sqrt(fvals[0]) if fvals[0]>=0 else 0
    if n=="exp":return math.exp(fvals[0])
    if n=="log10":return math.log10(fvals[0]) if fvals[0]>0 else 0
    if n=="real":return vals[0].real if isinstance(vals[0],complex) else fvals[0]
    if n=="imag":return vals[0].imag if isinstance(vals[0],complex) else 0
    if n=="expression":
        return fvals[0]
    if n=="replace_nodata":return fvals[0]
    if n=="argmax":return fvals.index(max(fvals)) if False else max(range(len(vals)),key=lambda i:fvals[i])
    if n=="argmin":return min(range(len(vals)),key=lambda i:fvals[i])
    if n=="quantile":
        q=float(dict(args).get("q",dict(args).get("quantile",0.5)));s=sorted(fvals);idx=q*(len(s)-1);lo=int(math.floor(idx));hi=int(math.ceil(idx));return s[lo]+(s[hi]-s[lo])*(idx-lo)
    return fvals[0]

