    # If input and output both open: input is the source to burn into output. If output does not exist, might create it?
    src_ds=open_raster(call)
    output=call.parsed.values.get("output");output=output[0] if isinstance(output,list) else output
    # Validate but target may exist and no overwrite flag in spec - use validate customized: If not exists, create copy of source (like convert)
    if not dataset_exists(str(output),None):
        return run_raster(lambda:None,lambda ds:ds) if False else _raster_convert_like(call,src_ds,output)
    target=open_rasters(call,[str(output)])[0]
    one_config_warning(call)
