            if not (ref.crs.epsg and inp.crs.epsg and ref.crs.epsg==inp.crs.epsg):diffs.append("Reference and input datasets have different CRS.")
    if not (call.parsed.values.get("skip-geotransform") or skip_all):
        if ref.has_geotransform and not inp.has_geotransform:diffs.append("Reference dataset has a geotransform, but input one has no one.")
        elif inp.has_geotransform and not ref.has_geotransform:diffs.append("Reference dataset has no geotransform, but input one has one.")
        elif ref.has_geotransform and inp.has_geotransform and ref.geotransform!=inp.geotransform:diffs.append("Reference and input datasets have different geotransforms.")
    if ref.width!=inp.width:diffs.append(f"Reference dataset width is {ref.width}, but input dataset width is {inp.width}")
    if ref.height!=inp.height:diffs.append(f"Reference dataset height is {ref.height}, but input dataset height is {inp.height}")
    if not (call.parsed.values.get("skip-metadata") or skip_all):
