    if len(ref.bands)!=len(inp.bands):diffs.append(f"Reference dataset has {len(ref.bands)} bands, but input dataset has {len(inp.bands)} bands")
    else:
        for i,(rb,ib) in enumerate(zip(ref.bands,inp.bands)):
            if rb.dtype!=ib.dtype:diffs.append(f"Band {i+1}: Reference band type is {rb.dtype}, but input band type is {ib.dtype}")
            if rb.block_size!=ib.block_size and not skip_all:diffs.append(f"Band {i+1}: Reference band block size is {rb.block_size[0]}x{rb.block_size[1]}, but input band block size is {ib.block_size[0]}x{ib.block_size[1]}")
            if rb.color_interp!=ib.color_interp and not skip_all:diffs.append(f"Band {i+1}: Reference band color interpretation is {rb.color_interp}, but input band color interpretation is {ib.color_interp}")
            if rb.nodata!=ib.nodata and not skip_all:diffs.append(f"Band {i+1}: Reference band nodata is {rb.nodata}, but input band nodata is {ib.nodata}")
