def _dem_window(band,x,y):
    vals=[]
    for dy in (-1,0,1):
        row=[]
        for dx in (-1,0,1):
            xx=min(max(x+dx,0),band.width-1);yy=min(max(y+dy,0),band.height-1)
            row.append(band.data[yy][xx])
        vals.append(row)
    return vals

def _dem_gradient(band,x,y,alg,xscale_pixels,yscale_pixels):
    w=_dem_window(band,x,y)
    # if any neighbor nodata, caller decides output nodata (except edges duplicate values could be nodata)
    if str(alg).lower().startswith("zeven"):
        dzdx=((w[1][2]-w[1][0])/(2*xscale_pixels)) if xscale_pixels else 0
        dzdy=((w[2][1]-w[0][1])/(2*yscale_pixels)) if yscale_pixels else 0
    else:
        dzdx=(((w[0][2]+2*w[1][2]+w[2][2])-(w[0][0]+2*w[1][0]+w[2][0]))/(8*xscale_pixels)) if xscale_pixels else 0
        dzdy=(((w[2][0]+2*w[2][1]+w[2][2])-(w[0][0]+2*w[0][1]+w[0][2]))/(8*yscale_pixels)) if yscale_pixels else 0
    return float(dzdx),float(dzdy)

def _dem_scales(ds,call):
    gt=ds.geotransform
    xres=math.hypot(gt[1],gt[4]);yres=math.hypot(gt[2],gt[5])
    xscale_arg=call.parsed.values.get("xscale") if call.parsed.has("xscale") else None
    yscale_arg=call.parsed.values.get("yscale") if call.parsed.has("yscale") else None
    # GDAL DEM scale semantics: user xscale/yscale are ratio vertical units to horizontal units / conversion factors. Effective denominator is pixel distance in same horizontal units * scale. If CRS is geographic degrees, default scale from GDAL is based on 111120 (m/degree) at center latitude maybe.
    def default_scale(is_x):
        if ds.crs and ds.crs.is_geographic():
            # GDAL gdaldem uses spherical earth circumference approximation 111120 m/degree for latitude, longitude scaled by cos(center lat) for x.
            center_lat=0.0
            try:
                ext=ds.extent();center_lat=(ext[1]+ext[3])/2
            except:center_lat=0
            return 111120.0*math.cos(math.radians(center_lat)) if is_x else 111120.0
        # CRS axis units conversion to meters if projected and unit not meters could be omitted.
        return 1.0
    xscale=float(xscale_arg) if xscale_arg is not None else default_scale(True)
    yscale=float(yscale_arg) if yscale_arg is not None else default_scale(False)
    return xres*xscale,yres*yscale

def _run_dem(call, mode):
    in_ds=open_raster(call)
    output=call.parsed.values.get("output");output=output[0] if isinstance(output,list) else output
    driver=validate_output(call,output,call.parsed.values.get("output-format"),"raster")
    if driver=="GDALG":one_config_warning(call);return gdalgmod.write_gdalg(call,output)
    if driver=="VRT":_raise_vrt_incompatible(call,explicit=bool(call.parsed.values.get("output-format")))
    config_warnings_for_operation(call,"read_write")
    band_idx=int(call.parsed.values.get("band") or 1)
    if band_idx<1 or band_idx>len(in_ds.bands):
        raise ParseError(f"ERROR 1: Band {band_idx} requested, but only bands 1 to {len(in_ds.bands)} available.\n",code=1)
    band=in_ds.bands[band_idx-1]
    xs,ys=_dem_scales(in_ds,call)
    out_dtype="Byte" if mode=="hillshade" else "Float32"
    out_nodata=0 if mode=="hillshade" else -9999.0
    out_band=Band(out_dtype,in_ds.width,in_ds.height,nodata=out_nodata,color_interp="Gray")
    grad_alg=call.parsed.values.get("gradient-alg") or "Horn"
    no_edges=bool(call.parsed.values.get("no-edges"))
    zfactor=float(call.parsed.values.get("zfactor") or 1.0) if mode=="hillshade" else 1.0
    for y in range(in_ds.height):
        for x in range(in_ds.width):
            center=band.data[y][x]
            if band.nodata is not None and center==band.nodata:
                out_band.data[y][x]=cast_value(out_nodata,out_dtype);continue
            if no_edges and (x==0 or y==0 or x==in_ds.width-1 or y==in_ds.height-1):
                out_band.data[y][x]=cast_value(out_nodata,out_dtype);continue
            win=_dem_window(band,x,y)
            # nodata in any non-duplicated neighbor => nodata output in GDAL DEM for slope/aspect etc (if bComputeEdges might treat outside as center). Check in-bounds neighbors only.
            has_nd=False
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    xx=x+dx;yy=y+dy
                    if 0<=xx<band.width and 0<=yy<band.height and band.nodata is not None and band.data[yy][xx]==band.nodata:has_nd=True
            if has_nd:
                out_band.data[y][x]=cast_value(out_nodata,out_dtype);continue
            dzdx,dzdy=_dem_gradient(band,x,y,grad_alg,xs,ys)
            if mode=="slope":
                slope_mag=math.hypot(dzdx,dzdy)
                val=math.degrees(math.atan(slope_mag)) if (call.parsed.values.get("unit") or "degree")=="degree" else slope_mag*100.0
            elif mode=="aspect":
                if dzdx==0 and dzdy==0:
                    val=0.0 if call.parsed.values.get("zero-for-flat") else out_nodata
                    out_band.data[y][x]=cast_value(val,out_dtype);continue
                trig=math.degrees(math.atan2(dzdy,-dzdx))
                if (call.parsed.values.get("convention") or "azimuth")=="trigonometric-angle":val=trig%360.0
                else:val=(90.0-trig)%360.0
            elif mode=="hillshade":
                # Scale gradients by zfactor (DEM code applies to elevation values before gradient)
                dzdx*=zfactor;dzdy*=zfactor
                alt=math.radians(float(call.parsed.values.get("altitude") or 45.0));az=math.radians(float(call.parsed.values.get("azimuth") or 315.0))
                variant=(call.parsed.values.get("variant") or "regular")
                def shade_one(azimuth_rad,altitude_rad):
                    nx=-dzdx;ny=dzdy;nz=1.0
                    norm=math.sqrt(nx*nx+ny*ny+nz*nz)
                    sx=math.sin(azimuth_rad)*math.cos(altitude_rad);sy=math.cos(azimuth_rad)*math.cos(altitude_rad);sz=math.sin(altitude_rad)
                    return max(0.0,(nx*sx+ny*sy+nz*sz)/norm)
                if variant=="multidirectional":
                    # average illumination for azimuths spaced 45 degrees as GDAL doc (16 directions?) Approx 16 around az.
                    vals=[shade_one(az+math.radians(i*45),alt) for i in range(8)];shade=sum(vals)/len(vals)
                elif variant=="combined":
                    shade=shade_one(az,alt)
                    slope_mag=math.hypot(dzdx,dzdy);shade=(shade+max(0.0,1.0-slope_mag))/2 if False else shade*(1.0-0.5*min(1.0,slope_mag))
                    shade=max(0.0,min(1.0,shade))
                elif variant=="Igor":
                    # Igor hillshading uses normalized dot with denominator adjustments - fallback regular
                    shade=shade_one(az,alt)
                else:shade=shade_one(az,alt)
                val=255.0*shade
            elif mode=="roughness":
                flat=[float(v) for row in win for v in row]
                # With edge duplicate values; original edge quirks accepted
                val=max(flat)-min(flat)
            elif mode=="tpi":
                neigh=[float(win[yy][xx]) for yy in range(3) for xx in range(3) if not (xx==1 and yy==1)]
                val=float(center)-sum(neigh)/len(neigh)
            elif mode=="tri":
                if (call.parsed.values.get("algorithm") or "Riley")=="Wilson":
                    diffs=[]
                    for yy in range(3):
                        for xx in range(3):
                            if xx==1 and yy==1:continue
                            diffs.append(abs(float(center)-float(win[yy][xx])))
                    val=sum(diffs)/len(diffs) if diffs else 0
                else:
                    total=0.0
                    for yy in range(3):
                        for xx in range(3):
                            if xx==1 and yy==1:continue
                            d=float(center)-float(win[yy][xx]);total+=d*d
                    val=math.sqrt(total)
            else:val=0
            out_band.data[y][x]=cast_value(val,out_dtype)
    out_ds=RasterDataset(in_ds.width,in_ds.height,[out_band],in_ds.geotransform,in_ds.crs,copy.deepcopy(in_ds.metadata),driver,driver,str(output),has_geotransform=in_ds.has_geotransform)
    creation_opts=parse_kv_options(call.parsed.values.get("creation-option") or [])
    _write_raster(call,out_ds,output,driver,creation_opts,preserve=True,use_source_block=True,progress=True)
    return 0

def handler_slope(call):return _run_dem(call,"slope")
def handler_aspect(call):return _run_dem(call,"aspect")
def handler_hillshade(call):return _run_dem(call,"hillshade")
def handler_roughness(call):return _run_dem(call,"roughness")
def handler_tpi(call):return _run_dem(call,"tpi")
def handler_tri(call):return _run_dem(call,"tri")

def handler_neighbors(call):
    kernel_vals=call.parsed.values.get("kernel") or []
    methods=call.parsed.values.get("method") or []
    if isinstance(methods,str):methods=[methods]
    if not methods:methods=[]
    # Kernel is required by spec parser. Values as strings packed maybe "1,1,1;1,1,1" or numbers repeated. Need parse based on --size.
    size=int(call.parsed.values.get("size")) if call.parsed.values.get("size") is not None else None
    kernel=None
    # Parse kernel argument in handler to validate semantic count like original likely.
    flat=[]
    for item in kernel_vals:
        s=str(item)
        for tok in re.split(r'[,;\s]+',s.strip()):
            if tok:
                try:flat.append(float(tok))
                except:flat.append(0)
    if size:
        if len(flat)!=size*size:
            raise ParseError(f"ERROR 1: neighbors: Invalid kernel size\n",code=1)
        kernel=[flat[i*size:(i+1)*size] for i in range(size)]
    else:
        # Infer square size from number values
        n=int(math.isqrt(len(flat)))
        if n*n==len(flat) and n>0:
            size=n;kernel=[flat[i*n:(i+1)*n] for i in range(n)]
        else:
            raise ParseError(f"ERROR 1: neighbors: Invalid kernel size\n",code=1)
    def tr(ds):
        band_idx=call.parsed.values.get("band")
        out_dtype=canon_dtype(call.parsed.values.get("output-data-type") or "Float64")
        out_bands=[]
        src_bands=[ds.bands[int(band_idx)-1]] if band_idx is not None else list(ds.bands)
        # --nodata argument in neighbors is a string in spec (parse using helper)
        nd_val=None;nd_none=False
        if call.parsed.has("nodata"):
            from ops_basic import _parse_nodata_arg;nd_val,nd_none=_parse_nodata_arg(call.parsed.values.get("nodata"),call)
        for band in src_bands:
            if methods:
                for method in methods:
                    ob=_neighbors_compute(band,kernel,method,out_dtype,nd_val,nd_none);out_bands.append(ob)
            else:
                out_bands.append(_neighbors_compute(band,kernel,None,out_dtype,nd_val,nd_none))
        ds.bands=out_bands
        return ds
    return run_raster(call,tr)

def _neighbors_compute(band,kernel,method,out_dtype,nd_val,nd_none):
    size=len(kernel);radius=size//2
    ob=Band(out_dtype,band.width,band.height,nodata=(None if nd_none else nd_val),color_interp=band.color_interp)
    for y in range(band.height):
        for x in range(band.width):
            vals=[]
            weighted=0.0;wsum=0.0
            for ky in range(size):
                for kx in range(size):
                    kv=kernel[ky][kx]
                    if kv==0:continue
                    xx=x+kx-radius;yy=y+ky-radius
                    if 0<=xx<band.width and 0<=yy<band.height:
                        v=band.data[yy][xx]
                        if band.nodata is not None and v==band.nodata:continue
                        vals.append(float(v));weighted+=float(v)*kv;wsum+=kv
            if not vals:
                ob.data[y][x]=cast_value(nd_val if nd_val is not None else 0,out_dtype);continue
            if method is None:
                # kernel is weights: result is weighted sum (not normalized unless kernel sums to 1)
                val=weighted
            else:
                m=str(method).lower()
