    driver=validate_output(call,output,call.parsed.values.get("output-format"),"vector")
    if driver=="GDALG":one_config_warning(call);return gdalgmod.write_gdalg(call,output)
    config_warnings_for_operation(call,"read_write")
    band=in_ds.bands[int(call.parsed.values.get("band") or 1)-1]
    nodata=call.parsed.values.get("src-nodata")
    src_nd=float(nodata) if nodata is not None else band.nodata
    levels=_contour_levels(call,band,src_nd)
    elev_name=call.parsed.values.get("elevation-name") or "ELEV"
