def _in_range(v,lo,hi,nd):
    if nd is not None and v==nd:return False
    fv=float(v)
    if lo is not None and fv<lo:return False
    if hi is not None and fv>=hi:return False
    return True

def _contour_levels(call,band,src_nd):
    if call.parsed.has("levels"):
        vals=[]
        for raw in call.parsed.values.get("levels") or []:
            for part in re.split(r'[, ]+',str(raw)):
                if part:vals.append(float(part))
        return sorted(vals)
    vals=[float(v) for row in band.data for v in row if not (src_nd is not None and v==src_nd)]
    if not vals:return []
    mn=min(vals);mx=max(vals);offset=float(call.parsed.values.get("offset") or 0.0)
    if call.parsed.has("exp-base"):
        base=int(call.parsed.values.get("exp-base"));interval=float(call.parsed.values.get("interval") or 1.0)
        levels=[];k=-10
        while k<100:
            lev=offset+interval*(base**k) if k>=0 else offset+interval/(base**(-k))
            if mn<=lev<=mx:levels.append(lev)
            if lev>mx and k>0:break
            k+=1
        return sorted(set(levels))
    interval=float(call.parsed.values.get("interval"))
    if interval==0:return []
    start=math.ceil((mn-offset)/interval)*interval+offset
    levels=[];lev=start
    while lev<=mx:
        levels.append(lev);lev+=interval
        if len(levels)>100000:break
    return levels

def _marching_squares_lines(band,level,src_nd):
    # Treat samples as grid points at centers with coordinates x=index, y=index (pixel coordinate center convention?)
    # In GDALContour, pixel centres are at integer coordinates in image space; segment endpoints transform via gt(x,y) where x/y are point coordinates in pixel/line of samples: our transform adds 0.5 in _geo_transform caller? We return coordinates in pixel-space where point index is treated by caller transform _geo_transform_point(in_ds,px,py), which maps (0,0) to origin corner - that means sample 0 becomes corner, a half pixel shift from GDAL (which maps sample center to gt + (col+0.5)*res). Caller should add 0.5 before geo transform. Our line coords are point coords in "sample index" space, caller as above does _geo_transform_point(in_ds,px,py) without +0.5, so line locations are shifted half pixel. To avoid refactoring, in this function return coords with +0.5 offset added: result point corresponds to geo correctly when caller applies gt directly.
    segments=[]
    # Edge intersection cache: edge ('h',x,y) horizontal between (x,y)-(x+1,y), ('v',x,y) vertical between (x,y)-(x,y+1)
    def is_valid(v):return not (src_nd is not None and v==src_nd)
    def interp(p1,p2,v1,v2):
        t=(level-v1)/(v2-v1) if v2!=v1 else 0
        return (p1[0]+(p2[0]-p1[0])*t+0.5,p1[1]+(p2[1]-p1[1])*t+0.5)
    for y in range(band.height-1):
        for x in range(band.width-1):
            vals=[[band.data[y][x],band.data[y][x+1]],[band.data[y+1][x],band.data[y+1][x+1]]]  # NW NE / SW SE
            # Values order TL,TR,BR,BL for marching squares
            corners=[(x,y,vals[0][0]),(x+1,y,vals[0][1]),(x+1,y+1,vals[1][1]),(x,y+1,vals[1][0])]
            if any(not is_valid(c[2]) for c in corners):continue
            case=0
            for i,c in enumerate(corners):
                if float(c[2])>level:case|=1<<i
            if case==0 or case==15:continue
            # edges: 0 top TL-TR,1 right TR-BR,2 bottom BR-BL (reverse),3 left BL-TL
            edge_pts={}
            edges=[(0,1),(1,2),(3,2),(0,3)]  # (edge endpoints indices in corners, careful bottom from BL to BR)
            # Define bottom edge as BL(3)-BR(2), left as TL(0)-BL(3)
            edge_defs=[(corners[0],corners[1]),(corners[1],corners[2]),(corners[3],corners[2]),(corners[0],corners[3])]
            for ei,(a,b) in enumerate(edge_defs):
                if (float(a[2])>level)!=(float(b[2])>level):
                    edge_pts[ei]=interp((a[0],a[1]),(b[0],b[1]),float(a[2]),float(b[2]))
            # Standard lookup by case (TL=1,TR=2,BR=4,BL=8)
            table={1:[(3,0)],2:[(0,1)],3:[(3,1)],4:[(1,2)],5:[(3,0),(1,2)],6:[(0,2)],7:[(3,2)],8:[(2,3)],9:[(0,2)],10:[(0,1),(2,3)],11:[(1,2)],12:[(3,1)],13:[(0,1)],14:[(3,0)]}
            # Saddle cases 5/10 selection based average maybe our pairs are a choice.
            for e1,e2 in table.get(case,[]):
                if e1 in edge_pts and e2 in edge_pts:
                    segments.append((edge_pts[e1],edge_pts[e2]))
    # Stitch segments into lines by exact endpoint matches
    lines=_stitch_segments(segments)
    return lines

def _stitch_segments(segments):
    # Map endpoint rounded to segment indices
    from collections import defaultdict
    def key(p):return (round(p[0],10),round(p[1],10))
    adj=defaultdict(list)
    for i,(a,b) in enumerate(segments):
        adj[key(a)].append(i);adj[key(b)].append(i)
    used=[False]*len(segments);lines=[]
    for i,seg in enumerate(segments):
        if used[i]:continue
        used[i]=True;line=[seg[0],seg[1]]
        # extend forward
        while True:
            end=line[-1]
            cand=[j for j in adj[key(end)] if not used[j]]
            if not cand:break
            j=cand[0];used[j]=True;a,b=segments[j]
            nxt=b if key(a)==key(end) else a
            line.append(nxt)
            if key(nxt)==key(line[0]):break
        # extend backward
        while True:
            start=line[0]
            cand=[j for j in adj[key(start)] if not used[j]]
            if not cand:break
            j=cand[0];used[j]=True;a,b=segments[j]
            nxt=b if key(a)==key(start) else a
            line.insert(0,nxt)
            if key(nxt)==key(line[-1]):break
        if len(line)>=2:lines.append(line)
    return lines

