    zones_ds=None;zones_raster=None
    try:
        zones_ds=open_vector_dataset(zones_path)
    except Exception:
        try:zones_raster=open_raster_dataset(zones_path)
        except Exception:raise ParseError(f"ERROR 4: {zones_path}: No such file or directory\n"+call.usage_appendix(),code=1)
    out_layers=[]
    if zones_raster is not None:
        zb_idx=int(call.parsed.values.get("zones-band") or 1);zband=zones_raster.bands[zb_idx-1]
        # Zones are values in zones raster aligned by geo/pixels - if zones raster dimensions differ, resample nearest by geo mapping (simplified pixel normalized)
        zone_vals={}
        # stats per band per zone -> fields naming: For each requested stat, if multiple bands prefix b{bi}_ maybe original.
        fields=[Field("zone","Real" if zband.dtype.startswith("Float") else "Integer64")]
        stat_fields=[]
        for bi in band_indices:
            for st in stats_arg:
                fname=(f"b{bi}_{st}" if len(band_indices)>1 else st)
                stat_fields.append((bi,st,fname));fields.append(Field(fname,"Real" if st not in ("count","coverage","unique","variety") else "Integer64"))
        # Gather values
        per_zone={}
        for y in range(in_ds.height):
            for x in range(in_ds.width):
                zx=int(x*zones_raster.width/in_ds.width);zy=int(y*zones_raster.height/in_ds.height)
                zv=zband.data[min(zy,zones_raster.height-1)][min(zx,zones_raster.width-1)]
                if zband.nodata is not None and zv==zband.nodata:continue
                if zv not in per_zone:per_zone[zv]={}
                for bi in band_indices:
                    v=in_ds.bands[bi-1].data[y][x]
                    if in_ds.bands[bi-1].nodata is not None and v==in_ds.bands[bi-1].nodata:continue
                    per_zone[zv].setdefault(bi,[]).append((float(v),x,y))
        features=[]
        for zv in sorted(per_zone.keys(),key=lambda z:float(z)):
            props={"zone":_zone_value(zv)}
            for bi,st,fname in stat_fields:
                vals=per_zone[zv].get(bi,[])
                props[fname]=_compute_zone_stat(st,vals,in_ds,x_band=bi)
            features.append(Feature(len(features),props,None))
        layer=Layer(_output_layer_name(call,"zonal_stats"),fields,features,"None",None);layer.has_geometry=False
        out_layers=[layer]
    else:
        include_fields=call.parsed.values.get("include-field") or []
        zone_layer_filter=call.parsed.values.get("zones-layer")
        for zlayer in zones_ds.layers:
            if zone_layer_filter and zlayer.name!=zone_layer_filter:continue
            fields=[]
            if include_fields:
                for fn in include_fields:
                    fld=zlayer.get_field(fn)
                    if fld:fields.append(fld.copy())
            stat_fields=[]
            for bi in band_indices:
                for st in stats_arg:
                    fname=(f"b{bi}_{st}" if len(band_indices)>1 else st)
                    stat_fields.append((bi,st,fname));fields.append(Field(fname,"Real" if st not in ("count",) else "Integer64"))
            feats=[]
            for feat in zlayer.features:
                # pixels whose centers inside feature geometry
                props={fld.name:feat.properties.get(fld.name) for fld in fields if fld.name in feat.properties}
                vals_by_band={}
                for bi in band_indices:
                    vals=[]
                    for y in range(in_ds.height):
                        for x in range(in_ds.width):
                            gx,gy=_geo_transform_point(in_ds,x+0.5,y+0.5)
                            if _point_in_geometry(gx,gy,feat.geometry):
                                v=in_ds.bands[bi-1].data[y][x]
                                if in_ds.bands[bi-1].nodata is not None and v==in_ds.bands[bi-1].nodata:continue
                                vals.append((float(v),x,y))
                    vals_by_band[bi]=vals
                for bi,st,fname in stat_fields:props[fname]=_compute_zone_stat(st,vals_by_band.get(bi,[]),in_ds)
                feats.append(Feature(len(feats),props,copy.deepcopy(feat.geometry)))
            out_layers.append(Layer(_output_layer_name(call,zlayer.name),fields,feats,zlayer.geom_type,zlayer.crs))
    out_ds=VectorDataset(driver,driver,str(output),out_layers)
    return _write_vector_from_raster(call,out_ds,output,driver)

def _zone_value(v):
    return int(v) if isinstance(v,int) or (isinstance(v,float) and v==int(v)) else v

def _compute_zone_stat(stat,vals,ds,x_band=None):
    # vals list (value,x,y)
    if not vals:return None
    floats=[v for v,x,y in vals]
    st=stat.lower()
    if st=="count":return len(vals)
    if st=="coverage":return len(vals) # number pixels? coverage could be area - approximate count * pixel area in a helper outside not known. We'll handle below if needed.
    if st=="sum":return sum(floats)
    if st=="mean":return sum(floats)/len(floats)
    if st=="min":return min(floats)
    if st=="max":return max(floats)
    if st=="median":
        s=sorted(floats);n=len(s);return s[n//2] if n%2 else (s[n//2-1]+s[n//2])/2
    if st=="stdev" or st=="variance":
        mu=sum(floats)/len(floats);var=sum((v-mu)**2 for v in floats)/len(floats);return math.sqrt(var) if st=="stdev" else var
    if st=="mode":
        from collections import Counter;return Counter(floats).most_common(1)[0][0]
    if st=="minority":
        from collections import Counter;return Counter(floats).most_common()[-1][0]
    if st=="variety":return len(set(floats))
    if st=="unique":return sorted(set(floats))
    if st=="values":return floats
    if st=="frac":return len(vals)/(ds.width*ds.height) if ds else None
    if st in ("center_x","center_y","min_center_x","min_center_y","max_center_x","max_center_y"):
        if st.startswith("min_"):target=min(vals,key=lambda t:t[0])
        elif st.startswith("max_"):target=max(vals,key=lambda t:t[0])
        else:target=vals[len(vals)//2]
        geo=_geo_transform_point(ds,target[1]+0.5,target[2]+0.5)
        return geo[0] if st.endswith("_x") else geo[1]
    if st.startswith("weighted_"):
        return _compute_zone_stat(st.replace("weighted_",""),vals,ds)
    if st=="weights":return len(vals)
    return None
