def _zone_value(v):
    return int(v) if isinstance(v,int) or (isinstance(v,float) and v==int(v)) else v

def _compute_zone_stat(stat,vals,ds,x_band=None):
    # vals list (value,x,y)
    if not vals:return None
    floats=[v for v,x,y in vals]
    st=stat.lower()
    if st=="count":return len(vals)
    if st=="coverage":return len(vals) # number pixels? coverage could be area - approximate count * pixel area in a helper outside not known. We'll handle below if needed.
    if st=="sum":return sum(floats)
    if st=="mean":return sum(floats)/len(floats)
    if st=="min":return min(floats)
    if st=="max":return max(floats)
    if st=="median":
        s=sorted(floats);n=len(s);return s[n//2] if n%2 else (s[n//2-1]+s[n//2])/2
    if st=="stdev" or st=="variance":
        mu=sum(floats)/len(floats);var=sum((v-mu)**2 for v in floats)/len(floats);return math.sqrt(var) if st=="stdev" else var
    if st=="mode":
        from collections import Counter;return Counter(floats).most_common(1)[0][0]
    if st=="minority":
        from collections import Counter;return Counter(floats).most_common()[-1][0]
    if st=="variety":return len(set(floats))
    if st=="unique":return sorted(set(floats))
    if st=="values":return floats
    if st=="frac":return len(vals)/(ds.width*ds.height) if ds else None
    if st in ("center_x","center_y","min_center_x","min_center_y","max_center_x","max_center_y"):
        if st.startswith("min_"):target=min(vals,key=lambda t:t[0])
        elif st.startswith("max_"):target=max(vals,key=lambda t:t[0])
        else:target=vals[len(vals)//2]
        geo=_geo_transform_point(ds,target[1]+0.5,target[2]+0.5)
        return geo[0] if st.endswith("_x") else geo[1]
    if st.startswith("weighted_"):
        return _compute_zone_stat(st.replace("weighted_",""),vals,ds)
    if st=="weights":return len(vals)
    return None
