            if path[-1] in ("as-features","contour","footprint","index","polygonize","zonal-stats"):return "vector"
            return "raster"
        if len(path)>=3 and path[1]=="vector":
            if path[-1] in ("rasterize",) or path[2]=="grid":return "raster"
            return "vector"
        return self.current_kind

    def _invoke_standalone_with_node(self,node,args,expected_kind,generation=False,final_write_like=False):
        # Determine synthetic tokens based on node positional names.
        positionals=list(node.positional)
        # Determine handler
