    def _invoke_via_serialized(self,node,args,expected_kind,generation=False):
        # Find matching step spec for this standalone node and pipeline type
        info_name=node.path[-1]
        # special grid/overview node mapping in serialize: node path may be vector grid avg etc
        if node.path[:3]==("gdal","vector","grid"):
            step_name="grid";sub=node.path[-1]
            # args are step args after subname removed in caller for grid
        else:
            step_name=info_name
        specs=[s for s in stepspec.get_step_specs(self.pipeline_key) if s.name==step_name]
        # Select spec whose URL points to this node or kind matches
        spec_obj=None
        for s in specs:
            node_url=node.json_obj.get("url") or ""
            if s.entry.get("url")==node_url:spec_obj=s;break
        if spec_obj is None and specs:spec_obj=specs[0]
        if spec_obj is None:
            raise PipeError(f"ERROR 1: pipeline: unknown step name: {step_name}\n"+_usage(self.invoked_path),code=1)
        step_parsed=self._parse_with_spec(spec_obj,args)
        # Build synthetic standalone token list
        syn=[]
        temp_out=self._temp_path(expected_kind)
        temp_in=None
        if not generation:
            temp_in=self._write_temp_to_path(self.current_ds)
        # Determine positional handling
        standalone_pos=node.positional
        extra_positional_values=[]
        # Step positional values are those in step spec positional not input/output.
        for pcan in spec_obj.positional:
            if pcan in ("input","output"):continue
            if pcan in step_parsed.specified:
                val=step_parsed.values.get(pcan)
                if isinstance(val,list):extra_positional_values.extend([str(v) for v in val])
                else:extra_positional_values.append(str(val))
        # Synthetic order: options from step parsed first? Standalone parser allows any ordering. We'll construct positional tokens in standalone order, then options.
        pos_tokens=[]
        for pcan in standalone_pos:
            if pcan=="input":
                if generation:
                    # Values from step parsed input
                    vals=step_parsed.values.get("input") or []
                    if isinstance(vals,list):pos_tokens.extend([str(v) for v in vals])
                    else:pos_tokens.append(str(vals))
                else:
                    pos_tokens.append(temp_in)
            elif pcan=="output":
                # For standalone create vector step handled direct (not here), for edit raster dataset pcan below.
                pos_tokens.append(temp_out)
            elif pcan=="dataset":
                pos_tokens.append(temp_in)
            elif pcan in ("reference",):
                vals=step_parsed.values.get(pcan);pos_tokens.append(str(vals))
            else:
                # consume one extra positional if available
                if extra_positional_values:pos_tokens.append(extra_positional_values.pop(0))
        # Options serialized from step_parsed specified in spec order, skip input/output and positional names
        option_tokens=[]
        skip=set(spec_obj.positional)|{"help","json-usage","config"}
        for can in spec_obj.args.keys():
            if can in skip:continue
            if can not in step_parsed.specified:continue
            # Find canonical alias in standalone node for this arg if exists; if standalone doesn't have it, pass step canonical anyway (parser may error appropriately)
            val=step_parsed.values.get(can);speca=spec_obj.args[can]
            opt="--"+can
