                if val:option_tokens.append(opt)
                continue
            if speca.is_list:
                if speca.type in ("integer_list","real_list"):
                    if val:option_tokens.extend([opt,",".join(str(v) for v in val)])
                else:
                    for v in val or []:option_tokens.extend([opt,str(v)])
            else:
                option_tokens.extend([opt,str(val)])
        syn_tokens=pos_tokens+option_tokens+extra_positional_values
        # Add quiet if standalone supports it and not already
        if "quiet" in node.args and "--quiet" not in syn_tokens and "-q" not in syn_tokens:
            syn_tokens=["--quiet"]+syn_tokens
        if "overwrite" in node.args:
            syn_tokens=["--overwrite"]+syn_tokens
        # Parse and call
        from cli import Call
        parser=ArgParser(node,node.path)
        try:sparsed=parser.parse(syn_tokens)
        except ParseError as ex:
            msg=ex.message
            if "\nUsage:" in msg:msg=msg.split("\nUsage:")[0]+"\n"+_usage(self.invoked_path)
            raise PipeError(msg,code=ex.code)
        call=Call(sparsed,node,node.path)
        # Transform certain ParseError usages from handler to pipeline usage
        import operations
        handler=operations.HANDLERS.get(tuple(node.path))
        try:
            rc=handler(call)
        except ParseError as ex:
            msg=ex.message
            if "\nUsage:" in msg:
                msg=msg.split("\nUsage:")[0]+"\n"+_usage(self.invoked_path)
            raise PipeError(msg,code=ex.code,stdout=getattr(ex,"stdout",""))
        # Determine if handler was an in-place operation (raster edit / overview / vector sql with no output) - output file is temp_in in that case; our temp_out might not exist.
        result_path=temp_out
        if not vfs.exists(str(result_path)):
            result_path=temp_in
        if result_path and vfs.exists(str(result_path)):
            # Open result
            if expected_kind=="raster":
                from rasterio import open_raster_dataset;ds=open_raster_dataset(str(result_path))
            else:
                from vectorio import open_vector_dataset;ds=open_vector_dataset(str(result_path))
            # Streamed dataset identity adjustments for raster: Driver becomes VRT if a processing step (not read/create) in original. For steps that are materialized through a temp GTiff, mimic by setting driver to VRT and files to original current files if current was from a file.
            if expected_kind=="raster" and not generation:
                prev_files=list(self.current_ds.files) if self.current_ds else []
                ds.driver_short="VRT";ds.driver_long="Virtual Raster";ds.description=self.current_ds.description if self.current_ds else "";ds.files=prev_files
            elif expected_kind=="vector" and not generation:
                ds._stream_processed=True
                if self.current_ds:
                    ds.description=self.current_ds.description
            self.current_ds=ds;self.current_kind=expected_kind
        return rc

